
        function showAdminSessionGate(message) {
            document.body.classList.add('admin-access-denied');
            const gate = document.getElementById('adminSessionGate');
            const msgEl = document.getElementById('adminSessionGateMsg');
            if (msgEl && message) msgEl.textContent = message;
            if (gate) gate.classList.add('is-visible');
        }

        function goToMainAdminLogin() {
            window.location.replace('index.html?adminLogin=1');
        }

        function closeAdminPanelWindow() {
            try {
                if (window.opener && !window.opener.closed) {
                    window.close();
                    return;
                }
            } catch (_) {}
            window.location.replace('index.html');
            setTimeout(function () {
                try {
                    window.close();
                } catch (_) {}
            }, 400);
        }

        function showAdminCopyableDialog(title, text) {
            const dlg = document.getElementById('adminCopyableDialog');
            const titleEl = document.getElementById('adminCopyableDialogTitle');
            const textEl = document.getElementById('adminCopyableDialogText');
            if (!dlg || !textEl) {
                alert(String(title || '') + '\n\n' + String(text || ''));
                return;
            }
            if (titleEl) titleEl.textContent = title || 'Mensaje';
            textEl.value = String(text || '');
            dlg.classList.add('is-open');
            try {
                textEl.focus();
                textEl.select();
            } catch (_) {}
        }

        function closeAdminCopyableDialog() {
            const dlg = document.getElementById('adminCopyableDialog');
            if (dlg) dlg.classList.remove('is-open');
        }

        async function adminCopyDialogToClipboard() {
            const textEl = document.getElementById('adminCopyableDialogText');
            const text = textEl ? textEl.value : '';
            try {
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    await navigator.clipboard.writeText(text);
                    alert('✅ Texto copiado al portapapeles.');
                    return;
                }
            } catch (_) {}
            try {
                textEl.focus();
                textEl.select();
                document.execCommand('copy');
                alert('✅ Texto copiado (selección manual).');
            } catch (e) {
                alert('Selecciona el texto con el ratón y pulsa Ctrl+C.');
            }
        }

        window.showAdminCopyableDialog = showAdminCopyableDialog;
        window.closeAdminCopyableDialog = closeAdminCopyableDialog;
        window.adminCopyDialogToClipboard = adminCopyDialogToClipboard;

        async function verifyFirebaseAdminSession() {
            if (window.__CDSAN_FILE_PROTOCOL__ || location.protocol === 'file:') {
                showAdminSessionGate('El panel de administración requiere la web publicada del club (HTTPS), no un archivo local.');
                return false;
            }
            if (typeof window.waitForFirebaseReady === 'function') {
                const ready = await window.waitForFirebaseReady(20000);
                if (!ready.ok) {
                    showAdminSessionGate('No se pudo conectar con la nube. Abre la web del club, inicia sesión como administrador y vuelve a abrir el panel.');
                    return false;
                }
            }
            if (!window.firebaseAuth || window.firebaseAuth.isSimulation) {
                return true;
            }

            const waitAuth =
                typeof window.waitForFirebaseAuthUser === 'function'
                    ? window.waitForFirebaseAuthUser
                    : function () {
                          return Promise.resolve(window.firebaseAuth.currentUser || null);
                      };
            const user = await waitAuth(12000);

            if (!user) {
                if (window.AdminSession && window.AdminSession.clearStoredAdminSession) {
                    window.AdminSession.clearStoredAdminSession();
                } else {
                    localStorage.removeItem('currentAdmin');
                    localStorage.removeItem('adminUser');
                }
                showAdminSessionGate(
                    'Sesión caducada o no iniciada. Vuelve a la página principal e inicia sesión como administrador.'
                );
                return false;
            }

            if (
                !window.AdminSession
                || typeof window.AdminSession.isAdminAuthenticated !== 'function'
                || !window.AdminSession.isAdminAuthenticated()
            ) {
                showAdminSessionGate(
                    'Acceso al panel solo tras iniciar sesión con contraseña en la web principal (botón Admin).'
                );
                return false;
            }
            try {
                const { doc, getDoc } = await import('https://www.gstatic.com/firebasejs/10.12.3/firebase-firestore.js');
                const col = (window.DB_COLLECTIONS && window.DB_COLLECTIONS.ADMINS) || 'sanabria_admins';
                const snap = await getDoc(doc(window.firebaseDb, col, user.uid));
                if (!snap.exists()) {
                    showAdminSessionGate('Tu usuario no tiene permisos de administrador en la nube del club.');
                    return false;
                }
                const d = snap.data() || {};
                const isOrganizer = d.role === 'competition_organizer'
                    || (window.AdminOrganizerAccess && window.AdminOrganizerAccess.isOrganizerFirestoreDoc(d));
                const isFullAdmin =
                    d.isAdmin === true
                    || d.isSuperAdmin === true
                    || d.role === 'admin'
                    || d.role === 'super_admin';
                const ok = d.appScope === 'cdsanabriacf' && (isFullAdmin || isOrganizer);
                if (!ok) {
                    showAdminSessionGate('Sin permisos de administrador u organizador en la nube del club.');
                    return false;
                }
                if (isOrganizer) {
                    try {
                        const cur = JSON.parse(localStorage.getItem('currentAdmin') || '{}');
                        cur.role = 'competition_organizer';
                        cur.isAdmin = false;
                        localStorage.setItem('currentAdmin', JSON.stringify(cur));
                        localStorage.setItem('adminUser', JSON.stringify(cur));
                    } catch (_) {}
                }
                return true;
            } catch (e) {
                console.warn('verifyFirebaseAdminSession:', e);
                showAdminSessionGate('No se pudo verificar la sesión de administrador en la nube.');
                return false;
            }
        }

        document.addEventListener('DOMContentLoaded', async function() {
            console.log('🔍 Cargando panel de administración CDSANABRIACF...');
            const firebaseOk = await verifyFirebaseAdminSession();
            if (!firebaseOk) return;
            checkAdminSession();
            checkAdminPermissions();
            if (window.AdminOrganizerAccess && window.AdminOrganizerAccess.isCompetitionOrganizer()) {
                window.AdminOrganizerAccess.applyNavRestrictions();
                window.AdminOrganizerAccess.applyCompetitionTabChrome();
            }
            checkExpiredMembers(); // Verificar socios expirados al cargar
            checkAutomaticSeasonRenewal(); // Renovación automática tras 31/05 (Firebase)
            cargarConfiguracionTienda(); // Cargar configuración de tienda
            
            // Abrir pestaña si viene desde enlace de la web principal
            const savedTab = localStorage.getItem('adminActiveTab');
            const isOrganizer = window.AdminOrganizerAccess && window.AdminOrganizerAccess.isCompetitionOrganizer();
            if (isOrganizer) {
                localStorage.removeItem('adminActiveTab');
                if (window.AdminOrganizerAccess && window.AdminOrganizerAccess.activateOrganizerCompeticionesTab) {
                    window.AdminOrganizerAccess.activateOrganizerCompeticionesTab();
                } else {
                    showTab('competiciones');
                }
                if (typeof loadCompetitionsList === 'function') loadCompetitionsList();
            } else if (savedTab) {
                console.log('📂 Abriendo pestaña desde enlace:', savedTab);
                setTimeout(() => {
                    showTab(savedTab);
                    localStorage.removeItem('adminActiveTab'); // Limpiar para futuras cargas
                }, 500);
            }
            
            // También verificar hash de la URL
            const hash = window.location.hash.replace('#', '');
            if (!isOrganizer && hash && !savedTab) {
                console.log('📂 Abriendo pestaña desde hash URL:', hash);
                setTimeout(() => {
                    showTab(hash);
                }, 500);
            }

            // Reconciliación al abrir: solo el resumen final (sin otros avisos previos).
            setTimeout(() => {
                intentarReconciliacionAutomaticaAlAbrir().catch((err) => {
                    console.warn('No se pudo ejecutar reconciliación automática al abrir:', err);
                });
            }, 1200);

            window.addEventListener('clubMediaUpdated', function () {
                try { if (typeof renderMultimediaAdminList === 'function') renderMultimediaAdminList(); } catch (_) {}
            });
            window.addEventListener('settingsBlobUpdated', function () {
                try { if (typeof cargarConfiguracionTienda === 'function') cargarConfiguracionTienda(); } catch (_) {}
            });
        });

        // Función para verificar sesión de administrador
        function checkAdminSession() {
            try {
                const currentAdmin = JSON.parse(localStorage.getItem('currentAdmin') || '{}');
                
                if (!currentAdmin.email) {
                    showAdminSessionGate('Sesión de administrador no válida. Inicia sesión desde la web principal.');
                    return false;
                }
                
                console.log('✅ Sesión de administrador verificada:', currentAdmin.email);
                
                // Actualizar información en pantalla con indicador de permisos (sin mostrar email)
                const adminInfo = document.getElementById('currentAdminInfo');
                if (adminInfo) {
                    if (window.AdminOrganizerAccess && window.AdminOrganizerAccess.isCompetitionOrganizer(currentAdmin)) {
                        adminInfo.textContent =
                            '🏆 ' + (currentAdmin.name || 'Organizador/a') + ' · Solo competiciones (campeonatos F7)';
                    } else {
                    const isPrincipal = currentAdmin.email === 'amco@gmx.es';
                    const isSecondAdmin = currentAdmin.email === 'cdsanabriafc@gmail.com';
                    
                    // Ocultar información del administrador principal
                    if (isPrincipal) {
                        adminInfo.textContent = '👤 Administrador Autorizado (Permisos completos)';
                    } else {
                        const roleText = isSecondAdmin ? '👨‍💼 SEGUNDO' : '👨‍💼 SECUNDARIO';
                        const permissionText = isSecondAdmin ? '(Permisos completos)' : '(Sin gestión de admins)';
                        adminInfo.textContent = `👤 ${currentAdmin.name || 'Administrador/a'} · ${roleText} · ${permissionText}`;
                    }
                    }
                }
                
                return true;
            } catch (error) {
                console.error('❌ Error verificando sesión:', error);
                showAdminSessionGate('Error de sesión de administrador. Vuelve a iniciar sesión en la web principal.');
                return false;
            }
        }

        // Función legacy (mantenida por compatibilidad). La activa está al final del archivo.
        function showTabLegacy(tabName) {
            try {
                console.log('📂 Cambiando a pestaña:', tabName);
                
                // Ocultar todos los contenidos de pestañas
                const tabContents = document.querySelectorAll('.tab-content');
                tabContents.forEach(content => content.classList.remove('active'));
                
                // Remover clase active de todos los botones
                const navTabs = document.querySelectorAll('.nav-tab');
                navTabs.forEach(tab => tab.classList.remove('active'));
                
                // Mostrar el contenido de la pestaña seleccionada
                const targetTab = document.getElementById(tabName);
                if (targetTab) {
                    targetTab.classList.add('active');
                }
                
                // Marcar el botón como activo
                const buttons = document.querySelectorAll('.nav-tab');
                buttons.forEach(button => {
                    if (button.textContent.includes(getTabDisplayName(tabName))) {
                        button.classList.add('active');
                    }
                });
                
                console.log('✅ Pestaña cambiada exitosamente:', tabName);
            } catch (error) {
                console.error('❌ Error cambiando pestaña:', error);
            }
        }

