        function deleteAdmin(adminId) {
            // Verificar permisos
            const currentAdmin = JSON.parse(localStorage.getItem('currentAdmin') || '{}');
            if (currentAdmin.email !== 'amco@gmx.es') {
                alert('❌ Solo el administrador principal puede eliminar otros administradores');
                return;
            }
            
            if (confirm('¿Estás seguro de que quieres eliminar este administrador?\n\n⚠️ Esta acción no se puede deshacer.')) {
                try {
                    const admins = JSON.parse(localStorage.getItem('cdsanabriacfTeamAdmins') || '[]');
                    const adminToDelete = admins.find(admin => admin.id === adminId);
                    
                    if (adminToDelete) {
                        const updatedAdmins = admins.filter(admin => admin.id !== adminId);
                        localStorage.setItem('cdsanabriacfTeamAdmins', JSON.stringify(updatedAdmins));

                        loadAdminsList();
                        alert('✅ Administrador "' + adminToDelete.name + '" eliminado correctamente');
                        console.log('🗑️ Administrador eliminado:', adminToDelete.name, 'ID:', adminId);
                    }
                } catch (error) {
                    console.error('❌ Error eliminando administrador:', error);
                    alert('❌ Error al eliminar el administrador');
                }
            }
        }

        // === MÓDULO DE JUGADORES ===

        let __adminEditingPlayerId = null;

        function findPlayerIndexById(players, playerId) {
            return (players || []).findIndex(function (p) {
                return String(p.id) === String(playerId);
            });
        }

        function findPlayerByIdLocal(playerId) {
            let players = [];
            try {
                players = JSON.parse(localStorage.getItem('clubPlayers') || '[]');
            } catch (_) {
                players = [];
            }
            const ix = findPlayerIndexById(players, playerId);
            if (ix >= 0) return players[ix];
            if (window.ClubPlayerMemberSync && window.ClubPlayerMemberSync.globalPlayerIdentityKey) {
                const targetKey = String(playerId || '').trim();
                const byKey = players.find(function (p) {
                    return window.ClubPlayerMemberSync.globalPlayerIdentityKey(p) === targetKey;
                });
                if (byKey) return byKey;
            }
            return null;
        }

        function jsPlayerIdArg(playerId) {
            return JSON.stringify(String(playerId || ''));
        }

        function setPlayerFormMode(mode) {
            const form = document.getElementById('addPlayerForm');
            if (!form) return;
            const title = form.querySelector('h4');
            const saveBtn = form.querySelector('button.btn-success');
            if (mode === 'edit') {
                if (title) title.textContent = '✏️ Editar Jugador/a';
                if (saveBtn) saveBtn.textContent = '💾 Guardar cambios';
            } else {
                if (title) title.textContent = '📝 Registrar Nuevo Jugador';
                if (saveBtn) saveBtn.textContent = '💾 Guardar Jugador';
            }
        }
        
