        // Función para mostrar formulario de crear equipo
        function showAddTeamForm() {
            document.getElementById('addTeamForm').style.display = 'block';
            setupTeamCrestPreview();
            document.getElementById('addTeamForm').scrollIntoView({ behavior: 'smooth' });
        }

        function setupTeamCrestPreview() {
            const input = document.getElementById('teamCrest');
            const preview = document.getElementById('teamCrestPreview');
            if (!input || !preview) return;
            input.onchange = function(e) {
                const file = e.target.files && e.target.files[0];
                if (!file) {
                    preview.innerHTML = '';
                    return;
                }
                if (!String(file.type || '').startsWith('image/')) {
                    alert('❌ El escudo debe ser una imagen.');
                    input.value = '';
                    preview.innerHTML = '';
                    return;
                }
                const reader = new FileReader();
                reader.onload = function(ev) {
                    preview.innerHTML = `<img src="${ev.target.result}" alt="Preview escudo" style="width:42px; height:42px; object-fit:cover; border-radius:50%; border:1px solid #cbd5e1;">`;
                };
                reader.readAsDataURL(file);
            };
        }

