        function cancelAddTeam() {
            document.getElementById('addTeamForm').style.display = 'none';
            clearTeamForm();
        }

        // Función para limpiar formulario de equipo
        function clearTeamForm() {
            const form = document.getElementById('addTeamForm');
            const inputs = form.querySelectorAll('input, select');
            inputs.forEach(input => {
                if (input.type === 'checkbox') {
                    input.checked = false;
                } else {
                    input.value = '';
                }
            });
            document.getElementById('teamStatus').value = 'active';
            const crestPreview = document.getElementById('teamCrestPreview');
            if (crestPreview) crestPreview.innerHTML = '';
        }

        // Función para guardar equipo
        async function saveTeam() {
            try {
                const teamCrestInput = document.getElementById('teamCrest');
                const crestFile = teamCrestInput?.files?.[0] || null;
                let crestData = '';
                if (crestFile) {
                    if (!String(crestFile.type || '').startsWith('image/')) {
                        alert('❌ El escudo debe ser una imagen válida.');
                        return;
                    }
                    if (crestFile.size > 5 * 1024 * 1024) {
                        alert('❌ El escudo supera el tamaño máximo de 5MB.');
                        return;
                    }
                    crestData = await readFileAsDataURL(crestFile);
                }

                const teamData = {
                    id: 'TEAM_' + Date.now(),
                    name: document.getElementById('teamName').value.trim(),
                    category: document.getElementById('teamCategory').value,
                    coach: document.getElementById('teamCoach').value.trim(),
                    field: document.getElementById('teamField').value.trim(),
                    schedule: document.getElementById('teamSchedule').value.trim(),
                    status: document.getElementById('teamStatus').value,
                    crest: crestData,
                    createdAt: new Date().toISOString(),
                    createdBy: JSON.parse(localStorage.getItem('currentAdmin') || '{}').email || 'admin'
                };

                // Validar campos obligatorios
                if (!teamData.name || !teamData.category) {
                    alert('❌ Por favor, completa todos los campos obligatorios marcados con *');
                    return;
                }

                // Guardar en localStorage
                const teams = JSON.parse(localStorage.getItem('clubTeams') || '[]');
                teams.push(teamData);
                localStorage.setItem('clubTeams', JSON.stringify(teams));
                await persistRecordToFirebase('clubTeams', 'teams', teamData);

                alert('✅ Equipo creado exitosamente\n\n🏆 ' + teamData.name + '\n📋 Categoría: ' + teamData.category + '\n👨‍💼 Estado: ' + (teamData.status === 'active' ? 'Activo' : 'Inactivo'));
                
                cancelAddTeam();
                loadTeamsCards();
                updateDashboardCounts();

                console.log('🏆 Nuevo equipo creado:', teamData.name);
            } catch (error) {
                console.error('❌ Error guardando equipo:', error);
                alert('❌ Error al crear el equipo. Inténtalo de nuevo.');
            }
        }

        // Función para cargar tarjetas de equipos
        function loadTeamsCards() {
            try {
                const teams = JSON.parse(localStorage.getItem('clubTeams') || '[]');
                const players = JSON.parse(localStorage.getItem('clubPlayers') || '[]');
                const teamsCards = document.getElementById('teamsCards');
                
                // Si no hay equipos personalizados, mostrar las categorías por defecto
                if (teams.length === 0) {
                    const defaultCategories = [
                        { key: 'prebenajmin', name: 'Prebenjamín', age: '6-8 años' },
                        { key: 'benjamin', name: 'Benjamín', age: '8-10 años' },
                        { key: 'alevin', name: 'Alevín', age: '10-12 años' },
                        { key: 'infantil', name: 'Infantil', age: '12-14 años' },
                        { key: 'cadete', name: 'Cadete', age: '14-16 años' },
                        { key: 'juvenil', name: 'Juvenil', age: '16-18 años' },
                        { key: 'aficionado', name: 'Aficionado', age: '18+ años' }
                    ];
                    
                    let html = '';
                    defaultCategories.forEach(category => {
                        const categoryPlayers = players.filter(player => player.category === category.key);
                        const activePlayers = categoryPlayers.filter(player => player.status === 'active');
                        
                        html += `
                            <div class="dashboard-card">
                                <h4>${category.name}</h4>
                                <p>Edad: ${category.age}</p>
                                <div class="number" id="${category.key}Count">${activePlayers.length}</div>
                                <p>jugadores activos</p>
                                <button class="btn" onclick="manageCategoryPlayers('${category.key}')">Gestionar</button>
                            </div>
                        `;
                    });
                    
                    teamsCards.innerHTML = html;
                } else {
                    // Mostrar equipos personalizados
                    let html = '';
                    teams.forEach(team => {
                        const teamPlayers = players.filter(player => player.category === team.category);
                        const activePlayers = teamPlayers.filter(player => player.status === 'active');
                        const statusColor = team.status === 'active' ? '#059669' : '#dc2626';
                        const statusText = team.status === 'active' ? 'Activo' : 'Inactivo';
                        
                        html += `
                            <div class="dashboard-card" style="position: relative;">
                                <div style="position: absolute; top: 10px; right: 10px;">
                                    <span style="background: ${statusColor}; color: white; padding: 2px 8px; border-radius: 10px; font-size: 0.8rem;">
                                        ${statusText}
                                    </span>
                                </div>
                                <h4>${team.name}</h4>
                                ${team.crest ? `<div style="margin: 8px 0;"><img src="${team.crest}" alt="Escudo ${team.name}" style="width:40px; height:40px; object-fit:cover; border-radius:50%; border:1px solid #cbd5e1;"></div>` : ''}
                                <p>Categoría: ${team.category}</p>
                                ${team.coach ? `<p>👨‍💼 ${team.coach}</p>` : ''}
                                <div class="number">${activePlayers.length}</div>
                                <p>jugadores activos</p>
                                <div style="display: flex; gap: 5px; margin-top: 10px;">
                                    <button class="btn" onclick="manageCategoryPlayers('${team.category}')" style="flex: 1;">Gestionar</button>
                                    <button onclick="changeTeamCrest('${team.id}')" style="padding: 5px 10px; background: #1d4ed8; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">
                                        🛡️ Escudo
                                    </button>
                                    <button onclick="removeTeamCrest('${team.id}')" style="padding: 5px 10px; background: #64748b; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">
                                        🗑️ Quitar
                                    </button>
                                    <button onclick="toggleTeamStatus('${team.id}')" style="padding: 5px 10px; background: ${team.status === 'active' ? '#dc2626' : '#059669'}; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">
                                        ${team.status === 'active' ? '❌ Deshabilitar' : '✅ Habilitar'}
                                    </button>
                                </div>
                            </div>
                        `;
                    });
                    
                    teamsCards.innerHTML = html;
                }
                
                console.log('🏆 Tarjetas de equipos cargadas:', teams.length, 'equipos');
            } catch (error) {
                console.error('❌ Error cargando tarjetas de equipos:', error);
            }
        }

        // Función para cambiar estado del equipo
        async function toggleTeamStatus(teamId) {
            try {
                const teams = JSON.parse(localStorage.getItem('clubTeams') || '[]');
                const teamIndex = teams.findIndex(team => team.id === teamId);
                
                if (teamIndex !== -1) {
                    const currentStatus = teams[teamIndex].status;
                    const newStatus = currentStatus === 'active' ? 'inactive' : 'active';
                    
                    teams[teamIndex].status = newStatus;
                    localStorage.setItem('clubTeams', JSON.stringify(teams));
                    await persistRecordToFirebase('clubTeams', 'teams', teams[teamIndex]);
                    
                    loadTeamsCards();
                    
                    const statusText = newStatus === 'active' ? 'habilitado' : 'deshabilitado';
                    alert(`✅ Equipo "${teams[teamIndex].name}" ${statusText} correctamente`);
                    
                    console.log('🏆 Estado del equipo cambiado:', teams[teamIndex].name, '->', newStatus);
                }
            } catch (error) {
                console.error('❌ Error cambiando estado del equipo:', error);
                alert('❌ Error al cambiar el estado del equipo');
            }
        }

        async function syncTeamCrestInCompetitions(teamId, crestData) {
            const competitions = JSON.parse(localStorage.getItem('clubCompetitions') || '[]');
            let changed = 0;
            for (const competition of competitions) {
                if (!Array.isArray(competition.teams) || !competition.teams.length) continue;
                let localChanged = false;
                competition.teams = competition.teams.map((team) => {
                    if (String(team.id) === String(teamId)) {
                        localChanged = true;
                        return { ...team, crest: crestData || '' };
                    }
                    return team;
                });
                if (localChanged) {
                    changed += 1;
                    competition.updatedAt = new Date().toISOString();
                    try {
                        await persistRecordToFirebase('clubCompetitions', 'competitions', competition);
                    } catch (error) {
                        console.warn('No se pudo sincronizar escudo en competición:', competition.id, error);
                    }
                }
            }
            if (changed > 0) {
                localStorage.setItem('clubCompetitions', JSON.stringify(competitions));
            }
        }

        function changeTeamCrest(teamId) {
            try {
                const teams = JSON.parse(localStorage.getItem('clubTeams') || '[]');
                const teamIndex = teams.findIndex(team => String(team.id) === String(teamId));
                if (teamIndex < 0) {
                    alert('❌ Equipo no encontrado');
                    return;
                }
                const team = teams[teamIndex];
                const input = document.createElement('input');
                input.type = 'file';
                input.accept = 'image/*';
                input.onchange = async (event) => {
                    try {
                        const file = event.target?.files?.[0];
                        if (!file) return;
                        if (!String(file.type || '').startsWith('image/')) {
                            alert('❌ Debes seleccionar una imagen válida para el escudo.');
                            return;
                        }
                        if (file.size > 5 * 1024 * 1024) {
                            alert('❌ El escudo supera el tamaño máximo de 5MB.');
                            return;
                        }
                        const crestData = await readFileAsDataURL(file);
                        teams[teamIndex].crest = crestData;
                        teams[teamIndex].updatedAt = new Date().toISOString();
                        localStorage.setItem('clubTeams', JSON.stringify(teams));
                        await persistRecordToFirebase('clubTeams', 'teams', teams[teamIndex]);
                        await syncTeamCrestInCompetitions(teamId, crestData);
                        loadTeamsCards();
                        loadCompetitionsList();
                        alert(`✅ Escudo actualizado para ${team.name}`);
                    } catch (error) {
                        console.error('❌ Error actualizando escudo del equipo:', error);
                        alert('❌ No se pudo actualizar el escudo del equipo.');
                    }
                };
                input.click();
            } catch (error) {
                console.error('❌ Error en cambio de escudo:', error);
                alert('❌ Error al cambiar el escudo del equipo.');
            }
        }

        async function removeTeamCrest(teamId) {
            try {
                const teams = JSON.parse(localStorage.getItem('clubTeams') || '[]');
                const teamIndex = teams.findIndex(team => String(team.id) === String(teamId));
                if (teamIndex < 0) {
                    alert('❌ Equipo no encontrado');
                    return;
                }
                const team = teams[teamIndex];
                if (!team.crest) {
                    alert('ℹ️ Este equipo no tiene escudo asignado.');
                    return;
                }
                if (!confirm(`¿Quitar el escudo de ${team.name}?`)) return;

                teams[teamIndex].crest = '';
                teams[teamIndex].updatedAt = new Date().toISOString();
                localStorage.setItem('clubTeams', JSON.stringify(teams));
                await persistRecordToFirebase('clubTeams', 'teams', teams[teamIndex]);
                await syncTeamCrestInCompetitions(teamId, '');
                loadTeamsCards();
                loadCompetitionsList();
                alert(`✅ Escudo eliminado de ${team.name}`);
            } catch (error) {
                console.error('❌ Error eliminando escudo del equipo:', error);
                alert('❌ No se pudo eliminar el escudo del equipo.');
            }
        }

        // === MÓDULO DE EVENTOS ===
        window.__eventEditingId = null;

        function toggleEventFreePaymentUI() {
            const free = !!document.getElementById('eventIsFree')?.checked;
            const wrap = document.getElementById('eventPaymentMethodsWrap');
            if (wrap) wrap.style.opacity = free ? '0.45' : '1';
            ['eventPayCard', 'eventPayBizum', 'eventPayTransfer'].forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.disabled = free;
            });
        }

        function toggleEventGuestsMaxUI() {
            const on = !!document.getElementById('eventAllowGuests')?.checked;
            const maxEl = document.getElementById('eventMaxGuests');
            if (maxEl) {
                maxEl.disabled = !on;
                if (on && (parseInt(maxEl.value, 10) || 0) < 1) maxEl.value = '1';
                if (!on) maxEl.value = '0';
            }
        }

        function normalizeEventDni(value) {
            return String(value || '').trim().toUpperCase().replace(/[^0-9A-Z]/g, '');
        }

        function normalizeLegacyEvent(event) {
            const safe = { ...(event || {}) };
            const basePrice = Number(safe.price || 0);
            safe.pricesByType = {
                socios: Number(safe.pricesByType?.socios ?? basePrice ?? 0),
                amigos: Number(safe.pricesByType?.amigos ?? basePrice ?? 0),
                jugadores: Number(safe.pricesByType?.jugadores ?? basePrice ?? 0),
                directiva: Number(safe.pricesByType?.directiva ?? basePrice ?? 0),
                entrenadores: Number(safe.pricesByType?.entrenadores ?? basePrice ?? 0),
                invitados: Number(safe.pricesByType?.invitados ?? safe.pricesByType?.invitado ?? basePrice ?? 0)
            };
            const allPricesZero = Object.values(safe.pricesByType).every((v) => Number(v) === 0);
            safe.isFreeEvent = safe.isFreeEvent === true || allPricesZero;
            safe.allowGuests = !!safe.allowGuests;
            safe.maxGuestsPerRegistration = Math.max(0, parseInt(safe.maxGuestsPerRegistration, 10) || 0);
            const pm = safe.paymentMethods && typeof safe.paymentMethods === 'object' ? safe.paymentMethods : {};
            if (safe.isFreeEvent) {
                safe.paymentMethods = {};
            } else if (!pm.card && !pm.bizum && !pm.transfer) {
                safe.paymentMethods = { card: true, bizum: false, transfer: true };
            } else {
                safe.paymentMethods = { card: !!pm.card, bizum: !!pm.bizum, transfer: !!pm.transfer };
            }
            safe.allowedGroups = safe.allowedGroups && typeof safe.allowedGroups === 'object'
                ? {
                    socios: !!safe.allowedGroups.socios,
                    amigos: !!safe.allowedGroups.amigos,
                    jugadores: !!safe.allowedGroups.jugadores,
                    directiva: !!safe.allowedGroups.directiva,
                    entrenadores: !!safe.allowedGroups.entrenadores
                }
                : {
                    socios: safe.allowedAudience !== 'amigos',
                    amigos: safe.allowedAudience !== 'socios',
                    jugadores: false,
                    directiva: false,
                    entrenadores: false
                };
            safe.playerScope = safe.playerScope || 'all';
            safe.allowedPlayerCategories = Array.isArray(safe.allowedPlayerCategories) ? safe.allowedPlayerCategories : [];
            safe.allowedAudience = 'custom';
            safe.participants = Array.isArray(safe.participants) ? safe.participants : (Array.isArray(safe.registeredMembers) ? safe.registeredMembers : []);
            safe.registeredMembers = safe.participants;
            safe.revenueDestination = safe.revenueDestination === 'B' ? 'B' : 'A';
            return safe;
        }

        function migrateLegacyEventsIfNeeded() {
            try {
                const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
                if (!Array.isArray(events) || !events.length) return;
                let changed = false;
                const normalized = events.map((event) => {
                    const next = normalizeLegacyEvent(event);
                    if (!event.pricesByType || !event.allowedGroups || event.allowedGroups.entrenadores === undefined || !Array.isArray(event.allowedPlayerCategories) || !Array.isArray(event.participants) || event.revenueDestination === undefined) {
                        changed = true;
                    }
                    return next;
                });
                if (changed) {
                    localStorage.setItem('clubEvents', JSON.stringify(normalized));
                    if (typeof window.syncLocalArrayKeyToFirebase === 'function') {
                        window.syncLocalArrayKeyToFirebase('clubEvents').catch(() => {});
                    }
                }
            } catch (error) {
                console.warn('No se pudo migrar eventos legacy:', error);
            }
        }
        
        function showAddEventForm() {
            document.getElementById('addEventForm').style.display = 'block';
            document.getElementById('addEventForm').scrollIntoView({ behavior: 'smooth' });
            const today = new Date();
            document.getElementById('eventDate').value = today.toISOString().split('T')[0];
            window.__eventEditingId = null;
            const allowSocios = document.getElementById('eventAllowSocios');
            const allowAmigos = document.getElementById('eventAllowAmigos');
            const allowJugadores = document.getElementById('eventAllowJugadores');
            const allowDirectiva = document.getElementById('eventAllowDirectiva');
            const allowEntrenadores = document.getElementById('eventAllowEntrenadores');
            if (allowSocios) allowSocios.checked = true;
            if (allowAmigos) allowAmigos.checked = true;
            if (allowJugadores) allowJugadores.checked = false;
            if (allowDirectiva) allowDirectiva.checked = false;
            if (allowEntrenadores) allowEntrenadores.checked = false;
            const scope = document.getElementById('eventPlayerScope');
            if (scope) scope.value = 'all';
            const rev = document.getElementById('eventRevenueDestination');
            if (rev) rev.value = 'A';
            const isFree = document.getElementById('eventIsFree');
            if (isFree) isFree.checked = false;
            const payCard = document.getElementById('eventPayCard');
            const payBizum = document.getElementById('eventPayBizum');
            const payTransfer = document.getElementById('eventPayTransfer');
            if (payCard) payCard.checked = true;
            if (payBizum) payBizum.checked = false;
            if (payTransfer) payTransfer.checked = true;
            const invPrice = document.getElementById('eventPriceInvitados');
            if (invPrice) invPrice.value = '0';
            const allowG = document.getElementById('eventAllowGuests');
            if (allowG) allowG.checked = false;
            const maxG = document.getElementById('eventMaxGuests');
            if (maxG) maxG.value = '0';
            toggleEventFreePaymentUI();
            toggleEventGuestsMaxUI();
        }

        function cancelAddEvent() {
            document.getElementById('addEventForm').style.display = 'none';
            window.__eventEditingId = null;
            clearEventForm();
        }

        function clearEventForm() {
            const form = document.getElementById('addEventForm');
            const inputs = form.querySelectorAll('input, textarea, select');
            inputs.forEach(input => {
                if (input.type === 'checkbox') {
                    input.checked = false;
                } else if (input.type === 'file') {
                    input.value = '';
                } else {
                    input.value = '';
                }
            });
            document.getElementById('eventImagePreview').style.display = 'none';
        }

        function getEventAllowedGroupsSummary(event) {
            const groups = event.allowedGroups || {
                socios: event.allowedAudience !== 'amigos',
                amigos: event.allowedAudience !== 'socios',
                jugadores: false,
                directiva: false,
                entrenadores: false
            };
            const list = [];
            if (groups.socios) list.push('socios/as');
            if (groups.amigos) list.push('amigos/as');
            if (groups.jugadores) list.push('jugadores/as');
            if (groups.directiva) list.push('directiva');
            if (groups.entrenadores) list.push('entrenadores/as');
            return list.length ? list.join(', ') : 'sin grupos habilitados';
        }

        function getEventPlayerScopeSummary(event) {
            const groups = event.allowedGroups || {};
            if (!groups.jugadores) return 'No aplica';
            if ((event.playerScope || 'all') !== 'categories') return 'Todos los jugadores/as';
            const categories = Array.isArray(event.allowedPlayerCategories) ? event.allowedPlayerCategories : [];
            return categories.length ? categories.join(', ') : 'Sin categorías';
        }

        function prefillEventFormFromTemplate(templateEvent) {
            const event = templateEvent || {};
            document.getElementById('eventName').value = (event.name || event.title || '') + ' (Copia)';
            document.getElementById('eventDate').value = event.date || '';
            document.getElementById('eventStartTime').value = event.startTime || '';
            document.getElementById('eventEndTime').value = event.endTime || '';
            document.getElementById('eventLocation').value = event.location || '';
            document.getElementById('eventDescription').value = event.description || '';
            const prices = event.pricesByType || { socios: event.price || 0, amigos: event.price || 0, jugadores: event.price || 0, directiva: event.price || 0, entrenadores: event.price || 0 };
            document.getElementById('eventPrice').value = Number(prices.socios || 0);
            document.getElementById('eventPriceAmigos').value = Number(prices.amigos || 0);
            document.getElementById('eventPriceJugadores').value = Number(prices.jugadores || 0);
            document.getElementById('eventPriceDirectiva').value = Number(prices.directiva || 0);
            const pe = document.getElementById('eventPriceEntrenadores');
            if (pe) pe.value = Number(prices.entrenadores || 0);
            document.getElementById('eventMinParticipants').value = Number(event.minParticipants || 1);
            document.getElementById('eventMaxParticipants').value = Number(event.maxParticipants || 1);
            document.getElementById('eventRegistrationStart').value = event.registrationStart || '';
            document.getElementById('eventRegistrationDeadline').value = event.registrationDeadline || '';
            document.getElementById('eventPhotoConsent').checked = !!event.photoConsent;
            document.getElementById('eventDataConsent').checked = !!event.dataConsent;

            const groups = event.allowedGroups || {
                socios: event.allowedAudience !== 'amigos',
                amigos: event.allowedAudience !== 'socios',
                jugadores: false,
                directiva: false,
                entrenadores: false
            };
            document.getElementById('eventAllowSocios').checked = !!groups.socios;
            document.getElementById('eventAllowAmigos').checked = !!groups.amigos;
            document.getElementById('eventAllowJugadores').checked = !!groups.jugadores;
            document.getElementById('eventAllowDirectiva').checked = !!groups.directiva;
            const ae = document.getElementById('eventAllowEntrenadores');
            if (ae) ae.checked = !!groups.entrenadores;
            document.getElementById('eventPlayerScope').value = event.playerScope || 'all';
            const revEl = document.getElementById('eventRevenueDestination');
            if (revEl) revEl.value = event.revenueDestination === 'B' ? 'B' : 'A';

            const selectedCategories = new Set(Array.isArray(event.allowedPlayerCategories) ? event.allowedPlayerCategories : []);
            document.querySelectorAll('.eventPlayerCategory').forEach((el) => {
                el.checked = selectedCategories.has(String(el.value || '').trim());
            });

            const preview = document.getElementById('eventImagePreview');
            const previewImg = document.getElementById('eventImagePreviewImg');
            if (event.image && preview && previewImg) {
                previewImg.src = event.image;
                preview.style.display = 'block';
            }
            const eNorm = normalizeLegacyEvent(event);
            const isFreeEl = document.getElementById('eventIsFree');
            if (isFreeEl) isFreeEl.checked = !!eNorm.isFreeEvent;
            const payCard = document.getElementById('eventPayCard');
            const payBizum = document.getElementById('eventPayBizum');
            const payTransfer = document.getElementById('eventPayTransfer');
            const pm = eNorm.paymentMethods || {};
            if (payCard) payCard.checked = !!pm.card;
            if (payBizum) payBizum.checked = !!pm.bizum;
            if (payTransfer) payTransfer.checked = !!pm.transfer;
            const invP = document.getElementById('eventPriceInvitados');
            if (invP) invP.value = Number(eNorm.pricesByType?.invitados ?? 0);
            const allowG = document.getElementById('eventAllowGuests');
            if (allowG) allowG.checked = !!eNorm.allowGuests;
            const maxG = document.getElementById('eventMaxGuests');
            if (maxG) maxG.value = Number(eNorm.maxGuestsPerRegistration || 0);
            toggleEventFreePaymentUI();
            toggleEventGuestsMaxUI();
        }

        function duplicateEvent(eventId) {
            try {
                const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
                const source = events.find((e) => e.id === eventId);
                if (!source) {
                    alert('❌ Evento no encontrado para duplicar');
                    return;
                }
                showAddEventForm();
                prefillEventFormFromTemplate(source);
                alert('✅ Evento duplicado en formulario. Cambia categoría/fecha u otros datos y pulsa "Crear Evento".');
            } catch (error) {
                console.error('❌ Error duplicando evento:', error);
                alert('❌ No se pudo duplicar el evento.');
            }
        }

        function saveEvent() {
            try {
                const priceSocios = parseFloat(document.getElementById('eventPrice').value);
                const priceAmigosRaw = document.getElementById('eventPriceAmigos').value;
                const priceJugadoresRaw = document.getElementById('eventPriceJugadores').value;
                const priceDirectivaRaw = document.getElementById('eventPriceDirectiva').value;
                const priceEntrenadoresRaw = document.getElementById('eventPriceEntrenadores')
                    ? document.getElementById('eventPriceEntrenadores').value
                    : '';
                const priceAmigos = priceAmigosRaw === '' ? priceSocios : parseFloat(priceAmigosRaw);
                const priceJugadores = priceJugadoresRaw === '' ? priceSocios : parseFloat(priceJugadoresRaw);
                const priceDirectiva = priceDirectivaRaw === '' ? priceSocios : parseFloat(priceDirectivaRaw);
                const priceEntrenadores = priceEntrenadoresRaw === '' ? priceSocios : parseFloat(priceEntrenadoresRaw);
                const allowedGroups = {
                    socios: !!document.getElementById('eventAllowSocios')?.checked,
                    amigos: !!document.getElementById('eventAllowAmigos')?.checked,
                    jugadores: !!document.getElementById('eventAllowJugadores')?.checked,
                    directiva: !!document.getElementById('eventAllowDirectiva')?.checked,
                    entrenadores: !!document.getElementById('eventAllowEntrenadores')?.checked
                };
                const playerScope = document.getElementById('eventPlayerScope')?.value || 'all';
                const allowedPlayerCategories = Array.from(document.querySelectorAll('.eventPlayerCategory:checked'))
                    .map((el) => String(el.value || '').trim())
                    .filter(Boolean);
                const editingId = window.__eventEditingId;
                let existingEvent = null;
                if (editingId) {
                    const currentEvents = JSON.parse(localStorage.getItem('clubEvents') || '[]');
                    existingEvent = currentEvents.find((e) => String(e.id) === String(editingId)) || null;
                }
                const eventData = {
                    id: editingId || ('EVENT_' + Date.now()),
                    name: document.getElementById('eventName').value.trim(),
                    title: document.getElementById('eventName').value.trim(),
                    date: document.getElementById('eventDate').value,
                    startTime: document.getElementById('eventStartTime').value,
                    endTime: document.getElementById('eventEndTime').value,
                    location: document.getElementById('eventLocation').value.trim(),
                    description: document.getElementById('eventDescription').value.trim(),
                    price: Number.isFinite(priceSocios) ? priceSocios : 0,
                    pricesByType: {
                        socios: Number.isFinite(priceSocios) ? priceSocios : 0,
                        amigos: Number.isFinite(priceAmigos) ? priceAmigos : (Number.isFinite(priceSocios) ? priceSocios : 0),
                        jugadores: Number.isFinite(priceJugadores) ? priceJugadores : (Number.isFinite(priceSocios) ? priceSocios : 0),
                        directiva: Number.isFinite(priceDirectiva) ? priceDirectiva : (Number.isFinite(priceSocios) ? priceSocios : 0),
                        entrenadores: Number.isFinite(priceEntrenadores) ? priceEntrenadores : (Number.isFinite(priceSocios) ? priceSocios : 0),
                        invitados: parseFloat(document.getElementById('eventPriceInvitados')?.value || '0') || 0
                    },
                    isFreeEvent: !!document.getElementById('eventIsFree')?.checked,
                    paymentMethods: {
                        card: !!document.getElementById('eventPayCard')?.checked,
                        bizum: !!document.getElementById('eventPayBizum')?.checked,
                        transfer: !!document.getElementById('eventPayTransfer')?.checked
                    },
                    allowGuests: !!document.getElementById('eventAllowGuests')?.checked,
                    maxGuestsPerRegistration: Math.max(0, parseInt(document.getElementById('eventMaxGuests')?.value || '0', 10) || 0),
                    minParticipants: parseInt(document.getElementById('eventMinParticipants').value),
                    maxParticipants: parseInt(document.getElementById('eventMaxParticipants').value),
                    registrationStart: document.getElementById('eventRegistrationStart').value,
                    allowedAudience: 'custom',
                    allowedGroups,
                    playerScope,
                    allowedPlayerCategories,
                    registrationDeadline: document.getElementById('eventRegistrationDeadline').value,
                    photoConsent: document.getElementById('eventPhotoConsent').checked,
                    dataConsent: document.getElementById('eventDataConsent').checked,
                    revenueDestination: document.getElementById('eventRevenueDestination')?.value === 'B' ? 'B' : 'A',
                    image: null, // Se manejará por separado
                    participants: Array.isArray(existingEvent?.participants) ? existingEvent.participants : [],
                    registeredMembers: Array.isArray(existingEvent?.registeredMembers) ? existingEvent.registeredMembers : [],
                    status: 'upcoming',
                    createdAt: existingEvent?.createdAt || new Date().toISOString(),
                    createdBy: existingEvent?.createdBy || JSON.parse(localStorage.getItem('currentAdmin') || '{}').email || 'admin',
                    updatedAt: new Date().toISOString()
                };

                // Validaciones
                if (!eventData.name || !eventData.date || !eventData.startTime || !eventData.endTime || !eventData.location || !eventData.description) {
                    alert('❌ Por favor, completa todos los campos obligatorios marcados con *');
                    return;
                }

                if (eventData.startTime >= eventData.endTime) {
                    alert('❌ La hora de fin debe ser posterior a la hora de inicio');
                    return;
                }

                if (eventData.minParticipants > eventData.maxParticipants) {
                    alert('❌ El mínimo de participantes no puede ser mayor que el máximo');
                    return;
                }

                if (eventData.registrationStart && eventData.registrationDeadline && eventData.registrationStart > eventData.registrationDeadline) {
                    alert('❌ El inicio de inscripción no puede ser posterior al fin de inscripción');
                    return;
                }
                if (Object.values(eventData.pricesByType).some((value) => Number(value) < 0 || Number.isNaN(Number(value)))) {
                    alert('❌ Los precios por tipo deben ser números válidos de 0 o más.');
                    return;
                }
                if (!Object.values(allowedGroups).some(Boolean)) {
                    alert('❌ Debes permitir al menos un grupo de inscripción.');
                    return;
                }
                if (allowedGroups.jugadores && playerScope === 'categories' && allowedPlayerCategories.length === 0) {
                    alert('❌ Si eliges jugadores/as por categorías, marca al menos una categoría.');
                    return;
                }
                const normalizedForSave = normalizeLegacyEvent(eventData);
                if (!normalizedForSave.isFreeEvent) {
                    const pm = normalizedForSave.paymentMethods || {};
                    if (!pm.card && !pm.bizum && !pm.transfer) {
                        alert('❌ Si el evento no es gratuito, marca al menos una forma de pago (tarjeta, Bizum o transferencia).');
                        return;
                    }
                }
                if (eventData.allowGuests && eventData.maxGuestsPerRegistration < 1) {
                    alert('❌ Si permites invitados, indica cuántos como máximo (1 o más).');
                    return;
                }
                Object.assign(eventData, {
                    isFreeEvent: normalizedForSave.isFreeEvent,
                    paymentMethods: normalizedForSave.paymentMethods,
                    allowGuests: eventData.allowGuests,
                    maxGuestsPerRegistration: eventData.maxGuestsPerRegistration
                });

                // Manejar imagen
                const imageFile = document.getElementById('eventImage').files[0];
                if (imageFile) {
                    const reader = new FileReader();
                    reader.onload = function(e) {
                        eventData.image = e.target.result;
                        saveEventToStorage(eventData).catch((err) => console.warn('No se pudo sincronizar evento en Firebase:', err));
                    };
                    reader.readAsDataURL(imageFile);
                } else {
                    saveEventToStorage(eventData).catch((err) => console.warn('No se pudo sincronizar evento en Firebase:', err));
                }

            } catch (error) {
                console.error('❌ Error guardando evento:', error);
                alert('❌ Error al crear el evento. Inténtalo de nuevo.');
            }
        }

        async function saveEventToStorage(eventData) {
            const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
            if (window.__eventEditingId) {
                const idx = events.findIndex((e) => String(e.id) === String(window.__eventEditingId));
                if (idx >= 0) {
                    events[idx] = { ...events[idx], ...eventData, id: events[idx].id };
                } else {
                    events.push(eventData);
                }
            } else {
                events.push(eventData);
            }
            localStorage.setItem('clubEvents', JSON.stringify(events));
            await persistRecordToFirebase('clubEvents', 'events', eventData);

            const prices = eventData.pricesByType || {};
            const formatPrice = (value) => Number(value || 0) === 0 ? 'Gratuito' : `${Number(value || 0).toFixed(2)}€`;
            alert(
                `✅ Evento creado exitosamente\n\n🎉 ${eventData.name}\n📆 ${eventData.date}\n` +
                `💰 Socios/as: ${formatPrice(prices.socios)}\n` +
                `💰 Amigos/as: ${formatPrice(prices.amigos)}\n` +
                `💰 Jugadores/as: ${formatPrice(prices.jugadores)}\n` +
                `💰 Directiva: ${formatPrice(prices.directiva)}\n` +
                `💰 Entrenadores/as: ${formatPrice(prices.entrenadores)}\n` +
                `💶 Ingresos evento → ${eventData.revenueDestination === 'B' ? 'B (efectivo)' : 'A (banco)'}\n` +
                `👥 ${eventData.minParticipants}-${eventData.maxParticipants} participantes`
            );
            
            window.__eventEditingId = null;
            cancelAddEvent();
            loadEventsList();
            updateDashboardCounts();

            console.log('🎉 Nuevo evento creado:', eventData.name);
        }

        function loadEventsList() {
            try {
                migrateLegacyEventsIfNeeded();
                const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
                const eventsList = document.getElementById('eventsList');
                
                if (events.length === 0) {
                    eventsList.innerHTML = '<p style="text-align: center; color: #666; padding: 20px;">No hay eventos creados aún.</p>';
                    return;
                }

                // Actualizar estado de eventos
                const now = new Date();
                events.forEach(event => {
                    const eventDate = new Date(event.date);
                    const eventEndTime = new Date(`${event.date}T${event.endTime}`);
                    
                    if (eventEndTime < now) {
                        event.status = 'finished';
                    } else if (eventDate.toDateString() === now.toDateString()) {
                        event.status = 'ongoing';
                    } else {
                        event.status = 'upcoming';
                    }
                });

                // Filtrar eventos
                const statusFilter = document.getElementById('eventStatusFilter').value;
                const typeFilter = document.getElementById('eventTypeFilter').value;
                
                const filteredEvents = events.filter(event => {
                    const statusMatch = statusFilter === 'all' || event.status === statusFilter;
                    const typeMatch = typeFilter === 'all' || 
                                    (typeFilter === 'free' && event.price === 0) || 
                                    (typeFilter === 'paid' && event.price > 0);
                    return statusMatch && typeMatch;
                }).sort((a, b) => new Date(a.date) - new Date(b.date));

                let html = '<div style="background: white; border-radius: 10px; padding: 15px;">';

                filteredEvents.forEach(event => {
                    const statusColors = { 'upcoming': '#f59e0b', 'ongoing': '#059669', 'finished': '#6c757d' };
                    const statusTexts = { 'upcoming': 'Próximo', 'ongoing': 'En Curso', 'finished': 'Finalizado' };
                    const prices = event.pricesByType || { socios: event.price || 0, amigos: event.price || 0, jugadores: event.price || 0, directiva: event.price || 0, entrenadores: event.price || 0 };
                    const formatPrice = (value) => Number(value || 0) === 0 ? 'Gratuito' : `${Number(value || 0).toFixed(2)}€`;
                    const participantsCount = event.participants ? event.participants.length : 0;
                    const availableSpots = event.maxParticipants - participantsCount;
                    const pendingEventPayments = countPendingEventPaymentBundles(event);
                    
                    html += `
                        <div style="border: 1px solid #e9ecef; border-radius: 10px; padding: 20px; margin-bottom: 15px; ${event.image ? 'display: flex; gap: 20px;' : ''}">
                            ${event.image ? `<div style="flex-shrink: 0;"><img src="${event.image}" style="width: 150px; height: 100px; object-fit: cover; border-radius: 8px;"></div>` : ''}
                            <div style="flex: 1;">
                                <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px;">
                                    <div>
                                        <h4 style="margin: 0 0 5px 0; color: #1e3a8a;">${event.name}</h4>
                                        <div style="font-size: 0.9em; color: #666; margin-bottom: 8px;">
                                            📅 ${new Date(event.date).toLocaleDateString()} | ⏰ ${event.startTime} - ${event.endTime} | 📍 ${event.location}
                                        </div>
                                        <div style="font-size: 0.9em; color: #666;">
                                            💰 Socios/as: ${formatPrice(prices.socios)} · Amigos/as: ${formatPrice(prices.amigos)} · Jugadores/as: ${formatPrice(prices.jugadores)} · Directiva: ${formatPrice(prices.directiva)} · Entrenadores/as: ${formatPrice(prices.entrenadores)} | 👥 ${participantsCount}/${event.maxParticipants} inscritos | ✅ ${availableSpots} plazas disponibles
                                        </div>
                                        <div style="font-size: 0.9em; color: #334155; margin-top: 4px;">
                                            🎯 Permitidos: ${getEventAllowedGroupsSummary(event)}
                                        </div>
                                        <div style="font-size: 0.9em; color: #334155; margin-top: 2px;">
                                            🧩 Jugadores/as: ${getEventPlayerScopeSummary(event)}
                                        </div>
                                    </div>
                                    <span style="background: ${statusColors[event.status]}; color: white; padding: 4px 8px; border-radius: 12px; font-size: 0.8rem;">
                                        ${statusTexts[event.status]}
                                    </span>
                                </div>
                                <p style="margin: 10px 0; color: #555; font-size: 0.9em;">${event.description}</p>
                                <div style="display: flex; gap: 10px; margin-top: 15px;">
                                    <button onclick="viewEventDetails('${event.id}')" style="padding: 6px 12px; background: #6c757d; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">👁️ Ver Detalles</button>
                                    <button onclick="manageEventParticipants('${event.id}')" style="padding: 6px 12px; background: #1e3a8a; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">👥 Participantes</button>
                                    ${pendingEventPayments > 0 ? `<button onclick="validateEventPaymentsMenu('${event.id}')" style="padding: 6px 12px; background: #059669; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;" title="Confirmar transferencia o efectivo recibido">✅ Validar pagos (${pendingEventPayments})</button>` : ''}
                                    <button onclick="exportEventParticipantsExcel('${event.id}')" style="padding: 6px 12px; background: #166534; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">📊 Excel</button>
                                    <button onclick="exportEventParticipantsCSV('${event.id}')" style="padding: 6px 12px; background: #8b5cf6; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">📄 CSV</button>
                                    <button onclick="exportEventParticipantsWord('${event.id}')" style="padding: 6px 12px; background: #0ea5e9; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">📝 Word</button>
                                    <button onclick="exportEventParticipantsPdf('${event.id}')" style="padding: 6px 12px; background: #b45309; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">🖨️ PDF</button>
                                    <button onclick="duplicateEvent('${event.id}')" style="padding: 6px 12px; background: #4f46e5; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">📑 Duplicar</button>
                                    <button onclick="editEvent('${event.id}')" style="padding: 6px 12px; background: #059669; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">✏️ Editar</button>
                                    <button onclick="deleteEvent('${event.id}')" style="padding: 6px 12px; background: #dc2626; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">🗑️ Eliminar</button>
                                </div>
                            </div>
                        </div>
                    `;
                });

                html += '</div>';
                eventsList.innerHTML = html;
                
                // Guardar eventos actualizados
                localStorage.setItem('clubEvents', JSON.stringify(events));
                
                console.log('🎉 Lista de eventos cargada:', filteredEvents.length, 'eventos');
            } catch (error) {
                console.error('❌ Error cargando lista de eventos:', error);
            }
        }

        function filterEvents() {
            loadEventsList();
        }

        function viewEventDetails(eventId) {
            const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
            const event = events.find(e => e.id === eventId);
            
            if (event) {
                const prices = event.pricesByType || { socios: event.price || 0, amigos: event.price || 0, jugadores: event.price || 0, directiva: event.price || 0, entrenadores: event.price || 0 };
                const formatPrice = (value) => Number(value || 0) === 0 ? 'Gratuito' : `${Number(value || 0).toFixed(2)}€`;
                const participantsCount = event.participants ? event.participants.length : 0;
                
                let details = `🎉 DETALLES DEL EVENTO\n\n`;
                details += `Nombre: ${event.name}\n`;
                details += `Fecha: ${new Date(event.date).toLocaleDateString()}\n`;
                details += `Hora: ${event.startTime} - ${event.endTime}\n`;
                details += `Ubicación: ${event.location}\n`;
                details += `Precio socios/as: ${formatPrice(prices.socios)}\n`;
                details += `Precio amigos/as: ${formatPrice(prices.amigos)}\n`;
                details += `Precio jugadores/as: ${formatPrice(prices.jugadores)}\n`;
                details += `Precio directiva: ${formatPrice(prices.directiva)}\n`;
                details += `Precio entrenadores/as: ${formatPrice(prices.entrenadores)}\n`;
                details += `Ingresos inscripciones → ${event.revenueDestination === 'B' ? 'B (efectivo)' : 'A (banco)'}\n`;
                details += `Participantes: ${participantsCount}/${event.maxParticipants}\n`;
                details += `Mínimo requerido: ${event.minParticipants}\n`;
                const groups = event.allowedGroups || {
                    socios: event.allowedAudience !== 'amigos',
                    amigos: event.allowedAudience !== 'socios',
                    jugadores: false,
                    directiva: false,
                    entrenadores: false
                };
                const enabled = [];
                if (groups.socios) enabled.push('socios/as');
                if (groups.amigos) enabled.push('amigos/as');
                if (groups.jugadores) enabled.push('jugadores/as');
                if (groups.directiva) enabled.push('directiva');
                if (groups.entrenadores) enabled.push('entrenadores/as');
                details += `Permitido apuntarse: ${enabled.join(', ') || 'Nadie'}\n`;
                if (groups.jugadores) {
                    const scopeLabel = event.playerScope === 'categories' ? 'Por categorías' : 'Todos los jugadores/as';
                    details += `Alcance jugadores/as: ${scopeLabel}\n`;
                    if (event.playerScope === 'categories') {
                        details += `Categorías: ${(event.allowedPlayerCategories || []).join(', ') || 'Ninguna'}\n`;
                    }
                }
                
                if (event.registrationDeadline) {
                    details += `Fecha límite inscripción: ${new Date(event.registrationDeadline).toLocaleDateString()}\n`;
                }
                
                details += `\nDescripción: ${event.description}\n`;
                
                if (event.photoConsent || event.dataConsent) {
                    details += `\n✅ CONSENTIMIENTOS REQUERIDOS:\n`;
                    if (event.photoConsent) details += `- Autorización para fotos y videos\n`;
                    if (event.dataConsent) details += `- Tratamiento de datos personales\n`;
                }
                
                details += `\nCreado: ${new Date(event.createdAt).toLocaleDateString()}\nPor: ${event.createdBy}`;
                
                alert(details);
            }
        }

        function normalizeParticipantDni(value) {
            return String(value || '').trim().toUpperCase().replace(/[^0-9A-Z]/g, '');
        }

        function normalizeParticipantEventTier(p) {
            const raw = String(p.priceTier || p.resolvedBy || p.tipoUsuario || '').toLowerCase();
            if (raw.includes('directiv')) return 'directiva';
            if (raw.includes('entren')) return 'entrenadores';
            if (raw.includes('jugad')) return 'jugadores';
            if (raw.includes('amig')) return 'amigos';
            if (raw.includes('socio')) return 'socios';
            return 'socios';
        }

        function formatParticipantTierLabel(tier) {
            const t = String(tier || '');
            if (t === 'entrenadores') return 'entrenador/a';
            if (t === 'jugadores') return 'jugador/a';
            if (t === 'directiva') return 'directiva';
            if (t === 'amigos') return 'amigo/a';
            if (t === 'socios') return 'socio/a';
            return t || '—';
        }

        function resolveParticipantClubMembership(p) {
            if (p.isSocioMember || p.membershipKind === 'socio') return 'socio';
            if (p.isAmigoMember || p.membershipKind === 'amigo') return 'amigo';
            if (p.isEntrenadorMember || p.membershipKind === 'entrenador') return 'entrenador';
            const email = String(p.email || '').trim().toLowerCase();
            const dni = normalizeParticipantDni(p.dni);
            const pName = `${String(p.nombre || p.name || '').trim()} ${String(p.apellidos || p.surname || '').trim()}`
                .trim()
                .toLowerCase();
            const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
            const socioMatch = members.find(function (m) {
                return membersShareIdentity(m, {
                    email: email,
                    dni: dni,
                    name: p.nombre || p.name,
                    surname: p.apellidos || p.surname,
                    nombre: p.nombre || p.name,
                    apellidos: p.apellidos || p.surname
                });
            });
            if (socioMatch) return 'socio';
            if (dni && members.some((m) => normalizeParticipantDni(m.dni) === dni)) return 'socio';
            const amigos = JSON.parse(localStorage.getItem('clubFriends') || '[]');
            if (email && amigos.some((m) => String(m.email || '').trim().toLowerCase() === email)) return 'amigo';
            if (dni && amigos.some((m) => normalizeParticipantDni(m.dni) === dni)) return 'amigo';
            return null;
        }

        function participantMatchesClubPlayer(p) {
            if (p.isJugador) return true;
            const players = JSON.parse(localStorage.getItem('clubPlayers') || '[]');
            const email = String(p.email || '').trim().toLowerCase();
            const dni = normalizeParticipantDni(p.dni);
            const nombre = `${String(p.nombre || p.name || '').trim()} ${String(p.apellidos || p.surname || '').trim()}`
                .trim()
                .toLowerCase();
            return players.some((pl) => {
                const sameEmail = email && String(pl.email || '').trim().toLowerCase() === email;
                const sameDni = dni && normalizeParticipantDni(pl.dni) === dni;
                const plName = `${String(pl.name || pl.nombre || '').trim()} ${String(pl.surname || pl.apellidos || '').trim()}`
                    .trim()
                    .toLowerCase();
                const sameName = nombre && plName && plName === nombre;
                return sameEmail || sameDni || sameName;
            });
        }

        function participantMatchesExportFilter(p, filterKey) {
            const eventTier = normalizeParticipantEventTier(p);
            const clubMembership = resolveParticipantClubMembership(p);
            if (filterKey === 'all') return true;
            if (filterKey === 'jugadores') {
                return eventTier === 'jugadores' || participantMatchesClubPlayer(p);
            }
            if (filterKey === 'socios') {
                return clubMembership === 'socio';
            }
            if (filterKey === 'directiva') {
                return eventTier === 'directiva' || !!p.isDirectiva;
            }
            if (filterKey === 'amigos') {
                return eventTier === 'amigos' || clubMembership === 'amigo';
            }
            if (filterKey === 'entrenadores') {
                return eventTier === 'entrenadores' || !!p.isEntrenador || clubMembership === 'entrenador';
            }
            return true;
        }

        function promptEventParticipantsListFilter(eventTitle) {
            const msg = [
                `Listado de inscritos — ${eventTitle}`,
                '',
                '1 = Todos los inscritos',
                '2 = Jugadores/as (incl. socios que se apuntaron con tarifa jugador)',
                '3 = Socios/as del club (todos los socios inscritos, aunque paguen otra tarifa)',
                '4 = Directiva',
                '5 = Amigos/as',
                '6 = Entrenadores/as',
                '7 = Combinar (ej: 2,3 = jugadores + socios; 3,4 = socios + directiva)',
                '',
                'Escribe el número o números separados por coma:'
            ].join('\n');
            const raw = prompt(msg, '1');
            if (raw === null) return null;
            const trimmed = String(raw).trim();
            if (!trimmed) return ['all'];
            const map = {
                1: 'all',
                2: 'jugadores',
                3: 'socios',
                4: 'directiva',
                5: 'amigos',
                6: 'entrenadores'
            };
            const tokens = trimmed.includes(',') || trimmed.includes(' ')
                ? trimmed.replace(/^7[,:\s]*/i, '').split(/[,\s]+/).filter(Boolean)
                : [trimmed];
            const keys = tokens
                .map((t) => map[t] || (['jugadores', 'socios', 'directiva', 'amigos', 'entrenadores', 'all'].includes(t) ? t : null))
                .filter(Boolean);
            if (!keys.length || keys.includes('all')) return ['all'];
            return [...new Set(keys)];
        }

        function filterEventParticipantsByListChoice(participants, filters) {
            if (!filters || filters.includes('all')) return participants.slice();
            return participants.filter((p) => filters.some((f) => participantMatchesExportFilter(p, f)));
        }

        function getEventParticipantsFilterSummary(filters) {
            if (!filters || filters.includes('all')) return 'todos los inscritos';
            const labels = {
                jugadores: 'jugadores/as',
                socios: 'socios/as del club',
                directiva: 'directiva',
                amigos: 'amigos/as',
                entrenadores: 'entrenadores/as'
            };
            return filters.map((f) => labels[f] || f).join(' + ');
        }

        function formatParticipantListLine(p, idx) {
            const fullName = [p.nombre, p.apellidos].filter(Boolean).join(' ').trim() || p.name || p.email || 'Sin nombre';
            const eventTier = normalizeParticipantEventTier(p);
            const clubMembership = resolveParticipantClubMembership(p);
            const price = Number(p.appliedPrice || 0) === 0 ? 'Gratuito' : `${Number(p.appliedPrice || 0).toFixed(2)}€`;
            let perfil = `evento: ${formatParticipantTierLabel(eventTier)}`;
            if (clubMembership === 'socio' && eventTier !== 'socios') {
                perfil += ' · también socio/a';
            } else if (clubMembership && clubMembership !== 'socio') {
                perfil += ` · alta: ${clubMembership}`;
            }
            if (p.playerCategory) perfil += ` · ${p.playerCategory}`;
            let pago = '';
            if (!p.isGuest && eventParticipantPaymentPending(p)) {
                pago = ' | 🏦 pago pendiente';
            } else if (p.paid === true || String(p.paymentStatus || '').toLowerCase() === 'paid' || p.paidOnline) {
                pago = ' | ✅ pagado';
            }
            return `${idx + 1}. ${fullName} | ${p.email || 'sin email'} | ${p.telefono || p.phone || 'sin teléfono'} | ${perfil} | ${price}${pago}`;
        }

        function eventParticipantPaymentPending(p) {
            if (!p || p.isGuest) return false;
            const status = String(p.paymentStatus || '').toLowerCase();
            if (status === 'paid' || p.paid === true || p.paidOnline === true) return false;
            if (status === 'pending_transfer') return true;
            return String(p.paymentMethod || '').toLowerCase() === 'transfer' && p.paid !== true;
        }

        function groupPendingEventRegistrationBundles(participants) {
            const list = Array.isArray(participants) ? participants : [];
            const pendingHolders = list.filter((p) => eventParticipantPaymentPending(p) && !p.isGuest);
            return pendingHolders.map((holder) => {
                const email = String(holder.email || '').trim().toLowerCase();
                const holderId = holder.id ? String(holder.id) : '';
                const guests = list.filter((g) => {
                    if (!g || !g.isGuest) return false;
                    const guestPending =
                        String(g.paymentStatus || '').toLowerCase() === 'pending_transfer' ||
                        (String(g.paymentMethod || '').toLowerCase() === 'transfer' && g.paid !== true);
                    if (!guestPending) return false;
                    const byEmail = email && String(g.invitedByEmail || '').trim().toLowerCase() === email;
                    const byId = holderId && g.invitedById && String(g.invitedById) === holderId;
                    return byEmail || byId;
                });
                const records = [holder, ...guests];
                const total = records.reduce((s, r) => s + Number(r.appliedPrice || 0), 0);
                return {
                    holder: holder,
                    guests: guests,
                    records: records,
                    email: holder.email,
                    total: Math.round(total * 100) / 100,
                    slots: records.length,
                    guestCount: guests.length
                };
            });
        }

        function countPendingEventPaymentBundles(event) {
            const participants = Array.isArray(event.participants) ? event.participants : [];
            return groupPendingEventRegistrationBundles(participants).length;
        }

        function adminPaymentChannelFromChoice(choice) {
            const c = String(choice || '').trim();
            if (c === '2') return 'efectivo';
            if (c === '3') return 'otro';
            return 'transferencia';
        }

        async function validateEventRegistrationPayment(eventId, holderEmail) {
            try {
                const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
                const eventIndex = events.findIndex((e) => String(e.id) === String(eventId));
                if (eventIndex < 0) {
                    alert('❌ Evento no encontrado');
                    return;
                }
                const event = events[eventIndex];
                const participants = Array.isArray(event.participants) ? event.participants : [];
                const bundles = groupPendingEventRegistrationBundles(participants);
                const normEmail = String(holderEmail || '').trim().toLowerCase();
                const bundle = bundles.find((b) => String(b.email || '').trim().toLowerCase() === normEmail);
                if (!bundle) {
                    alert('❌ Inscripción no encontrada o ya validada');
                    return;
                }

                const holderName = [bundle.holder.nombre || bundle.holder.name, bundle.holder.apellidos || bundle.holder.surname]
                    .filter(Boolean)
                    .join(' ')
                    .trim();
                const choice = prompt(
                    '¿Confirmas que has recibido el pago de esta inscripción?\n\n' +
                    holderName +
                    '\n' +
                    bundle.email +
                    '\nImporte: ' +
                    bundle.total.toFixed(2) +
                    ' €\nPlazas: ' +
                    bundle.slots +
                    (bundle.guestCount ? ' (incl. ' + bundle.guestCount + ' invitado(s))' : '') +
                    '\n\n1 = Transferencia bancaria\n2 = Efectivo\n3 = Otro\n\nEscribe 1, 2 o 3:',
                    '1'
                );
                if (choice === null) return;
                if (!['1', '2', '3'].includes(String(choice).trim())) {
                    alert('Operación cancelada.');
                    return;
                }
                if (!confirm('¿Validar el pago y confirmar la inscripción al evento?')) return;

                const currentAdmin = JSON.parse(localStorage.getItem('currentAdmin') || '{}');
                const adminName = currentAdmin.name || currentAdmin.email || 'Administrador';
                const payChannel = adminPaymentChannelFromChoice(choice);
                const now = new Date().toISOString();
                const bundleIds = new Set(bundle.records.map((r) => (r.id ? String(r.id) : '')).filter(Boolean));

                event.participants = participants.map((p) => {
                    const inBundle =
                        (p.id && bundleIds.has(String(p.id))) ||
                        (!p.isGuest && String(p.email || '').trim().toLowerCase() === normEmail && eventParticipantPaymentPending(p)) ||
                        (p.isGuest &&
                            String(p.invitedByEmail || '').trim().toLowerCase() === normEmail &&
                            (String(p.paymentStatus || '').toLowerCase() === 'pending_transfer' ||
                                (String(p.paymentMethod || '').toLowerCase() === 'transfer' && p.paid !== true)));
                    if (!inBundle) return p;
                    return {
                        ...p,
                        paymentStatus: 'paid',
                        paid: true,
                        paidAt: now,
                        validatedDate: now,
                        validatedBy: adminName,
                        paymentMethod: payChannel === 'efectivo' ? 'cash' : payChannel === 'otro' ? 'other' : 'transfer'
                    };
                });
                event.registeredMembers = event.participants;
                event.updatedAt = now;
                events[eventIndex] = event;
                localStorage.setItem('clubEvents', JSON.stringify(events));

                let firebaseSyncOk = false;
                try {
                    await persistRecordToFirebase('clubEvents', 'events', event);
                    firebaseSyncOk = true;
                } catch (syncErr) {
                    console.warn('Validación evento guardada en local; error Firebase:', syncErr);
                }

                if (typeof ClubAccounting !== 'undefined' && bundle.total > 0) {
                    const bucket = event.revenueDestination === 'B' ? 'B' : 'A';
                    const hint = holderName || bundle.email;
                    const row = ClubAccounting.recordEventIncome(
                        bucket,
                        bundle.total,
                        event.id,
                        event.name || event.title,
                        hint
                    );
                    if (row && ClubAccounting.trySyncLedgerRow) {
                        ClubAccounting.trySyncLedgerRow(row);
                    }
                }

                if (bundle.email) {
                    const eventTime = [event.startTime, event.endTime].filter(Boolean).join(' — ');
                    fetch('/.netlify/functions/send-club-email', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            type: 'event_registration_confirmed',
                            email: bundle.email,
                            nombre: bundle.holder.nombre || bundle.holder.name,
                            apellidos: bundle.holder.apellidos || bundle.holder.surname,
                            eventTitle: event.name || event.title,
                            eventDate: event.date,
                            eventTime: eventTime,
                            eventLocation: event.location,
                            totalEur: bundle.total,
                            slots: bundle.slots,
                            guestCount: bundle.guestCount,
                            paymentChannel: payChannel
                        })
                    })
                        .then((r) => r.json())
                        .then((r) => {
                            if (!r.ok) console.warn('Email confirmación evento:', r.error);
                        })
                        .catch((e) => console.warn('Email confirmación evento:', e));
                }

                loadEventsList();
                const syncMsg = firebaseSyncOk ? 'sincronizada' : 'guardada solo en este dispositivo';
                alert(
                    '✅ Pago validado. Inscripción confirmada (' +
                        syncMsg +
                        ').\n\n📧 Se enviará un correo de confirmación a ' +
                        (bundle.email || '—') +
                        '.'
                );
            } catch (error) {
                console.error('❌ Error validando pago evento:', error);
                alert('❌ Error al validar el pago: ' + (error.message || error));
            }
        }

        function validateEventPaymentsMenu(eventId) {
            const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
            const event = events.find((e) => String(e.id) === String(eventId));
            if (!event) {
                alert('❌ Evento no encontrado');
                return;
            }
            const bundles = groupPendingEventRegistrationBundles(
                Array.isArray(event.participants) ? event.participants : []
            );
            if (!bundles.length) {
                alert('ℹ️ No hay inscripciones con pago pendiente de validar en este evento.');
                return;
            }
            const title = event.name || event.title || 'Evento';
            const lines = bundles.map((b, i) => {
                const name = [b.holder.nombre || b.holder.name, b.holder.apellidos || b.holder.surname]
                    .filter(Boolean)
                    .join(' ')
                    .trim();
                return (
                    i +
                    1 +
                    '. ' +
                    name +
                    ' — ' +
                    (b.email || 'sin email') +
                    ' — ' +
                    b.total.toFixed(2) +
                    ' € (' +
                    b.slots +
                    ' plaza(s))'
                );
            });
            const pick = prompt(
                '🏦 PAGOS PENDIENTES — ' +
                    title +
                    '\n\n' +
                    lines.join('\n') +
                    '\n\nEscribe el número de la inscripción a validar (1-' +
                    bundles.length +
                    '):',
                '1'
            );
            if (pick === null) return;
            const ix = parseInt(String(pick).trim(), 10) - 1;
            if (!Number.isFinite(ix) || ix < 0 || ix >= bundles.length) {
                alert('Selección no válida.');
                return;
            }
            validateEventRegistrationPayment(eventId, bundles[ix].email);
        }

        function buildParticipantExportRow(event, p) {
            const eventTier = normalizeParticipantEventTier(p);
            const clubMembership = resolveParticipantClubMembership(p);
            const tambienSocio =
                clubMembership === 'socio' && eventTier !== 'socios' ? 'si' : clubMembership === 'socio' ? 'si' : 'no';
            return [
                event.name || event.title || '',
                event.date || '',
                p.nombre || p.name || '',
                p.apellidos || p.surname || '',
                p.email || '',
                p.telefono || p.phone || '',
                formatParticipantTierLabel(eventTier),
                p.priceTier || '',
                p.appliedPrice == null ? '' : p.appliedPrice,
                p.resolvedBy || p.tipoUsuario || '',
                clubMembership || '',
                tambienSocio,
                p.playerCategory || '',
                p.sourceMatch || '',
                p.registeredAt || ''
            ];
        }

        function manageEventParticipants(eventId) {
            const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
            const event = events.find(e => e.id === eventId);
            if (!event) {
                alert('❌ Evento no encontrado');
                return;
            }

            const participants = Array.isArray(event.participants) ? event.participants : [];
            if (!participants.length) {
                alert(`ℹ️ "${event.name || event.title || 'Evento'}" no tiene inscritos aún.`);
                return;
            }

            const filters = promptEventParticipantsListFilter(event.name || event.title || 'Evento');
            if (filters === null) return;

            const filtered = filterEventParticipantsByListChoice(participants, filters);
            if (!filtered.length) {
                alert(`ℹ️ No hay inscritos que coincidan con: ${getEventParticipantsFilterSummary(filters)}`);
                return;
            }

            const lines = filtered.map((p, idx) => formatParticipantListLine(p, idx));
            const pendingPay = countPendingEventPaymentBundles(event);

            const details = [
                `👥 INSCRITOS EN: ${event.name || event.title || 'Evento'}`,
                `Filtro: ${getEventParticipantsFilterSummary(filters)}`,
                `Mostrando: ${filtered.length} de ${participants.length}`,
                pendingPay > 0 ? `🏦 Pagos pendientes de validar: ${pendingPay} (usa «Validar pagos» en la lista del evento)` : '',
                '',
                ...lines,
                '',
                'Para exportar con el mismo criterio, usa CSV o Word de inscritos.'
            ].join('\n');
            alert(details);
        }

        function escapeCsvValue(value) {
            return `"${String(value == null ? '' : value).replace(/"/g, '""')}"`;
        }

        function downloadBlobFile(content, filename, mimeType) {
            const blob = new Blob([content], { type: mimeType });
            const link = document.createElement('a');
            const url = URL.createObjectURL(blob);
            link.href = url;
            link.download = filename;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            URL.revokeObjectURL(url);
            addToExportHistory(filename);
        }

        function getEventParticipantsExportPack(eventId) {
            const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
            const event = events.find((e) => e.id === eventId);
            if (!event) {
                alert('❌ Evento no encontrado');
                return null;
            }
            const participants = Array.isArray(event.participants) ? event.participants : [];
            if (!participants.length) {
                alert('ℹ️ Este evento no tiene inscritos para exportar');
                return null;
            }
            const title = event.name || event.title || 'Evento';
            const filters = promptEventParticipantsListFilter(title);
            if (filters === null) return null;
            const filtered = filterEventParticipantsByListChoice(participants, filters);
            if (!filtered.length) {
                alert(`ℹ️ No hay inscritos que coincidan con: ${getEventParticipantsFilterSummary(filters)}`);
                return null;
            }
            const headers = [
                'Evento',
                'FechaEvento',
                'Nombre',
                'Apellidos',
                'Email',
                'Telefono',
                'PerfilEnEvento',
                'TarifaAplicada',
                'PrecioAplicado',
                'ResueltoComo',
                'AltaEnClub',
                'TambienSocio',
                'CategoriaJugador',
                'CoincidenciaPor',
                'FechaInscripcion'
            ];
            const matrixRows = filtered.map((p) => buildParticipantExportRow(event, p));
            const objectRows = matrixRows.map((r) => {
                const o = {};
                headers.forEach((h, i) => {
                    o[h] = r[i];
                });
                return o;
            });
            const filterSlug = filters.includes('all') ? 'todos' : filters.join('-');
            const safeName = String(title).replace(/[^\w.-]/g, '_');
            const date = new Date().toISOString().split('T')[0];
            const base = `inscritos_${safeName}_${filterSlug}_${date}`;
            return {
                event,
                title,
                filters,
                filtered,
                participants,
                headers,
                matrixRows,
                objectRows,
                base,
                filterSummary: getEventParticipantsFilterSummary(filters)
            };
        }

        function exportEventParticipantsCSV(eventId) {
            const pack = getEventParticipantsExportPack(eventId);
            if (!pack) return;
            const csv = [
                pack.headers.map(escapeCsvValue).join(','),
                ...pack.matrixRows.map((r) => r.map(escapeCsvValue).join(','))
            ].join('\n');
            downloadBlobFile(csv, `${pack.base}.csv`, 'text/csv;charset=utf-8;');
            alert(`✅ Exportados ${pack.filtered.length} de ${pack.participants.length} inscritos (${pack.filterSummary})`);
        }

        async function exportEventParticipantsExcel(eventId) {
            const pack = getEventParticipantsExportPack(eventId);
            if (!pack) return;
            await exportDatasetToExcel(pack.headers, pack.objectRows, `${pack.base}.xlsx`);
            addToExportHistory(`${pack.base}.xlsx`);
            alert(`✅ Excel: ${pack.filtered.length} inscritos (${pack.filterSummary})`);
        }

        function exportEventParticipantsWord(eventId) {
            const pack = getEventParticipantsExportPack(eventId);
            if (!pack) return;
            const bodyLines = pack.filtered.map((p, idx) => formatParticipantListLine(p, idx));
            const docContent = [
                `Lista de inscritos - ${pack.title}`,
                `Fecha del evento: ${pack.event.date || '-'}`,
                `Filtro: ${pack.filterSummary}`,
                `Inscritos en este listado: ${pack.filtered.length} de ${pack.participants.length}`,
                '',
                ...bodyLines
            ].join('\n');
            downloadBlobFile(docContent, `${pack.base}.doc`, 'application/msword;charset=utf-8;');
            addToExportHistory(`${pack.base}.doc`);
            alert(`✅ Word: ${pack.filtered.length} inscritos (${pack.filterSummary})`);
        }

        async function exportEventParticipantsPdf(eventId) {
            const pack = getEventParticipantsExportPack(eventId);
            if (!pack) return;
            const listTitle = `Inscritos — ${pack.title} (${pack.filterSummary})`;
            await exportDatasetToPdf(listTitle, pack.headers, pack.objectRows, `${pack.base}.pdf`);
            addToExportHistory(`${pack.base}.pdf`);
            alert(`✅ PDF: ${pack.filtered.length} inscritos. Usa «Guardar como PDF» en el diálogo de impresión.`);
        }

        function editEvent(eventId) {
            try {
                const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
                const event = events.find((e) => String(e.id) === String(eventId));
                if (!event) {
                    alert('❌ Evento no encontrado');
                    return;
                }
                const normalized = normalizeLegacyEvent(event);
                window.__eventEditingId = normalized.id;
                showAddEventForm();
                prefillEventFormFromTemplate(normalized);
                document.getElementById('eventName').value = normalized.name || normalized.title || '';
                alert('✏️ Modo edición activo. Ajusta los campos y pulsa "Crear Evento" para guardar cambios.');
            } catch (error) {
                console.error('❌ Error cargando edición de evento:', error);
                alert('❌ No se pudo abrir el evento para edición.');
            }
        }

        async function deleteEvent(eventId) {
            if (confirm('¿Estás seguro de que quieres eliminar este evento?\n\n⚠️ Esta acción no se puede deshacer y eliminará todas las inscripciones.')) {
                try {
                    const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
                    const eventToDelete = events.find(e => e.id === eventId);
                    
                    if (eventToDelete) {
                        const updatedEvents = events.filter(e => e.id !== eventId);
                        localStorage.setItem('clubEvents', JSON.stringify(updatedEvents));
                        await deleteRecordFromFirebase('events', eventId);
                        
                        loadEventsList();
                        updateDashboardCounts();
                        alert('✅ Evento "' + eventToDelete.name + '" eliminado correctamente');
                        console.log('🗑️ Evento eliminado:', eventToDelete.name);
                    }
                } catch (error) {
                    console.error('❌ Error eliminando evento:', error);
                    alert('❌ Error al eliminar el evento');
                }
            }
        }

        async function deleteOldEvents() {
            try {
                const rawDays = prompt('¿Eliminar eventos finalizados con más de cuántos días de antigüedad?', '30');
                if (rawDays === null) return;
                const days = Number(rawDays);
                if (!Number.isFinite(days) || days < 0) {
                    alert('❌ Debes indicar un número válido de días (0 o mayor).');
                    return;
                }

                const events = JSON.parse(localStorage.getItem('clubEvents') || '[]');
                if (!Array.isArray(events) || !events.length) {
                    alert('ℹ️ No hay eventos para revisar.');
                    return;
                }

                const now = Date.now();
                const threshold = now - (days * 24 * 60 * 60 * 1000);
                const toDelete = [];
                const keep = [];

                events.forEach((event) => {
                    const endStamp = new Date(`${event.date || ''}T${event.endTime || '23:59'}`).getTime();
                    const status = String(event.status || '').toLowerCase();
                    const consideredFinished = status === 'finished' || status === 'finalizado' || (Number.isFinite(endStamp) && endStamp < now);
                    const isOldEnough = Number.isFinite(endStamp) ? endStamp < threshold : false;
                    if (consideredFinished && isOldEnough) {
                        toDelete.push(event);
                    } else {
                        keep.push(event);
                    }
                });

                if (!toDelete.length) {
                    alert('ℹ️ No hay eventos antiguos finalizados que cumplan el criterio.');
                    return;
                }

                const confirmText = `Se eliminarán ${toDelete.length} evento(s) finalizado(s) de más de ${days} día(s).\n\n¿Continuar?`;
                if (!confirm(confirmText)) return;

                localStorage.setItem('clubEvents', JSON.stringify(keep));

                if (typeof deleteRecordFromFirebase === 'function') {
                    for (const event of toDelete) {
                        try {
                            if (event.id) await deleteRecordFromFirebase('events', event.id);
                        } catch (error) {
                            console.warn('No se pudo eliminar evento en Firebase:', event.id, error);
                        }
                    }
                } else if (typeof window.syncLocalArrayKeyToFirebase === 'function') {
                    try { await window.syncLocalArrayKeyToFirebase('clubEvents'); } catch (_) {}
                }

                loadEventsList();
                updateDashboardCounts();
                alert(`✅ Se eliminaron ${toDelete.length} evento(s) antiguo(s).`);
            } catch (error) {
                console.error('❌ Error eliminando eventos antiguos:', error);
                alert('❌ No se pudieron eliminar los eventos antiguos.');
            }
        }

