        // === MÓDULO DE COMPETICIONES ===

        function hasCompetitionAdminAccess() {
            if (window.AdminOrganizerAccess && window.AdminOrganizerAccess.hasCompetitionManagementAccess()) {
                return true;
            }
            try {
                const currentAdmin = JSON.parse(localStorage.getItem('currentAdmin') || '{}');
                const hasSession = !!currentAdmin?.email;
                const hasRoleFlag =
                    currentAdmin?.role === 'admin' ||
                    currentAdmin?.role === 'super_admin' ||
                    currentAdmin?.role === 'competition_organizer';
                return hasSession && hasRoleFlag;
            } catch (_) {
                return false;
            }
        }

        function ensureCompetitionAdminAccess() {
            if (hasCompetitionAdminAccess()) return true;
            alert('🔒 Solo administradores u organizadores de competiciones pueden gestionar campeonatos.');
            return false;
        }
        
        function resetCompetitionFormChromeForNew() {
            const hid = document.getElementById('competitionEditId');
            if (hid) hid.value = '';
            const h = document.getElementById('competitionFormHeading');
            if (h) h.textContent = '🏆 Nueva Competición';
            const lbl = document.getElementById('competitionSaveButtonLabel');
            if (lbl) lbl.textContent = '💾 Guardar competición';
            const excl = document.getElementById('competitionExcludeOfficialPlayerStats');
            if (excl) excl.checked = true;
            updateCompetitionFormModeActions();
        }

        /** Por defecto las competiciones no alteran estadística oficial / federativa del club. */
        function competitionUsesInternalStatsOnly(competition) {
            if (!competition) return true;
            return competition.excludeFromOfficialPlayerStats !== false;
        }

        function getCompetitionTeamById(competition, teamId) {
            return (competition?.teams || []).find((t) => String(t.id) === String(teamId)) || null;
        }

        function matchBelongsToCategory(competition, match, categoryKey) {
            if (!categoryKey || categoryKey === 'all') return true;
            const target = normalizeCategoryKey(categoryKey);
            const hint = normalizeCategoryKey(match?.categoryHint || '');
            if (hint && hint === target) return true;
            const home = getCompetitionTeamById(competition, match?.homeTeamId);
            const away = getCompetitionTeamById(competition, match?.awayTeamId);
            return (
                normalizeCategoryKey(home?.category) === target ||
                normalizeCategoryKey(away?.category) === target
            );
        }

        function getMatchPrimaryCategory(competition, match) {
            const hint = String(match?.categoryHint || '').trim();
            if (hint) return hint;
            const home = getCompetitionTeamById(competition, match?.homeTeamId);
            const away = getCompetitionTeamById(competition, match?.awayTeamId);
            return String(home?.category || away?.category || '').trim();
        }

        function updateCompetitionFormModeActions() {
            const editId = String(document.getElementById('competitionEditId')?.value || '').trim();
            const type = String(document.getElementById('competitionType')?.value || '').trim().toLowerCase();
            const regenBtn = document.getElementById('competitionRegenerateBracketBtn');
            if (regenBtn) regenBtn.style.display = (editId && type === 'torneo') ? 'inline-block' : 'none';
        }

        function populateCompetitionFormFromRecord(competition) {
            const c = competition || {};
            const setVal = (id, v) => {
                const el = document.getElementById(id);
                if (el && v !== undefined && v !== null) el.value = String(v);
            };
            setVal('competitionName', c.name || '');
            setVal('competitionTitle', c.title || '');
            const cats = Array.isArray(c.categories) && c.categories.length
                ? c.categories
                : (c.category ? [c.category] : []);
            const catSel = document.getElementById('competitionCategories');
            if (catSel) {
                Array.from(catSel.options).forEach((opt) => {
                    if (!opt.value) return;
                    opt.selected = cats.includes(opt.value);
                });
            }
            const slots = Array.isArray(c.categorySlots) ? c.categorySlots : [];
            setVal(
                'competitionCategorySlots',
                slots.map((s) => [s.category, s.field, s.time].map((x) => String(x || '').trim()).filter(Boolean).join(' | ')).join('\n')
            );
            setVal('competitionFieldMode', c.fieldMode || 'single');
            setVal('competitionDefaultField', c.defaultField || '');
            setVal('competitionFieldList', c.fieldListRaw || '');
            setVal('competitionCalendarMode', normalizeCalendarMode(c.calendarMode));
            setVal('competitionScheduleDayStartTime', (c.scheduleDayStartTime || '09:00').toString().trim().slice(0, 5));
            setVal('competitionScheduleSlotMinutes', c.scheduleSlotIntervalMinutes != null ? String(c.scheduleSlotIntervalMinutes) : '90');
            setVal('competitionScheduleMatchDurationMinutes', Number(c.scheduleMatchDurationMinutes) > 0 ? String(c.scheduleMatchDurationMinutes) : '');
            setVal('competitionScheduleTurnoverMinutes', c.scheduleTurnoverMinutes != null ? String(c.scheduleTurnoverMinutes) : '10');
            setVal(
                'competitionScheduleCategoryDurations',
                c.scheduleCategoryDurationsRaw
                    || (Array.isArray(c.scheduleCategoryDurations) && c.scheduleCategoryDurations.length
                        ? c.scheduleCategoryDurations.map((row) =>
                            [row.category, row.matchMinutes, row.turnoverMinutes != null ? row.turnoverMinutes : ''].filter((x) => x !== '' && x != null).join(' | ')
                          ).join('\n')
                        : '')
            );
            setVal('competitionScheduleMaxMatchesPerDay', c.scheduleMaxMatchesPerDay != null ? String(c.scheduleMaxMatchesPerDay) : '0');
            setVal('competitionScheduleWeekdayDefaultEnd', (c.scheduleWeekdayDefaultEnd || '21:30').toString().trim().slice(0, 5));
            setVal('competitionScheduleWeekdayWindows', c.scheduleWeekdayWindowsRaw || c.scheduleWeekdayWindows || '');
            setVal('competitionScheduleRuleOverrides', c.scheduleRuleOverridesRaw || '');
            setVal('competitionScheduleAgeSortMode', c.scheduleAgeSortMode || 'youngest_first');
            setVal('competitionScheduleCategoryCustomOrder', c.scheduleCategoryCustomOrderRaw || '');
            const inv = document.getElementById('competitionScheduleCustomOrderInverted');
            if (inv) inv.checked = !!c.scheduleCustomOrderInverted;
            setVal('competitionScheduleSortCutoffTime', (c.scheduleSortCutoffTime || '').toString().trim().slice(0, 5));
            setVal('competitionScheduleAgeSortAfterCutoff', c.scheduleAgeSortAfterCutoff || '');
            setVal('competitionScheduleClampMinTime', (c.scheduleClampMinTime || '').toString().trim().slice(0, 5));
            setVal('competitionScheduleClampMaxTime', (c.scheduleClampMaxTime || '').toString().trim().slice(0, 5));
            setVal('competitionType', c.type || '');
            setVal('maxTeams', c.maxTeams != null ? String(c.maxTeams) : '8');
            const ft = normalizeCompetitionFormatType(
                c.formatType || (c.sportMode === 'futbol_sala' ? 'futbol_sala' : `futbol_${c.footballFormat || '7'}`)
            );
            setVal('competitionFormatType', ft);
            setVal('competitionStartDate', c.startDate || '');
            setVal('competitionEndDate', c.endDate || '');
            setVal('competitionDescription', c.description || '');
            setVal('competitionRules', c.rules || '');
            const exclOfficial = document.getElementById('competitionExcludeOfficialPlayerStats');
            if (exclOfficial) exclOfficial.checked = competitionUsesInternalStatsOnly(c);
            toggleCompetitionFields({ preserveValues: true });
            toggleParallelCalendarOptions();
            toggleParallelSortCustomOptions();
        }

        function beginEditCompetition(competitionId) {
            if (!ensureCompetitionAdminAccess()) return;
            showTab('competiciones');
            const { competition } = getCompetitionById(competitionId);
            if (!competition) {
                alert('❌ Competición no encontrada');
                return;
            }
            document.getElementById('competitionEditId').value = competition.id;
            populateCompetitionFormFromRecord(competition);
            const h = document.getElementById('competitionFormHeading');
            if (h) h.textContent = '✏️ Editar competición';
            const lbl = document.getElementById('competitionSaveButtonLabel');
            if (lbl) lbl.textContent = '💾 Guardar cambios';
            updateCompetitionFormModeActions();
            document.getElementById('addCompetitionForm').style.display = 'block';
            document.getElementById('addCompetitionForm').scrollIntoView({ behavior: 'smooth' });
            refreshSchedulePresetSelect();
        }

        async function regenerateCompetitionBracketFromEditForm() {
            if (!ensureCompetitionAdminAccess()) return;
            const editId = String(document.getElementById('competitionEditId')?.value || '').trim();
            if (!editId) {
                alert('Abre primero una competición en modo edición.');
                return;
            }
            if (String(document.getElementById('competitionType')?.value || '').trim().toLowerCase() !== 'torneo') {
                alert('La regeneración de cuadro solo aplica a torneos.');
                return;
            }
            if (!confirm('Se guardarán primero los cambios del formulario y después se regenerará el cuadro completo.\n\n¿Continuar?')) return;
            await saveCompetition();
            const { competition } = getCompetitionById(editId);
            if (!competition) {
                alert('❌ Competición no encontrada tras guardar');
                return;
            }
            if (competition.type !== 'torneo') {
                alert('La competición ya no está en modo torneo.');
                return;
            }
            const hadCompleted = (competition.matches || []).some((m) => m?.status === 'completed');
            if (hadCompleted) {
                const hard = confirm(
                    '⚠️ Hay partidos ya jugados.\n\nSi regeneras el cuadro se perderán esos resultados en el bracket.\n\n¿Regenerar de todas formas?'
                );
                if (!hard) return;
            }
            const generated = buildFullKnockoutCalendar(competition);
            competition.matches = generated.matches;
            competition.phases = generated.phases.length
                ? generated.phases
                : generateTournamentPhases(competition.maxTeams || 2);
            competition.champion = null;
            if (competition.status === 'finalizado') competition.status = 'activo';
            competition.updatedAt = new Date().toISOString();
            await saveCompetitionRecord(competition);
            loadCompetitionsList();
            alert('✅ Cuadro regenerado correctamente.');
        }

        function showAddCompetitionForm() {
            if (!ensureCompetitionAdminAccess()) return;
            clearCompetitionForm();
            document.getElementById('addCompetitionForm').style.display = 'block';
            document.getElementById('addCompetitionForm').scrollIntoView({ behavior: 'smooth' });
            const today = new Date();
            document.getElementById('competitionStartDate').value = today.toISOString().split('T')[0];
            const formatSelect = document.getElementById('competitionFormatType');
            if (formatSelect && !formatSelect.value) {
                formatSelect.value = 'futbol_7';
            }
            toggleParallelCalendarOptions();
            refreshSchedulePresetSelect();
        }

        function toggleParallelSortCustomOptions() {
            const sortMode = document.getElementById('competitionScheduleAgeSortMode')?.value || 'youngest_first';
            const wrap = document.getElementById('parallelSortCustomWrap');
            if (wrap) wrap.style.display = sortMode === 'custom' ? 'block' : 'none';
        }

        function toggleParallelCalendarOptions() {
            const mode = document.getElementById('competitionCalendarMode')?.value || 'classic';
            const box = document.getElementById('parallelCalendarOptions');
            if (box) box.style.display = mode === 'parallel_occupancy' ? 'block' : 'none';
            if (mode === 'parallel_occupancy') toggleParallelSortCustomOptions();
        }

        const SCHEDULE_PRESETS_STORAGE_KEY = 'clubSchedulePresets';

        function readSchedulePresetsList() {
            try {
                const raw = localStorage.getItem(SCHEDULE_PRESETS_STORAGE_KEY);
                const arr = JSON.parse(raw || '[]');
                return Array.isArray(arr) ? arr : [];
            } catch (e) {
                return [];
            }
        }

        function writeSchedulePresetsList(list) {
            localStorage.setItem(SCHEDULE_PRESETS_STORAGE_KEY, JSON.stringify(list));
        }

        function refreshSchedulePresetSelect() {
            const sel = document.getElementById('schedulePresetSelect');
            if (!sel) return;
            const prev = sel.value;
            sel.innerHTML = '<option value="">— Elegir plantilla —</option>';
            readSchedulePresetsList().forEach((p, idx) => {
                const opt = document.createElement('option');
                opt.value = String(idx);
                opt.textContent = String(p?.name || `Plantilla ${idx + 1}`);
                sel.appendChild(opt);
            });
            if (prev && [...sel.options].some((o) => o.value === prev)) sel.value = prev;
        }

        function gatherParallelSchedulePresetPayload() {
            return {
                calendarMode: String(document.getElementById('competitionCalendarMode')?.value || 'classic'),
                scheduleDayStartTime: String(document.getElementById('competitionScheduleDayStartTime')?.value || '09:00').trim(),
                scheduleSlotIntervalMinutes: Math.max(30, parseInt(String(document.getElementById('competitionScheduleSlotMinutes')?.value || '90'), 10) || 90),
                scheduleMatchDurationMinutes: (() => {
                    const raw = String(document.getElementById('competitionScheduleMatchDurationMinutes')?.value || '').trim();
                    return raw === '' ? 0 : Math.max(1, parseInt(raw, 10) || 0);
                })(),
                scheduleTurnoverMinutes: Math.max(0, parseInt(String(document.getElementById('competitionScheduleTurnoverMinutes')?.value ?? '10'), 10) || 0),
                scheduleCategoryDurationsRaw: String(document.getElementById('competitionScheduleCategoryDurations')?.value || '').trim(),
                scheduleCategoryDurations: parseCategoryDurationLines(String(document.getElementById('competitionScheduleCategoryDurations')?.value || '').trim()),
                scheduleMaxMatchesPerDay: Math.max(0, parseInt(String(document.getElementById('competitionScheduleMaxMatchesPerDay')?.value || '0'), 10) || 0),
                scheduleWeekdayDefaultEnd: String(document.getElementById('competitionScheduleWeekdayDefaultEnd')?.value || '21:30').trim(),
                scheduleWeekdayWindowsRaw: String(document.getElementById('competitionScheduleWeekdayWindows')?.value || '').trim(),
                scheduleRuleOverridesRaw: String(document.getElementById('competitionScheduleRuleOverrides')?.value || '').trim(),
                scheduleAgeSortMode: String(document.getElementById('competitionScheduleAgeSortMode')?.value || 'youngest_first').trim(),
                scheduleCategoryCustomOrderRaw: String(document.getElementById('competitionScheduleCategoryCustomOrder')?.value || '').trim(),
                scheduleCustomOrderInverted: !!document.getElementById('competitionScheduleCustomOrderInverted')?.checked,
                scheduleSortCutoffTime: String(document.getElementById('competitionScheduleSortCutoffTime')?.value || '').trim(),
                scheduleAgeSortAfterCutoff: String(document.getElementById('competitionScheduleAgeSortAfterCutoff')?.value || '').trim(),
                scheduleClampMinTime: String(document.getElementById('competitionScheduleClampMinTime')?.value || '').trim(),
                scheduleClampMaxTime: String(document.getElementById('competitionScheduleClampMaxTime')?.value || '').trim(),
                defaultField: String(document.getElementById('competitionDefaultField')?.value || '').trim(),
                fieldListRaw: String(document.getElementById('competitionFieldList')?.value || '').trim(),
                fieldMode: String(document.getElementById('competitionFieldMode')?.value || 'single').trim()
            };
        }

        function applyParallelSchedulePresetPayload(p) {
            if (!p || typeof p !== 'object') return;
            const setVal = (id, v) => {
                const el = document.getElementById(id);
                if (!el || v === undefined || v === null) return;
                el.value = String(v);
            };
            setVal('competitionCalendarMode', p.calendarMode);
            setVal('competitionScheduleDayStartTime', p.scheduleDayStartTime);
            setVal('competitionScheduleSlotMinutes', p.scheduleSlotIntervalMinutes);
            setVal('competitionScheduleMatchDurationMinutes', Number(p.scheduleMatchDurationMinutes) > 0 ? String(p.scheduleMatchDurationMinutes) : '');
            setVal('competitionScheduleTurnoverMinutes', p.scheduleTurnoverMinutes != null ? String(p.scheduleTurnoverMinutes) : '10');
            setVal('competitionScheduleCategoryDurations', p.scheduleCategoryDurationsRaw || '');
            setVal('competitionScheduleMaxMatchesPerDay', p.scheduleMaxMatchesPerDay);
            setVal('competitionScheduleWeekdayDefaultEnd', p.scheduleWeekdayDefaultEnd);
            setVal('competitionScheduleWeekdayWindows', p.scheduleWeekdayWindowsRaw);
            setVal('competitionScheduleRuleOverrides', p.scheduleRuleOverridesRaw);
            setVal('competitionScheduleAgeSortMode', p.scheduleAgeSortMode);
            setVal('competitionScheduleCategoryCustomOrder', p.scheduleCategoryCustomOrderRaw);
            setVal('competitionScheduleSortCutoffTime', p.scheduleSortCutoffTime);
            setVal('competitionScheduleAgeSortAfterCutoff', p.scheduleAgeSortAfterCutoff);
            setVal('competitionScheduleClampMinTime', p.scheduleClampMinTime);
            setVal('competitionScheduleClampMaxTime', p.scheduleClampMaxTime);
            setVal('competitionDefaultField', p.defaultField);
            setVal('competitionFieldList', p.fieldListRaw);
            setVal('competitionFieldMode', p.fieldMode);
            const inv = document.getElementById('competitionScheduleCustomOrderInverted');
            if (inv) inv.checked = !!p.scheduleCustomOrderInverted;
            toggleParallelCalendarOptions();
        }

        function saveSchedulePresetFromForm() {
            if (!ensureCompetitionAdminAccess()) return;
            const name = prompt('Nombre de la plantilla de calendario:', '');
            if (name == null || !String(name).trim()) return;
            const list = readSchedulePresetsList();
            list.push({
                id: `SCHED_PRESET_${Date.now()}`,
                name: String(name).trim(),
                savedAt: new Date().toISOString(),
                ...gatherParallelSchedulePresetPayload()
            });
            writeSchedulePresetsList(list);
            refreshSchedulePresetSelect();
            const sel = document.getElementById('schedulePresetSelect');
            if (sel) sel.value = String(list.length - 1);
            alert('✅ Plantilla guardada');
        }

        function loadSchedulePresetIntoForm() {
            const sel = document.getElementById('schedulePresetSelect');
            const ix = parseInt(String(sel?.value || ''), 10);
            if (!sel || Number.isNaN(ix) || ix < 0) {
                alert('Selecciona una plantilla en la lista.');
                return;
            }
            const list = readSchedulePresetsList();
            const p = list[ix];
            if (!p) {
                alert('Plantilla no encontrada.');
                refreshSchedulePresetSelect();
                return;
            }
            applyParallelSchedulePresetPayload(p);
            alert(`Plantilla cargada: ${p.name || 'sin nombre'}`);
        }

        function deleteSelectedSchedulePreset() {
            if (!ensureCompetitionAdminAccess()) return;
            const sel = document.getElementById('schedulePresetSelect');
            const ix = parseInt(String(sel?.value || ''), 10);
            if (!sel || Number.isNaN(ix) || ix < 0) {
                alert('Selecciona una plantilla para eliminar.');
                return;
            }
            const list = readSchedulePresetsList();
            if (!list[ix]) {
                refreshSchedulePresetSelect();
                return;
            }
            if (!confirm(`¿Eliminar la plantilla "${list[ix].name || ix}"?`)) return;
            list.splice(ix, 1);
            writeSchedulePresetsList(list);
            refreshSchedulePresetSelect();
            alert('Plantilla eliminada');
        }

