            const tStart = document.getElementById('competitionScheduleDayStartTime');
            if (tStart) tStart.value = '09:00';
            const tSlot = document.getElementById('competitionScheduleSlotMinutes');
            if (tSlot) tSlot.value = '90';
            const tMat = document.getElementById('competitionScheduleMatchDurationMinutes');
            if (tMat) tMat.value = '';
