        function toggleCompetitionFields(opts) {
            const preserveValues = opts && opts.preserveValues === true;
            const competitionType = document.getElementById('competitionType').value;
            const maxTeamsField = document.getElementById('maxTeams');
            if (!maxTeamsField) return;
            if (competitionType === 'torneo') {
                maxTeamsField.max = '32';
                if (!preserveValues) maxTeamsField.value = '8';
            } else if (competitionType === 'liga') {
                maxTeamsField.max = '20';
                if (!preserveValues) maxTeamsField.value = '10';
            } else {
                maxTeamsField.max = '8';
                if (!preserveValues) maxTeamsField.value = '4';
            }
            updateCompetitionFormModeActions();
        }

        function normalizeCompetitionFormatType(value) {
            const raw = String(value || '').trim().toLowerCase();
            if (raw === 'futbol_sala' || raw === 'sala' || raw === 'futsal') return 'futbol_sala';
            if (raw === 'futbol_7' || raw === '7' || raw === 'f7') return 'futbol_7';
            if (raw === 'futbol_8' || raw === '8' || raw === 'f8') return 'futbol_8';
            if (raw === 'futbol_9' || raw === '9' || raw === 'f9') return 'futbol_9';
            if (raw === 'futbol_11' || raw === '11' || raw === 'f11') return 'futbol_11';
            return 'futbol_7';
        }

        function getCompetitionModeLabel(competition) {
            const formatType = normalizeCompetitionFormatType(
                competition?.formatType ||
                (competition?.sportMode === 'futbol_sala' ? 'futbol_sala' : `futbol_${competition?.footballFormat || '7'}`)
            );
            const map = {
                futbol_7: 'Fútbol 7',
                futbol_8: 'Fútbol 8',
                futbol_9: 'Fútbol 9',
                futbol_11: 'Fútbol 11',
                futbol_sala: 'Fútbol sala'
            };
            return map[formatType] || 'Fútbol 7';
        }

