        function parseDelimitedText(rawText) {
            const text = String(rawText || '').trim();
            if (!text) return [];
            const lines = text.split(/\r?\n/).filter(Boolean);
            if (!lines.length) return [];
            const delimiter = lines[0].includes(';') ? ';' : (lines[0].includes('\t') ? '\t' : ',');
            const headers = lines[0].split(delimiter).map(h => h.trim().replace(/(^"|"$)/g, ''));
            return lines.slice(1).map((line) => {
                const values = line.split(delimiter).map(v => v.trim().replace(/(^"|"$)/g, ''));
                const row = {};
                headers.forEach((h, i) => { row[h] = values[i] || ''; });
                return row;
            });
        }

        async function ensureScriptLoaded(url, globalName) {
            if (globalName && window[globalName]) return;
            await new Promise((resolve, reject) => {
                const existing = document.querySelector(`script[data-dyn="${url}"]`);
                if (existing) {
                    existing.addEventListener('load', () => resolve(), { once: true });
                    existing.addEventListener('error', () => reject(new Error(`No se pudo cargar ${url}`)), { once: true });
                    return;
                }
                const s = document.createElement('script');
                s.src = url;
                s.async = true;
                s.dataset.dyn = url;
                s.onload = () => resolve();
                s.onerror = () => reject(new Error(`No se pudo cargar ${url}`));
                document.head.appendChild(s);
            });
        }

        function parseCompetitionRowsFromWordText(text) {
            const lines = String(text || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean);
            const rows = [];
            lines.forEach((line) => {
                // Formato esperado: Nombre | Categoria | Tipo | Modalidad | Formato | Inicio | Fin | MaxEquipos
                const parts = line.split('|').map(p => p.trim());
                if (!parts[0] || parts[0].toLowerCase() === 'nombre') return;
                rows.push({
                    Nombre: parts[0] || '',
                    Categoria: parts[1] || '',
                    Tipo: parts[2] || '',
                    Modalidad: parts[3] || '',
                    Formato: parts[4] || '',
                    Inicio: parts[5] || '',
                    Fin: parts[6] || '',
                    MaxEquipos: parts[7] || ''
                });
            });
            return rows;
        }

        async function readOfficeLikeFile(file) {
            const ext = (file?.name || '').toLowerCase().split('.').pop();
            if (!ext) throw new Error('Archivo sin extensión');
            if (ext === 'csv' || ext === 'txt') {
                const raw = await file.text();
                return parseDelimitedText(raw);
            }
            if (ext === 'xls' || ext === 'xlsx') {
                await ensureScriptLoaded('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js', 'XLSX');
                const ab = await file.arrayBuffer();
                const wb = window.XLSX.read(ab, { type: 'array' });
                const firstSheetName = wb.SheetNames[0];
                if (!firstSheetName) return [];
                const json = window.XLSX.utils.sheet_to_json(wb.Sheets[firstSheetName], { defval: '' });
                return Array.isArray(json) ? json : [];
            }
            if (ext === 'docx') {
                await ensureScriptLoaded('https://cdn.jsdelivr.net/npm/mammoth@1.8.0/mammoth.browser.min.js', 'mammoth');
                const ab = await file.arrayBuffer();
                const result = await window.mammoth.extractRawText({ arrayBuffer: ab });
                return parseCompetitionRowsFromWordText(result.value || '');
            }
            if (ext === 'doc') {
                const raw = await file.text();
                return parseCompetitionRowsFromWordText(raw);
            }
            throw new Error('Formato no soportado. Usa CSV, Excel o Word.');
        }

        function printCompetitionImportReport(report) {
            const win = window.open('', '_blank');
            if (!win) return;
            const rowsHtml = (report.samples || []).map((r, i) => `<tr><td>${i + 1}</td><td>${r.name}</td><td>${r.category}</td><td>${r.type}</td><td>${r.mode}</td></tr>`).join('');
            win.document.write(`
                <html>
                <head><title>Informe importación competiciones</title></head>
                <body style="font-family: Arial, sans-serif; padding: 20px;">
                    <h2 style="margin:0;">CD Sanabria CF - Informe de importación</h2>
                    <p><strong>Archivo:</strong> ${report.fileName}<br>
                    <strong>Fecha:</strong> ${new Date().toLocaleString()}<br>
                    <strong>Importadas:</strong> ${report.imported}<br>
                    <strong>Omitidas:</strong> ${report.skipped}</p>
                    <table style="border-collapse: collapse; width:100%;">
                        <thead>
                            <tr>
                                <th style="border:1px solid #ccc; padding:6px;">#</th>
                                <th style="border:1px solid #ccc; padding:6px;">Nombre</th>
                                <th style="border:1px solid #ccc; padding:6px;">Categoría</th>
                                <th style="border:1px solid #ccc; padding:6px;">Tipo</th>
                                <th style="border:1px solid #ccc; padding:6px;">Modalidad</th>
                            </tr>
                        </thead>
                        <tbody>${rowsHtml || '<tr><td colspan="5" style="border:1px solid #ccc; padding:6px;">Sin muestra</td></tr>'}</tbody>
                    </table>
                </body>
                </html>
            `);
            win.document.close();
            win.focus();
            win.print();
        }

