        // ===== FUNCIONES PARA GESTIÓN DE SOCIOS =====
        function showAddMemberForm() {
            const form = document.getElementById('addMemberForm');
            if (form) {
                form.style.display = 'block';
                clearMemberForm();
            }
        }

        function cancelAddMember() {
            const form = document.getElementById('addMemberForm');
            if (form) {
                form.style.display = 'none';
                clearMemberForm();
            }
        }

        function clearMemberForm() {
            document.getElementById('memberName').value = '';
            document.getElementById('memberSurname').value = '';
            document.getElementById('memberDNI').value = '';
            document.getElementById('memberPhone').value = '';
            document.getElementById('memberAddress').value = '';
            document.getElementById('memberEmail').value = '';
            document.getElementById('memberPassword').value = '';
        }

        async function saveMember() {
            try {
                const name = document.getElementById('memberName').value.trim();
                const surname = document.getElementById('memberSurname').value.trim();
                const dni = document.getElementById('memberDNI').value.trim();
                const phone = document.getElementById('memberPhone').value.trim();
                const address = document.getElementById('memberAddress').value.trim();
                const email = document.getElementById('memberEmail').value.trim();
                const password = document.getElementById('memberPassword').value.trim();
                const sexo = document.getElementById('memberSexo').value;

                // Validar campos obligatorios
                if (!name || !surname || !sexo || !phone || !password) {
                    alert('❌ Error: Los campos Nombre, Apellidos, Sexo, Teléfono y Contraseña son obligatorios.');
                    return;
                }

                // Obtener socios existentes
                const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                
                // Verificar DNI único si se proporciona
                if (dni) {
                    const existingMember = members.find(m => m.dni && m.dni.toLowerCase() === dni.toLowerCase());
                    if (existingMember) {
                        alert('❌ Error: Ya existe un socio con ese DNI.');
                        return;
                    }
                }

                // Crear nuevo socio
                const newMember = {
                    id: 'MEMBER_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
                    name: name,
                    surname: surname,
                    nombre: name,
                    apellidos: surname,
                    sexo: sexo,
                    dni: dni,
                    phone: phone,
                    telefono: phone,
                    address: address,
                    direccion: address,
                    email: email,
                    status: 'pending_validation',
                    estado: 'pendiente',
                    registrationDate: new Date().toISOString(),
                    validatedBy: null,
                    validatedDate: null,
                    memberNumber: null,
                    appScope: 'cdsanabriacf',
                    registrationSource: 'admin_panel'
                };

                if (email && password && window.cdsanClubAuth && window.firebaseAuth && !window.firebaseAuth.isSimulation) {
                    try {
                        const reg = await window.cdsanClubAuth.registerEmail(String(email).trim().toLowerCase(), password);
                        if (!reg.simulation && reg.uid) {
                            newMember.authUid = reg.uid;
                            newMember.uid = reg.uid;
                        }
                    } catch (e) {
                        console.error('saveMember Firebase Auth:', e);
                        if (e && e.code === 'auth/email-already-in-use') {
                            alert('❌ Ese correo ya tiene cuenta Firebase. El socio puede iniciar sesión con su contraseña.');
                        } else {
                            alert('❌ No se pudo crear la cuenta de acceso del socio en Firebase.');
                        }
                        return;
                    }
                } else if (password && typeof window.hashClubAccessKey === 'function') {
                    newMember.passwordHash = await window.hashClubAccessKey(password);
                }

                // Agregar a la lista
                if (typeof window.applyClubRoleFlagsToMember === 'function') {
                    window.applyClubRoleFlagsToMember(newMember);
                }
                members.push(newMember);
                syncMembersLocalStorage(members);
                await persistMemberToFirebase(newMember);

                // Cerrar formulario y recargar lista
                cancelAddMember();
                loadMembersList();
                updateMemberCounts();
                updateDashboardCounts();

                alert('✅ Socio registrado.\n\n⚠️ Tiene 7 días para ingresar la cuota. Un administrador lo validará al ver el pago en la cuenta (cdsanabriafc@gmail.com).');
                console.log('👤 Nuevo socio registrado:', newMember.name + ' ' + newMember.surname);

            } catch (error) {
                console.error('❌ Error guardando socio:', error);
                alert('❌ Error al guardar el socio. Inténtalo de nuevo.');
            }
        }

        /** Unifica ES/EN + Firestore Timestamp serializado; evita "undefined" en plantillas */
        function cleanMemberStr(v) {
            if (v == null) return '';
            const s = String(v).trim();
            if (s === '' || s === 'undefined' || s === 'null' || s === 'Sin nombre' || s === 'Sin apellidos' || s === 'Sin teléfono' || s === 'Sin DNI') return '';
            return s;
        }
        function normalizeSexoField(m) {
            if (!m) return '';
            const raw = String(m.sexo || m.genero || '').trim().toLowerCase();
            if (['mujer', 'f', 'femenino', 'female', 'fem'].includes(raw)) return 'mujer';
            if (['hombre', 'm', 'masculino', 'male', 'masc'].includes(raw)) return 'hombre';
            return '';
        }
        function registrationDateToIso(m) {
            const raw = m.registrationDate || m.fechaRegistro || m.createdAt || m.fechaAlta;
            if (raw == null) return null;
            if (typeof raw === 'object' && typeof raw.seconds === 'number') {
                const d = new Date(raw.seconds * 1000 + (typeof raw.nanoseconds === 'number' ? raw.nanoseconds / 1e6 : 0));
                return isNaN(d.getTime()) ? null : d.toISOString();
            }
            try {
                if (typeof raw.toDate === 'function') {
                    const d = raw.toDate();
                    return isNaN(d.getTime()) ? null : d.toISOString();
                }
            } catch (e) {}
            const d = new Date(raw);
            return isNaN(d.getTime()) ? null : d.toISOString();
        }
        function normalizeClubMember(m) {
            if (!m || typeof m !== 'object') return { name: '', surname: '', phone: '', registrationDate: null, status: 'pending_validation' };
            const regIso = registrationDateToIso(m) || (m.registrationDate || m.fechaRegistro || null);
            let status = m.status;
            if (status == null || status === '') {
                const e = String(m.estado || '').toLowerCase();
                if (e === 'pendiente' || e === 'pending' || e === 'pending_validation') status = 'pending_validation';
                else if (e === 'activo' || e === 'active') status = 'active';
                else if (e === 'expirado' || e === 'expired' || e === 'caducado') status = 'expired';
            }
            if (!status) status = 'pending_validation';
            const name = cleanMemberStr(m.name) || cleanMemberStr(m.nombre) || cleanMemberStr(m.nombres) || cleanMemberStr(m.firstName);
            const surname = cleanMemberStr(m.surname) || cleanMemberStr(m.apellidos) || cleanMemberStr(m.apellido) || cleanMemberStr(m.lastName);
            const phone = cleanMemberStr(m.phone) || cleanMemberStr(m.telefono) || cleanMemberStr(m.movil);
            const address = cleanMemberStr(m.address) || cleanMemberStr(m.direccion);
            const normalized = {
                ...m,
                name,
                surname,
                phone,
                address,
                registrationDate: regIso,
                status,
                memberNumber: m.memberNumber != null && m.memberNumber !== '' ? m.memberNumber : m.numeroSocio,
                birthDate: m.birthDate || m.fechaNacimiento,
                sexo: normalizeSexoField(m) || ''
            };
            delete normalized.password;
            delete normalized.pass;
            delete normalized.plainPassword;
            return normalized;
        }

        /** Cuotas menores/mayores: valores en ClubAccounting (pestaña Contabilidad), por defecto 10/20/17. */

        function edadEnFechaReferencia(fechaNacStr, refDate) {
            if (!fechaNacStr) return null;
            const birth = new Date(fechaNacStr);
            const ref = refDate instanceof Date ? refDate : new Date(refDate);
            if (isNaN(birth.getTime()) || isNaN(ref.getTime())) return null;
            let age = ref.getFullYear() - birth.getFullYear();
            const md = ref.getMonth() - birth.getMonth();
            if (md < 0 || (md === 0 && ref.getDate() < birth.getDate())) age--;
            return age;
        }

        function cuotaSegunEdad(edad) {
            const p = typeof ClubAccounting !== 'undefined' ? ClubAccounting.getMembershipPricing() : { cuotaMenor: 10, cuotaMayor: 25, edadMaxMenor: 17 };
            if (edad == null || isNaN(edad)) return p.cuotaMayor;
            return edad <= p.edadMaxMenor ? p.cuotaMenor : p.cuotaMayor;
        }

        function getMembershipSeasonCfg() {
            return (typeof ClubMembershipSeason !== 'undefined' && ClubMembershipSeason.getConfig)
                ? ClubMembershipSeason.getConfig()
                : { closeMonth: 5, closeDay: 31, paymentDeadlineDays: 7, firstCloseYear: 2027 };
        }

        function fechaReferenciaCierreTemporada(anioRef) {
            const c = getMembershipSeasonCfg();
            return new Date(anioRef, c.closeMonth - 1, c.closeDay, 12, 0, 0, 0);
        }

        /** Año del cierre de temporada para calcular menor/mayor (ej. edad al 31/05/2027). */
        function cuotaSegunEdadAlCierre(member, anioRef) {
            const birth = member.birthDate || member.fechaNacimiento;
            const edad = edadEnFechaReferencia(birth, fechaReferenciaCierreTemporada(anioRef));
            return cuotaSegunEdad(edad);
        }

        function cuotaSegunEdadAl31Agosto(member, anioRef) {
            return cuotaSegunEdadAlCierre(member, anioRef);
        }

        function proximoCierreTemporada() {
            if (typeof ClubAccounting !== 'undefined' && typeof ClubAccounting.getProximaVigenciaCuotaHasta === 'function') {
                return ClubAccounting.getProximaVigenciaCuotaHasta();
            }
            if (typeof ClubMembershipSeason !== 'undefined') {
                return ClubMembershipSeason.getProximaVigenciaCuotaHasta();
            }
            return new Date(new Date().getFullYear(), 4, 31, 23, 59, 59, 999);
        }

        function proximoCierreTemporada31Agosto() {
            return proximoCierreTemporada();
        }

        function isMemberPendingRenewal(member) {
            const m = normalizeClubMember(member);
            return m.status === 'pending_validation' && m.pendingReason === 'renovacion';
        }

        function isMemberPendingNewAlta(member) {
            const m = normalizeClubMember(member);
            if (m.status !== 'pending_validation') return false;
            return m.pendingReason !== 'renovacion';
        }

        /** Solo altas nuevas offline (transferencia/efectivo/TPV): 7 días. Renovaciones: sin caducidad. */
        function getMemberPaymentDeadline(member) {
            const m = normalizeClubMember(member);
            if (m.pendingReason === 'renovacion') return null;
            const lim = m.fechaLimitePago || m.fechaVencimiento;
            if (lim) {
                const d = new Date(lim);
                if (!isNaN(d.getTime())) return d;
            }
            const reg = new Date(m.registrationDate || m.fechaRegistro);
            if (isNaN(reg.getTime())) return null;
            const days = getMembershipSeasonCfg().paymentDeadlineDays || 7;
            return new Date(reg.getTime() + days * 86400000);
        }

        function isPastMemberPaymentDeadline(member) {
            const m = normalizeClubMember(member);
            if (m.status !== 'pending_validation') return false;
            const dl = getMemberPaymentDeadline(m);
            if (!dl) return false;
            return new Date() > dl;
        }

        function dedupeMembersList(rawMembers) {
            const list = Array.isArray(rawMembers) ? rawMembers.map(normalizeClubMember) : [];
            const byIdentity = new Map();
            list.forEach((member) => {
                const key = memberIdentityKey(member) || `id:${String(member.id || '').trim()}`;
                if (!key) return;
                if (!byIdentity.has(key)) {
                    byIdentity.set(key, member);
                    return;
                }
                const merged = mergeMemberData(byIdentity.get(key), member);
                byIdentity.set(key, merged);
            });
            return Array.from(byIdentity.values());
        }

        function buildMemberFirebasePayload(m) {
            if (typeof window.applyClubRoleFlagsToMember === 'function') {
                window.applyClubRoleFlagsToMember(m);
            }
            const nm = normalizeClubMember(m);
            const st = nm.status || '';
            let estado = 'pendiente';
            if (st === 'active') estado = 'activo';
            else if (st === 'pending_validation') estado = 'pendiente';
            else if (st === 'expired') estado = 'caducado';
            const payload = {
                name: nm.name,
                nombre: nm.name,
                surname: nm.surname,
                apellidos: nm.surname,
                email: nm.email || '',
                telefono: nm.phone || '',
                phone: nm.phone || '',
                dni: nm.dni || '',
                direccion: nm.address || '',
                address: nm.address || '',
                status: st,
                estado,
                memberNumber: nm.memberNumber,
                numeroSocio: nm.memberNumber,
                birthDate: nm.birthDate,
                fechaNacimiento: nm.birthDate,
                lastModified: nm.lastModified,
                modifiedBy: nm.modifiedBy,
                pagado: nm.pagado === true || st === 'active',
                validatedBy: nm.validatedBy || null,
                validatedDate: nm.validatedDate || null,
                cuota: nm.cuota != null ? nm.cuota : null,
                pendingReason: nm.pendingReason || null,
                fechaLimitePago: nm.fechaLimitePago || null,
                fechaVencimiento: nm.fechaVencimiento || null,
                renovacionDesde: nm.renovacionDesde || null,
                renovacionTemporada: nm.renovacionTemporada || null,
                cuotaReferenciaEdad31Agosto: nm.cuotaReferenciaEdad31Agosto || nm.cuotaReferenciaEdadCierre || null,
                cuotaReferenciaEdadCierre: nm.cuotaReferenciaEdadCierre || nm.cuotaReferenciaEdad31Agosto || null,
                cuotaVigenteHasta: nm.cuotaVigenteHasta || null,
                diasLimiteRenovacion: typeof nm.diasLimiteRenovacion === 'number' ? nm.diasLimiteRenovacion : null,
                socioDeHonor: m.socioDeHonor === true,
                membershipTier: m.membershipTier || (m.socioDeHonor === true ? 'honor' : 'regular'),
                numeroSocioHonor: m.numeroSocioHonor != null ? m.numeroSocioHonor : null,
                numeroSocioRegular: m.numeroSocioRegular != null ? m.numeroSocioRegular : null
            };
            if (typeof window.appendClubRoleFlagsToPayload === 'function') {
                window.appendClubRoleFlagsToPayload(payload, m);
            }
            return payload;
        }

        async function refreshLinkedMemberRoles(dni, name, surname) {
            if (typeof window.refreshMembersRoleFlagsForIdentity !== 'function') return [];
            const touched = window.refreshMembersRoleFlagsForIdentity(dni, name, surname);
            for (let i = 0; i < touched.length; i++) {
                try {
                    await persistMemberToFirebase(touched[i]);
                } catch (e) {
                    console.warn('refreshLinkedMemberRoles Firebase:', e);
                }
            }
            return touched;
        }

        async function persistMemberToFirebase(member) {
            if (!member || !member.id) return;
            try {
                if (typeof window.applyClubRoleFlagsToMember === 'function') {
                    window.applyClubRoleFlagsToMember(member);
                }
                const payload = buildMemberFirebasePayload(member);
                const merged = { ...member, ...payload, appScope: 'cdsanabriacf', registrationSource: member.registrationSource || 'admin_panel' };

                if (window.AdminClubCloudPersist && typeof window.AdminClubCloudPersist.persistMember === 'function') {
                    try {
                        return await window.AdminClubCloudPersist.persistMember(merged);
                    } catch (netlifyErr) {
                        console.warn('Netlify socio (admin):', netlifyErr);
                        if (window.AdminClubCloudPersist.cloudRequired && window.AdminClubCloudPersist.cloudRequired()) {
                            throw netlifyErr;
                        }
                    }
                }

                if (String(member.id).startsWith('MEMBER_') && typeof window.createDocument === 'function') {
                    const newId = await window.createDocument('members', merged);
                    const all = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                    const ix = all.findIndex(m => m.id === member.id);
                    if (ix >= 0) {
                        all[ix] = { ...all[ix], id: newId };
                        syncMembersLocalStorage(all);
                    }
                    try { window.dispatchEvent(new CustomEvent('membersUpdated')); } catch (e2) {}
                    return;
                }
                if (typeof window.updateDocument === 'function') {
                    await window.updateDocument('members', member.id, payload);
                }
            } catch (e) {
                console.warn('No se pudo sincronizar socio con Firebase:', e);
                throw e;
            }
        }

        /** Borra el socio en Firestore (ID + email/DNI por si hay duplicados o ID distinto). */
        async function removeMemberFromCloudIfNeeded(memberId, identity) {
            if (!memberId) return;
            const id = String(memberId).trim();
            if (!id || id.startsWith('MEMBER_')) return;
            const ident = identity && typeof identity === 'object' ? identity : {};
            if (window.AdminClubCloudPersist && typeof window.AdminClubCloudPersist.deleteMember === 'function') {
                await window.AdminClubCloudPersist.deleteMember(id, ident);
                return;
            }
            if (typeof window.deleteDocument !== 'function') {
                throw new Error('La nube no está disponible: no se puede eliminar en el servidor');
            }
            await window.deleteDocument('members', id, 'admin');
        }

        function memberFullNameKey(member) {
            const m = normalizeClubMember(member);
            return `${String(m.name || m.nombre || '').trim()} ${String(m.surname || m.apellidos || '').trim()}`
                .trim()
                .toLowerCase();
        }

        function membersShareIdentity(a, b) {
            const ma = normalizeClubMember(a);
            const mb = normalizeClubMember(b);
            const dniA = String(ma.dni || '').trim().toLowerCase();
            const dniB = String(mb.dni || '').trim().toLowerCase();
            if (dniA && dniB && dniA === dniB) return true;
            const emA = String(ma.email || '').trim().toLowerCase();
            const emB = String(mb.email || '').trim().toLowerCase();
            const nameA = memberFullNameKey(ma);
            const nameB = memberFullNameKey(mb);
            if (emA && emB && emA === emB && nameA && nameB && nameA === nameB) return true;
            return false;
        }

        function memberIdentityKey(member) {
            const m = normalizeClubMember(member);
            const dni = String(m.dni || '').trim().toLowerCase();
            const email = String(m.email || '').trim().toLowerCase();
            const name = memberFullNameKey(m);
            const playerId = String(m.playerId || '').trim();
            if (dni) return `dni:${dni}`;
            if (playerId && (m.socioJugador || m.isJugador)) return `player:${playerId}`;
            if (email && name) return `email:${email}|name:${name}`;
            if (email) return `email:${email}`;
            return '';
        }

        function pickBetterMemberValue(current, candidate) {
            const c = (current == null ? '' : String(current)).trim();
            const n = (candidate == null ? '' : String(candidate)).trim();
            if (!c && n) return candidate;
            if (!n) return current;
            return current;
        }

        function mergeMemberData(keeper, duplicate) {
            const a = normalizeClubMember(keeper);
            const b = normalizeClubMember(duplicate);
            const merged = { ...a };
            const fields = [
                'name', 'nombre', 'surname', 'apellidos', 'email', 'dni', 'phone', 'telefono',
                'address', 'direccion', 'birthDate', 'fechaNacimiento', 'memberNumber', 'numeroSocio',
                'status', 'estado', 'registrationDate', 'fechaRegistro', 'consentimiento',
                'consentimientoFecha', 'consentimientoIP', 'proteccionDatos', 'notificaciones',
                'pendingReason', 'fechaLimitePago', 'fechaVencimiento', 'cuota', 'renovacionDesde',
                'renovacionTemporada', 'cuotaReferenciaEdad31Agosto', 'cuotaReferenciaEdadCierre', 'cuotaVigenteHasta', 'diasLimiteRenovacion', 'offlinePaymentChannel'
            ];
            fields.forEach((field) => {
                merged[field] = pickBetterMemberValue(merged[field], b[field]);
            });
            merged.email = String(merged.email || '').trim().toLowerCase();
            merged.dni = String(merged.dni || '').trim().toLowerCase();
            merged.appScope = 'cdsanabriacf';
            return merged;
        }

        async function regularizarSociosFirebase(options) {
            const opts = options || {};
            const dryRun = !!opts.dryRun;

            if (typeof window.getDocuments !== 'function' || typeof window.updateDocument !== 'function') {
                alert('❌ La nube no está disponible en este panel.');
                return { ok: false, error: 'firebase_not_ready' };
            }

            const socios = await window.getDocuments('members');
            const normalized = Array.isArray(socios) ? socios.map(normalizeClubMember) : [];
            const byKey = new Map();
            const duplicates = [];

            for (const socio of normalized) {
                const key = memberIdentityKey(socio);
                if (!key) continue;
                if (!byKey.has(key)) {
                    byKey.set(key, socio);
                } else {
                    const keeper = byKey.get(key);
                    const merged = mergeMemberData(keeper, socio);
                    byKey.set(key, merged);
                    duplicates.push({ keeperId: keeper.id || merged.id, duplicateId: socio.id, key, merged });
                }
            }

            let updated = 0;
            let deleted = 0;
            const errors = [];

            for (const [key, keeper] of byKey.entries()) {
                try {
                    const keeperId = keeper.id;
                    if (!keeperId) continue;
                    const payload = buildMemberFirebasePayload({
                        ...keeper,
                        email: String(keeper.email || '').trim().toLowerCase(),
                        dni: String(keeper.dni || '').trim().toLowerCase()
                    });
                    if (!dryRun) {
                        await window.updateDocument('members', keeperId, payload);
                    }
                    updated += 1;
                } catch (e) {
                    errors.push(`update(${key}): ${String(e?.message || e)}`);
                }
            }

            for (const dup of duplicates) {
                try {
                    if (!dup.duplicateId || dup.duplicateId === dup.keeperId) continue;
                    if (!dryRun) {
                        await removeMemberFromCloudIfNeeded(dup.duplicateId, {
                            email: dup.merged && dup.merged.email,
                            dni: dup.merged && dup.merged.dni
                        });
                    }
                    deleted += 1;
                } catch (e) {
                    errors.push(`delete(${dup.duplicateId}): ${String(e?.message || e)}`);
                }
            }

            const sociosFinal = await window.getDocuments('members');
            syncMembersLocalStorage(sociosFinal);
            try { loadMembersList(); updateMemberCounts(); } catch (_) {}

            const result = {
                ok: errors.length === 0,
                dryRun,
                totalInicial: normalized.length,
                actualizados: updated,
                duplicadosDetectados: duplicates.length,
                duplicadosEliminados: deleted,
                totalFinal: Array.isArray(sociosFinal) ? sociosFinal.length : 0,
                errores: errors
            };
            console.log('🧹 Regularización socios Firebase:', result);
            if (!dryRun) {
                alert(`✅ Regularización completada\n\nSocios iniciales: ${result.totalInicial}\nActualizados: ${result.actualizados}\nDuplicados eliminados: ${result.duplicadosEliminados}\nSocios finales: ${result.totalFinal}`);
            }
            return result;
        }

        async function sincronizarPanelDesdeFirebase() {
            if (typeof window.getDocuments !== 'function') {
                alert('❌ La nube no está disponible en este panel.');
                return { ok: false, error: 'firebase_not_ready' };
            }
            const [socios, amigos, jugadores, entrenadores, equipos, eventos, encuentros, directiva, competiciones] = await Promise.all([
                window.getDocuments('members'),
                window.getDocuments('friends'),
                window.getDocuments('players'),
                window.getDocuments('coaches'),
                window.getDocuments('teams'),
                window.getDocuments('events'),
                window.getDocuments('matches'),
                window.getDocuments('board'),
                window.getDocuments('competitions')
            ]);

            syncMembersLocalStorage(socios || []);
            syncFriendsLocalStorage(amigos || []);
            if (typeof window.syncClubPlayersLocal === 'function') window.syncClubPlayersLocal(jugadores || []);
            else {
                const jp = JSON.stringify(jugadores || []);
                localStorage.setItem('clubPlayers', jp);
                localStorage.setItem('players', jp);
            }
            if (typeof window.syncClubCoachesLocal === 'function') window.syncClubCoachesLocal(entrenadores || []);
            else {
                const ec = JSON.stringify(entrenadores || []);
                localStorage.setItem('clubCoaches', ec);
                localStorage.setItem('coaches', ec);
            }
            if (typeof window.syncClubBoardLocal === 'function') window.syncClubBoardLocal(directiva || []);
            else {
                const bd = JSON.stringify(directiva || []);
                localStorage.setItem('clubBoard', bd);
                localStorage.setItem('board', bd);
            }

            localStorage.setItem('clubTeams', JSON.stringify(equipos || []));
            localStorage.setItem('teams', JSON.stringify(equipos || []));
            localStorage.setItem('equipos', JSON.stringify(equipos || []));

            localStorage.setItem('clubEvents', JSON.stringify(eventos || []));
            localStorage.setItem('events', JSON.stringify(eventos || []));
            localStorage.setItem('allEvents', JSON.stringify(eventos || []));
            localStorage.setItem('encuentros', JSON.stringify(encuentros || []));
            localStorage.setItem('clubCompetitions', JSON.stringify(competiciones || []));
            localStorage.setItem('competitions', JSON.stringify(competiciones || []));

            try {
                loadMembersList(); updateMemberCounts();
                loadFriendsList(); updateFriendCounts();
                loadPlayersList(); loadCoachesList(); updateCoachCounts();
                loadTeamsCards(); loadEventsList(); loadUpcomingActivities();
                loadBoardMembersList(); loadCompetitionsList();
                if (typeof loadEncuentrosList === 'function') loadEncuentrosList();
                updateDashboardCounts();
                if (typeof updateDatabaseStats === 'function') updateDatabaseStats();
            } catch (_) {}

            const result = {
                ok: true,
                socios: (socios || []).length,
                amigos: (amigos || []).length,
                jugadores: (jugadores || []).length,
                entrenadores: (entrenadores || []).length,
                equipos: (equipos || []).length,
                eventos: (eventos || []).length
            };
            console.log('🔄 Panel sincronizado desde Firebase:', result);
            return result;
        }

        function normalizeSimpleText(v) {
            return String(v || '').trim();
        }

        function normalizeIdentity(v) {
            return String(v || '').trim().toLowerCase();
        }

        function buildRecordKey(record, kind) {
            if (kind === 'players') {
                const dni = normalizeIdentity(record.dni);
                const email = normalizeIdentity(record.email);
                const category = normalizeIdentity(record.category || record.categoria);
                const dorsal = normalizeIdentity(record.number || record.dorsal);
                const birthDate = normalizeIdentity(record.birthDate || record.fechaNacimiento);
                if (dni) return `dni:${dni}`;
                if (email) return `email:${email}`;
                if (category && dorsal) return `cat_dorsal:${category}:${dorsal}`;
                return `name_birth:${normalizeIdentity(record.name || record.nombre)}:${normalizeIdentity(record.surname || record.apellidos)}:${birthDate}`;
            }
            if (kind === 'coaches') {
                const dni = normalizeIdentity(record.dni);
                const email = normalizeIdentity(record.email);
                const team = normalizeIdentity(record.team || record.equipo);
                if (dni) return `dni:${dni}`;
                if (email) return `email:${email}`;
                return `team_name:${team}:${normalizeIdentity(record.name || record.nombre)}:${normalizeIdentity(record.surname || record.apellidos)}`;
            }
            if (kind === 'events') {
                const title = normalizeIdentity(record.title || record.titulo);
                const date = normalizeIdentity(record.date || record.fecha);
                const start = normalizeIdentity(record.startTime || record.horaInicio);
                const location = normalizeIdentity(record.location || record.ubicacion);
                return `event:${title}:${date}:${start}:${location}`;
            }
            return normalizeIdentity(record.id);
        }

        function mergeGenericRecord(keeper, duplicate) {
            const merged = { ...keeper };
            Object.keys(duplicate || {}).forEach((k) => {
                const current = merged[k];
                const incoming = duplicate[k];
                const c = normalizeSimpleText(current);
                const n = normalizeSimpleText(incoming);
                if ((!c && n) || (Array.isArray(current) && current.length === 0 && Array.isArray(incoming) && incoming.length > 0)) {
                    merged[k] = incoming;
                }
            });
            merged.appScope = 'cdsanabriacf';
            return merged;
        }

        async function regularizarColeccionFirebase(kind, options) {
            const opts = options || {};
            const dryRun = !!opts.dryRun;
            if (typeof window.getDocuments !== 'function' || typeof window.updateDocument !== 'function') {
                return { ok: false, error: 'firebase_not_ready', kind };
            }

            const rows = await window.getDocuments(kind);
            const normalized = Array.isArray(rows) ? rows : [];
            const byKey = new Map();
            const duplicates = [];

            normalized.forEach((row) => {
                const key = buildRecordKey(row, kind);
                if (!key) return;
                if (!byKey.has(key)) {
                    byKey.set(key, row);
                } else {
                    const keeper = byKey.get(key);
                    const merged = mergeGenericRecord(keeper, row);
                    byKey.set(key, merged);
                    duplicates.push({ keeperId: keeper.id || merged.id, duplicateId: row.id, key, merged });
                }
            });

            let updated = 0;
            let deleted = 0;
            const errors = [];

            for (const [key, keeper] of byKey.entries()) {
                try {
                    if (!keeper?.id) continue;
                    if (!dryRun) {
                        await window.updateDocument(kind, keeper.id, mergeGenericRecord(keeper, {}));
                    }
                    updated += 1;
                } catch (e) {
                    errors.push(`update(${kind}:${key}): ${String(e?.message || e)}`);
                }
            }

            for (const dup of duplicates) {
                try {
                    if (!dup.duplicateId || dup.duplicateId === dup.keeperId) continue;
                    if (!dryRun && typeof window.deleteDocument === 'function') {
                        await window.deleteDocument(kind, dup.duplicateId, 'admin');
                    }
                    deleted += 1;
                } catch (e) {
                    errors.push(`delete(${kind}:${dup.duplicateId}): ${String(e?.message || e)}`);
                }
            }

            return {
                ok: errors.length === 0,
                kind,
                dryRun,
                totalInicial: normalized.length,
                actualizados: updated,
                duplicadosDetectados: duplicates.length,
                duplicadosEliminados: deleted,
                errores: errors
            };
        }

        async function regularizarDatosDeportivosFirebase(options) {
            const opts = options || {};
            const dryRun = !!opts.dryRun;
            const [players, coaches, events] = await Promise.all([
                regularizarColeccionFirebase('players', { dryRun }),
                regularizarColeccionFirebase('coaches', { dryRun }),
                regularizarColeccionFirebase('events', { dryRun })
            ]);

            const syncResult = await sincronizarPanelDesdeFirebase();
            const result = {
                ok: players.ok && coaches.ok && events.ok,
                dryRun,
                players,
                coaches,
                events,
                sync: syncResult
            };
            console.log('🧹 Regularización deportiva Firebase:', result);
            if (!dryRun) {
                alert(
                    `✅ Regularización deportiva completada\n\n` +
                    `Jugadores: ${players.totalInicial} -> dup ${players.duplicadosEliminados}\n` +
                    `Entrenadores: ${coaches.totalInicial} -> dup ${coaches.duplicadosEliminados}\n` +
                    `Eventos: ${events.totalInicial} -> dup ${events.duplicadosEliminados}`
                );
            }
            return result;
        }

        window.regularizarSociosFirebase = regularizarSociosFirebase;
        window.sincronizarPanelDesdeFirebase = sincronizarPanelDesdeFirebase;
        window.regularizarDatosDeportivosFirebase = regularizarDatosDeportivosFirebase;

        function normalizeClubFriend(f) {
            if (!f || typeof f !== 'object') {
                return { name: '', surname: '', phone: '', email: '', dni: '', status: 'active' };
            }
            return {
                ...f,
                name: (f.name || f.nombre || '').toString().trim(),
                surname: (f.surname || f.apellidos || '').toString().trim(),
                phone: (f.phone || f.telefono || '').toString().trim(),
                email: (f.email || '').toString().trim(),
                dni: (f.dni || '').toString().trim(),
                status: f.status || 'active'
            };
        }

        function buildFriendFirebasePayload(f) {
            const fr = normalizeClubFriend(f);
            const payload = {
                name: fr.name,
                nombre: fr.name,
                surname: fr.surname,
                apellidos: fr.surname,
                email: fr.email,
                telefono: fr.phone,
                phone: fr.phone,
                dni: fr.dni,
                status: fr.status,
                estado: fr.status === 'active' ? 'activo' : 'inactivo',
                registrationDate: fr.registrationDate,
                lastAccess: fr.lastAccess,
                accessCount: fr.accessCount
            };
            return payload;
        }

        function syncMembersLocalStorage(members) {
            if (typeof window.syncClubMembersLocal === 'function') {
                window.syncClubMembersLocal(members);
                return;
            }
            const list = Array.isArray(members) ? members : [];
            const json = JSON.stringify(list);
            localStorage.setItem('clubMembers', json);
            localStorage.setItem('members', json);
            localStorage.setItem('socios', json);
            localStorage.setItem('allMembers', json);
        }

        function syncFriendsLocalStorage(friends) {
            if (typeof window.syncClubFriendsLocal === 'function') {
                window.syncClubFriendsLocal(friends);
                return;
            }
            const list = Array.isArray(friends) ? friends : [];
            const json = JSON.stringify(list);
            localStorage.setItem('clubFriends', json);
            localStorage.setItem('friends', json);
            localStorage.setItem('amigos', json);
            localStorage.setItem('allFriends', json);
        }

        function readClubDataArray(primaryKey, fallbackKeys) {
            const keys = [primaryKey].concat(fallbackKeys || []);
            for (let i = 0; i < keys.length; i++) {
                try {
                    const raw = localStorage.getItem(keys[i]);
                    if (!raw) continue;
                    const list = JSON.parse(raw);
                    if (Array.isArray(list)) return list;
                } catch (_) {}
            }
            return [];
        }

        function formatDbPreviewRow(item, type) {
            const nombre = item.name || item.nombre || '';
            const apellidos = item.surname || item.apellidos || '';
            const email = item.email || '';
            const estado = item.status || item.estado || '';
            const id = item.id || '';
            const roles = [];
            if (item.isJugador) roles.push('jugador');
            if (item.isEntrenador) roles.push('entrenador');
            if (item.isDirectiva || item.isBoardMember) roles.push('directiva');
            const rolesTxt = roles.length ? ` · también: ${roles.join(', ')}` : '';
            return `${nombre} ${apellidos}`.trim() + (email ? ` · ${email}` : '') + (estado ? ` · ${estado}` : '') + rolesTxt + (id ? ` · id:${id}` : '');
        }

        async function persistFriendToFirebase(friend) {
            if (!friend || !friend.id) return;
            try {
                const payload = buildFriendFirebasePayload(friend);
                const merged = { ...friend, ...payload, appScope: 'cdsanabriacf', registrationSource: friend.registrationSource || 'admin_panel' };

                if (window.AdminClubCloudPersist && typeof window.AdminClubCloudPersist.persistFriend === 'function') {
                    try {
                        return await window.AdminClubCloudPersist.persistFriend(merged);
                    } catch (netlifyErr) {
                        console.warn('Netlify amigo (admin):', netlifyErr);
                        if (window.AdminClubCloudPersist.cloudRequired && window.AdminClubCloudPersist.cloudRequired()) {
                            throw netlifyErr;
                        }
                    }
                }

                if (String(friend.id).startsWith('FRIEND_') && typeof window.createDocument === 'function') {
                    const newId = await window.createDocument('friends', merged);
                    const all = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                    const ix = all.findIndex(f => f.id === friend.id);
                    if (ix >= 0) {
                        all[ix] = { ...all[ix], id: newId };
                        syncFriendsLocalStorage(all);
                    }
                    try { window.dispatchEvent(new CustomEvent('friendsUpdated')); } catch (e2) {}
                    return;
                }
                if (typeof window.updateDocument === 'function') {
                    await window.updateDocument('friends', friend.id, payload);
                }
            } catch (e) {
                console.warn('No se pudo sincronizar amigo con Firebase:', e);
                throw e;
            }
        }

        /** Borra el amigo en Firestore. IDs locales FRIEND_* (aún no creados en nube): solo se quita en local. */
        async function removeFriendFromCloudIfNeeded(friendId) {
            if (!friendId) return;
            const id = String(friendId).trim();
            if (!id || id.startsWith('FRIEND_')) return;
            if (window.AdminClubCloudPersist && typeof window.AdminClubCloudPersist.deleteFriend === 'function') {
                await window.AdminClubCloudPersist.deleteFriend(id);
                return;
            }
            if (typeof window.deleteDocument !== 'function') {
                throw new Error('La nube no está disponible: no se puede eliminar en el servidor');
            }
            await window.deleteDocument('friends', id, 'admin');
        }

        function isTemporaryLocalId(id) {
            const v = String(id || '');
            if (!v) return true;
            return (
                v.startsWith('PLAYER_') ||
                v.startsWith('TEAM_') ||
                v.startsWith('COMP_') ||
                v.startsWith('GUEST_') ||
                v.startsWith('CALENDAR_') ||
                v.startsWith('MSG_ADMIN_') ||
                v.startsWith('MEDIA_') ||
                /^\d{12,}$/.test(v)
            );
        }

        async function persistRecordToFirebase(localKey, collectionKey, record) {
            if (!record || typeof record !== 'object') return null;

            const netlifyMap = {
                members: 'member',
                friends: 'friend',
                players: 'player',
                coaches: 'coach'
            };
            const netlifyKind = netlifyMap[collectionKey];
            if (netlifyKind && window.AdminClubCloudPersist && typeof window.AdminClubCloudPersist.persist === 'function') {
                try {
                    const saved = await window.AdminClubCloudPersist.persist(netlifyKind, {
                        ...record,
                        appScope: 'cdsanabriacf',
                        registrationSource: record.registrationSource || 'admin_panel'
                    });
                    if (saved && saved.id && localKey) {
                        const list = JSON.parse(localStorage.getItem(localKey) || '[]');
                        const ix = list.findIndex((x) => x && x.id === record.id);
                        if (ix >= 0) {
                            list[ix] = { ...list[ix], ...saved };
                            localStorage.setItem(localKey, JSON.stringify(list));
                        }
                    }
                    return saved || record;
                } catch (netlifyErr) {
                    console.warn('Netlify persist (' + collectionKey + '):', netlifyErr);
                    if (window.AdminClubCloudPersist.cloudRequired && window.AdminClubCloudPersist.cloudRequired()) {
                        throw netlifyErr;
                    }
                }
            }

            if (typeof window.createDocument !== 'function' || typeof window.updateDocument !== 'function') return record;

            const localId = record.id;
            const useCreate = isTemporaryLocalId(localId);

            try {
                if (useCreate) {
                    const newId = await window.createDocument(collectionKey, record);
                    if (newId && localKey) {
                        const list = JSON.parse(localStorage.getItem(localKey) || '[]');
                        const ix = list.findIndex((x) => x && x.id === localId);
                        if (ix >= 0) {
                            list[ix] = { ...list[ix], id: newId };
                            localStorage.setItem(localKey, JSON.stringify(list));
                            return list[ix];
                        }
                    }
                    return { ...record, id: newId || localId };
                }

                await window.updateDocument(collectionKey, localId, record);
                return record;
            } catch (e) {
                // Fallback seguro: si update falla, intentar create.
                try {
                    const newId = await window.createDocument(collectionKey, record);
                    if (newId && localKey) {
                        const list = JSON.parse(localStorage.getItem(localKey) || '[]');
                        const ix = list.findIndex((x) => x && x.id === localId);
                        if (ix >= 0) {
                            list[ix] = { ...list[ix], id: newId };
                            localStorage.setItem(localKey, JSON.stringify(list));
                            return list[ix];
                        }
                    }
                    return { ...record, id: newId || localId };
                } catch (e2) {
                    console.warn(`No se pudo sincronizar ${collectionKey} con Firebase:`, e2);
                    return record;
                }
            }
        }

        async function deleteRecordFromFirebase(collectionKey, id) {
            if (!id || typeof window.deleteDocument !== 'function') return;
            try {
                await window.deleteDocument(collectionKey, id, 'admin');
            } catch (e) {
                console.warn(`No se pudo eliminar ${collectionKey}/${id} en Firebase:`, e);
            }
        }

        function escapeHtmlContabilidad(s) {
            return String(s == null ? '' : s)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;');
        }

        function ensureContabLedgerDelegation() {
            if (window._contabLedgerDelegationReady) return;
            window._contabLedgerDelegationReady = true;
            document.addEventListener('click', function (ev) {
                const btn = ev.target.closest && ev.target.closest('.contab-ledger-btn');
                if (!btn) return;
                const host = document.getElementById('contabilidad');
                if (!host || !host.contains(btn)) return;
                const act = btn.getAttribute('data-act');
                let id = '';
                try {
                    id = decodeURIComponent(btn.getAttribute('data-id') || '');
                } catch (e) {
                    return;
                }
                if (!act || !id) return;
                ev.preventDefault();
                if (act === 'edit') contabilidadAbrirEditar(id);
                else if (act === 'del') contabilidadEliminarAsiento(id);
                else if (act === 'swap') contabilidadToggleCaja(id);
            });
        }

        function contabIsoToDatetimeLocal(iso) {
            const d = new Date(iso);
            if (isNaN(d.getTime())) return '';
            const pad = (n) => String(n).padStart(2, '0');
            return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
        }

        function contabDatetimeLocalToIso(s) {
            const d = new Date(s);
            return isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
        }

        function getContabilidadRowsForInforme(desde, hasta) {
            if (typeof ClubAccounting === 'undefined') return [];
            const all = ClubAccounting.readLedger();
            const filtered = ClubAccounting.filterLedgerByDateRange(all, desde || '', hasta || '');
            return ClubAccounting.sortLedgerAsc(filtered);
        }

        function buildContabilidadInformeHtml(desde, hasta) {
            const rows = getContabilidadRowsForInforme(desde, hasta);
            const b = ClubAccounting.getBalances();
            const sumA = rows.reduce((acc, e) => acc + (e.bucket !== 'B' ? Number(e.signedAmount || 0) : 0), 0);
            const sumB = rows.reduce((acc, e) => acc + (e.bucket === 'B' ? Number(e.signedAmount || 0) : 0), 0);
            const rangeLabel = (!desde && !hasta) ? 'Todo el historial' : `${desde || '…'} — ${hasta || '…'}`;
            const tableRows = rows.map((e) => {
                const dt = new Date(e.createdAt);
                const fecha = isNaN(dt.getTime()) ? '—' : dt.toLocaleString('es-ES');
                const imp = Number(e.signedAmount || 0);
                return `<tr><td>${escapeHtmlContabilidad(fecha)}</td><td>${e.bucket === 'B' ? 'B' : 'A'}</td><td style="text-align:right">${imp.toFixed(2)}</td><td>${escapeHtmlContabilidad(e.category)}</td><td>${escapeHtmlContabilidad(e.concept)}</td></tr>`;
            }).join('');
            return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Informe contabilidad</title></head><body>
<h1>CD Sanabria CF — Libro de cuentas</h1>
<p><strong>Período:</strong> ${escapeHtmlContabilidad(rangeLabel)}</p>
<p>Asientos incluidos: ${rows.length}</p>
<table border="1" cellspacing="0" cellpadding="6" style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:11pt;">
<thead><tr><th>Fecha</th><th>Caja</th><th>Importe (€)</th><th>Categoría</th><th>Concepto</th></tr></thead>
<tbody>${tableRows}</tbody></table>
<p><strong>Suma de movimientos en el período</strong> — Caja A: ${sumA.toFixed(2).replace('.', ',')} € · Caja B: ${sumB.toFixed(2).replace('.', ',')} €</p>
<p><strong>Saldos actuales (suma de todo el libro)</strong> — A: ${b.A.toFixed(2).replace('.', ',')} € · B: ${b.B.toFixed(2).replace('.', ',')} €</p>
<p style="color:#666;font-size:10pt;">Generado el ${escapeHtmlContabilidad(new Date().toLocaleString('es-ES'))}</p>
</body></html>`;
        }

        function exportContabilidadWord() {
            if (typeof ClubAccounting === 'undefined') return;
            const d0 = (document.getElementById('contabRangoDesde') || {}).value || '';
            const d1 = (document.getElementById('contabRangoHasta') || {}).value || '';
            const rows = getContabilidadRowsForInforme(d0, d1);
            if (!rows.length) {
                alert('No hay asientos en el rango indicado (o el libro está vacío).');
                return;
            }
            const html = buildContabilidadInformeHtml(d0, d1);
            const fn = `informe_contabilidad_${d0 || 'inicio'}_${d1 || 'fin'}.doc`.replace(/[^\w.-]/g, '_');
            downloadBlobFile('\ufeff' + html, fn, 'application/msword;charset=utf-8;');
            alert(`✅ Informe Word generado (${rows.length} asientos).`);
        }

        function exportContabilidadPdf() {
            if (typeof ClubAccounting === 'undefined') return;
            const d0 = (document.getElementById('contabRangoDesde') || {}).value || '';
            const d1 = (document.getElementById('contabRangoHasta') || {}).value || '';
            const rows = getContabilidadRowsForInforme(d0, d1);
            if (!rows.length) {
                alert('No hay asientos en el rango indicado (o el libro está vacío).');
                return;
            }
            const html = buildContabilidadInformeHtml(d0, d1);
            const w = window.open('', '_blank');
            if (!w) {
                alert('Permite ventanas emergentes. Luego usa Imprimir → Guardar como PDF.');
                return;
            }
            w.document.open();
            w.document.write(html);
            w.document.close();
            w.focus();
            setTimeout(function () {
                try {
                    w.print();
                } catch (e) {
                    console.warn(e);
                }
            }, 400);
        }

        function contabilidadRound2(n) {
            return Math.round(Number(n) * 100) / 100;
        }

        /** Saldos A/B sumando todo lo anterior al primer movimiento del listado exportado (coherente con filtros solo-hasta, etc.). */
        function contabilidadOpeningBeforeFirstRow(rowsAsc) {
            if (typeof ClubAccounting === 'undefined' || !rowsAsc || !rowsAsc.length) {
                return { A: 0, B: 0 };
            }
            const tFirst = new Date(rowsAsc[0].createdAt).getTime();
            if (isNaN(tFirst)) return { A: 0, B: 0 };
            const all = ClubAccounting.readLedger();
            let A = 0;
            let B = 0;
            for (let i = 0; i < all.length; i++) {
                const e = all[i];
                const t = new Date(e.createdAt).getTime();
                if (isNaN(t) || t >= tFirst) continue;
                const amt = Number(e.signedAmount || 0);
                if (e.bucket === 'B') B += amt;
                else A += amt;
            }
            return { A: contabilidadRound2(A), B: contabilidadRound2(B) };
        }

        function contabilidadPeriodTotals(rows) {
            let ingA = 0;
            let gasA = 0;
            let ingB = 0;
            let gasB = 0;
            rows.forEach((e) => {
                const v = Number(e.signedAmount || 0);
                if (e.bucket === 'B') {
                    if (v > 0) ingB += v;
                    else if (v < 0) gasB += -v;
                } else if (v > 0) ingA += v;
                else if (v < 0) gasA += -v;
            });
            return {
                ingA: contabilidadRound2(ingA),
                gasA: contabilidadRound2(gasA),
                ingB: contabilidadRound2(ingB),
                gasB: contabilidadRound2(gasB),
                netA: contabilidadRound2(ingA - gasA),
                netB: contabilidadRound2(ingB - gasB)
            };
        }

        function contabilidadClosingForPeriod(opening, rows) {
            let A = opening.A;
            let B = opening.B;
            rows.forEach((e) => {
                const v = Number(e.signedAmount || 0);
                if (e.bucket === 'B') B += v;
                else A += v;
            });
            return { A: contabilidadRound2(A), B: contabilidadRound2(B) };
        }

        function contabilidadApplySheetColWidths(ws, widths) {
            if (!ws || !widths || !widths.length) return;
            ws['!cols'] = widths.map((wch) => ({ wch }));
        }

        async function exportContabilidadExcel() {
            if (typeof ClubAccounting === 'undefined') return;
            const d0 = (document.getElementById('contabRangoDesde') || {}).value || '';
            const d1 = (document.getElementById('contabRangoHasta') || {}).value || '';
            const rows = getContabilidadRowsForInforme(d0, d1);
            if (!rows.length) {
                alert('No hay asientos en el rango indicado (o el libro está vacío).');
                return;
            }
            try {
                await ensureScriptLoaded('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js', 'XLSX');
            } catch (err) {
                alert('No se pudo cargar la librería Excel. Comprueba la conexión a Internet.');
                console.warn(err);
                return;
            }
            const XLSX = window.XLSX;
            const opening = contabilidadOpeningBeforeFirstRow(rows);
            const pt = contabilidadPeriodTotals(rows);
            const cierre = contabilidadClosingForPeriod(opening, rows);
            const gb = ClubAccounting.getBalances();
            const rangeLabel = !d0 && !d1 ? 'Todo el historial' : `${d0 || '—'} → ${d1 || '—'}`;

            const resAoa = [
                ['CD SANABRIA CF — INFORME CONTABLE'],
                [],
                ['Período del informe', rangeLabel],
                ['Generado', new Date().toLocaleString('es-ES', { dateStyle: 'long', timeStyle: 'short' })],
                ['Movimientos incluidos', rows.length],
                [],
                ['Saldos al cierre previo al primer movimiento del informe', ''],
                ['  Caja A — Banco (€)', opening.A],
                ['  Caja B — Efectivo (€)', opening.B],
                [],
                ['Totales del período mostrado (entradas / salidas)', ''],
                ['  Caja A — Entradas (€)', pt.ingA],
                ['  Caja A — Salidas (€)', pt.gasA],
                ['  Caja A — Neto (€)', pt.netA],
                [],
                ['  Caja B — Entradas (€)', pt.ingB],
                ['  Caja B — Salidas (€)', pt.gasB],
                ['  Caja B — Neto (€)', pt.netB],
                [],
                ['Cierre tras el último movimiento del informe', ''],
                ['  Caja A — Banco (€)', cierre.A],
                ['  Caja B — Efectivo (€)', cierre.B],
                [],
                ['Saldos globales actuales (todo el libro)', ''],
                ['  Caja A — Banco (€)', gb.A],
                ['  Caja B — Efectivo (€)', gb.B]
            ];

            const wsRes = XLSX.utils.aoa_to_sheet(resAoa);
            wsRes['!merges'] = [{ s: { r: 0, c: 0 }, e: { r: 0, c: 3 } }];
            contabilidadApplySheetColWidths(wsRes, [48, 22]);

            const movHead = [
                'Nº',
                'Fecha y hora',
                'Caja',
                'Entrada (€)',
                'Salida (€)',
                'Neto (€)',
                'Saldo acum. A (€)',
                'Saldo acum. B (€)',
                'Categoría',
                'Concepto',
                'Referencia'
            ];
            const movAoa = [movHead];
            let runA = opening.A;
            let runB = opening.B;
            rows.forEach((e, idx) => {
                const amt = Number(e.signedAmount || 0);
                const ent = amt > 0 ? contabilidadRound2(amt) : '';
                const sal = amt < 0 ? contabilidadRound2(Math.abs(amt)) : '';
                if (e.bucket === 'B') runB += amt;
                else runA += amt;
                runA = contabilidadRound2(runA);
                runB = contabilidadRound2(runB);
                const dt = new Date(e.createdAt);
                const fh = isNaN(dt.getTime()) ? '—' : dt.toLocaleString('es-ES');
                const ref = [e.refType, e.refId].filter(Boolean).join(' · ');
                const cajaLabel = e.bucket === 'B' ? 'B — Efectivo' : 'A — Banco';
                movAoa.push([
                    idx + 1,
                    fh,
                    cajaLabel,
                    ent === '' ? '' : ent,
                    sal === '' ? '' : sal,
                    contabilidadRound2(amt),
                    runA,
                    runB,
                    e.category || '',
                    e.concept || '',
                    ref
                ]);
            });
            const wsMov = XLSX.utils.aoa_to_sheet(movAoa);
            contabilidadApplySheetColWidths(wsMov, [5, 20, 16, 12, 12, 11, 17, 17, 18, 48, 22]);

            const catMap = new Map();
            rows.forEach((e) => {
                const caja = e.bucket === 'B' ? 'B' : 'A';
                const key = `${e.category || '—'}|${caja}`;
                const o = catMap.get(key) || { categoria: e.category || '—', caja, ing: 0, gas: 0 };
                const v = Number(e.signedAmount || 0);
                if (v > 0) o.ing += v;
                else if (v < 0) o.gas += -v;
                catMap.set(key, o);
            });
            const catAoa = [['Categoría', 'Caja', 'Entradas (€)', 'Salidas (€)', 'Neto (€)']];
            Array.from(catMap.values())
                .sort((a, b) => String(a.categoria).localeCompare(String(b.categoria), 'es') || a.caja.localeCompare(b.caja))
                .forEach((o) => {
                    catAoa.push([
                        o.categoria,
                        o.caja === 'B' ? 'B — Efectivo' : 'A — Banco',
                        contabilidadRound2(o.ing),
                        contabilidadRound2(o.gas),
                        contabilidadRound2(o.ing - o.gas)
                    ]);
                });
            const wsCat = XLSX.utils.aoa_to_sheet(catAoa);
            contabilidadApplySheetColWidths(wsCat, [30, 16, 14, 14, 12]);

            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, wsRes, 'Resumen');
            XLSX.utils.book_append_sheet(wb, wsMov, 'Movimientos');
            XLSX.utils.book_append_sheet(wb, wsCat, 'Por categoría');

            const buf = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
            const fn = `informe_contabilidad_${d0 || 'inicio'}_${d1 || 'fin'}.xlsx`.replace(/[^\w.-]/g, '_');
            downloadBlobFile(buf, fn, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
            alert(`✅ Excel generado (${rows.length} movimientos · 3 hojas: Resumen, Movimientos, Por categoría).`);
        }

        function contabilidadLimpiarRango() {
            const a = document.getElementById('contabRangoDesde');
            const b = document.getElementById('contabRangoHasta');
            if (a) a.value = '';
            if (b) b.value = '';
            loadContabilidadPanel();
        }

        function loadContabilidadPanel() {
            try {
                ensureContabLedgerDelegation();
                if (typeof ClubAccounting === 'undefined') return;
                ClubAccounting.ensureDefaultPricing();
                const bal = ClubAccounting.getBalances();
                const elA = document.getElementById('contabSaldoA');
                const elB = document.getElementById('contabSaldoB');
                if (elA) elA.textContent = bal.A.toFixed(2).replace('.', ',') + ' €';
                if (elB) elB.textContent = bal.B.toFixed(2).replace('.', ',') + ' €';
                const p = ClubAccounting.getMembershipPricing();
                const cm = document.getElementById('contabCuotaMenor');
                const cmy = document.getElementById('contabCuotaMayor');
                const ce = document.getElementById('contabEdadMenor');
                if (cm) cm.value = p.cuotaMenor;
                if (cmy) cmy.value = p.cuotaMayor;
                if (ce) ce.value = p.edadMaxMenor;
                const desde = (document.getElementById('contabRangoDesde') || {}).value || '';
                const hasta = (document.getElementById('contabRangoHasta') || {}).value || '';
                let ledger = ClubAccounting.filterLedgerByDateRange(ClubAccounting.readLedger(), desde, hasta);
                ledger = ClubAccounting.sortLedgerDesc(ledger);
                const maxRows = 500;
                if (ledger.length > maxRows) ledger = ledger.slice(0, maxRows);
                const tbody = document.getElementById('contabLedgerBody');
                if (tbody) {
                    if (!ledger.length) {
                        tbody.innerHTML = '<tr><td colspan="6" style="padding:12px;color:#64748b;">Sin movimientos en este rango (o aún no hay asientos).</td></tr>';
                    } else {
                        tbody.innerHTML = ledger.map((e) => {
                            const d = new Date(e.createdAt);
                            const fecha = isNaN(d.getTime()) ? '—' : d.toLocaleString('es-ES');
                            const imp = Number(e.signedAmount || 0);
                            const impStr = (imp >= 0 ? '+' : '') + imp.toFixed(2) + ' €';
                            const color = imp >= 0 ? '#059669' : '#dc2626';
                            const idAttr = encodeURIComponent(String(e.id));
                            const cat = escapeHtmlContabilidad(e.category || '');
                            const con = escapeHtmlContabilidad(e.concept || '');
                            return '<tr style="border-bottom:1px solid #e2e8f0;">' +
                                '<td style="padding:8px;">' + escapeHtmlContabilidad(fecha) + '</td>' +
                                '<td style="padding:8px;text-align:center;">' + (e.bucket === 'B' ? 'B' : 'A') + '</td>' +
                                '<td style="padding:8px;text-align:right;font-weight:600;color:' + color + ';">' + impStr + '</td>' +
                                '<td style="padding:8px;">' + cat + '</td>' +
                                '<td style="padding:8px;">' + con + '</td>' +
                                '<td style="padding:8px;text-align:center;white-space:nowrap;">' +
                                '<button type="button" class="contab-ledger-btn" data-act="edit" data-id="' + idAttr + '" style="margin:2px;padding:4px 8px;font-size:0.75rem;cursor:pointer;border-radius:4px;border:1px solid #cbd5e1;background:#f8fafc;">Editar</button> ' +
                                '<button type="button" class="contab-ledger-btn" data-act="swap" data-id="' + idAttr + '" title="Cambiar A↔B" style="margin:2px;padding:4px 8px;font-size:0.75rem;cursor:pointer;border-radius:4px;border:1px solid #cbd5e1;background:#eef2ff;">A↔B</button> ' +
                                '<button type="button" class="contab-ledger-btn" data-act="del" data-id="' + idAttr + '" style="margin:2px;padding:4px 8px;font-size:0.75rem;cursor:pointer;border-radius:4px;border:1px solid #fecaca;background:#fef2f2;color:#991b1b;">Borrar</button>' +
                                '</td>' +
                                '</tr>';
                        }).join('');
                    }
                }
            } catch (err) {
                console.warn('Contabilidad:', err);
            }
        }

        function contabilidadAbrirEditar(id) {
            if (typeof ClubAccounting === 'undefined') return;
            const row = ClubAccounting.getEntryById(id);
            if (!row) {
                alert('Asiento no encontrado.');
                return;
            }
            const bd = document.getElementById('contabEditBackdrop');
            document.getElementById('contabEditId').value = String(row.id);
            document.getElementById('contabEditCreatedAt').value = contabIsoToDatetimeLocal(row.createdAt);
            document.getElementById('contabEditBucket').value = row.bucket === 'B' ? 'B' : 'A';
            document.getElementById('contabEditSigned').value = Number(row.signedAmount || 0);
            document.getElementById('contabEditCategory').value = row.category || '';
            document.getElementById('contabEditConcept').value = row.concept || '';
            if (bd) bd.style.display = 'flex';
        }

        function contabilidadCerrarEditarModal() {
            const bd = document.getElementById('contabEditBackdrop');
            if (bd) bd.style.display = 'none';
        }

        async function contabilidadGuardarEditar() {
            if (typeof ClubAccounting === 'undefined') return;
            const id = document.getElementById('contabEditId').value;
            const createdAt = contabDatetimeLocalToIso(document.getElementById('contabEditCreatedAt').value);
            const bucket = document.getElementById('contabEditBucket').value;
            const signedAmount = parseFloat(document.getElementById('contabEditSigned').value);
            const category = document.getElementById('contabEditCategory').value.trim() || 'otro';
            const concept = document.getElementById('contabEditConcept').value.trim();
            if (!concept || !Number.isFinite(signedAmount) || signedAmount === 0) {
                alert('Indica concepto e importe distinto de cero.');
                return;
            }
            const next = ClubAccounting.updateEntryById(id, {
                createdAt,
                bucket,
                signedAmount,
                category,
                concept
            });
            if (!next) {
                alert('No se pudo guardar (importe inválido o asiento no encontrado).');
                return;
            }
            try {
                await persistRecordToFirebase('clubAccountingLedger', 'ledger', next);
            } catch (e) {
                console.warn(e);
            }
            contabilidadCerrarEditarModal();
            loadContabilidadPanel();
            alert('✅ Asiento actualizado.');
        }

        async function contabilidadEliminarAsiento(id) {
            if (typeof ClubAccounting === 'undefined' || !id) return;
            if (!confirm('¿Eliminar este asiento del libro? No se puede deshacer.')) return;
            ClubAccounting.deleteEntryById(id);
            await deleteRecordFromFirebase('ledger', id);
            loadContabilidadPanel();
            alert('✅ Asiento eliminado.');
        }

        async function contabilidadToggleCaja(id) {
            if (typeof ClubAccounting === 'undefined' || !id) return;
            const next = ClubAccounting.toggleEntryBucket(id);
            if (!next) {
                alert('No se pudo cambiar de caja.');
                return;
            }
            try {
                await persistRecordToFirebase('clubAccountingLedger', 'ledger', next);
            } catch (e) {
                console.warn(e);
            }
            loadContabilidadPanel();
        }

        async function guardarContabilidadCuotas() {
            if (typeof ClubAccounting === 'undefined') return;
            const admin = JSON.parse(localStorage.getItem('currentAdmin') || '{}');
            ClubAccounting.saveMembershipPricing({
                cuotaMenor: document.getElementById('contabCuotaMenor').value,
                cuotaMayor: document.getElementById('contabCuotaMayor').value,
                edadMaxMenor: document.getElementById('contabEdadMenor').value,
                updatedBy: admin.email || admin.name || 'admin'
            });
            if (typeof window.syncLocalSettingsBlobToFirebase === 'function') {
                try {
                    await window.syncLocalSettingsBlobToFirebase('clubMembershipPricing');
                } catch (e) {
                    console.warn(e);
                }
            }
            alert('✅ Cuotas guardadas. Permanecen hasta que las vuelvas a cambiar.');
            loadContabilidadPanel();
        }

        async function contabilidadMovimientoManual() {
            if (typeof ClubAccounting === 'undefined') return;
            const tipo = document.getElementById('contabMovTipo').value;
            const bucket = document.getElementById('contabMovBucket').value;
            const monto = parseFloat(document.getElementById('contabMovMonto').value);
            const concepto = document.getElementById('contabMovConcepto').value.trim();
            if (!concepto || !Number.isFinite(monto) || monto <= 0) {
                alert('❌ Indica concepto e importe válido.');
                return;
            }
            const signed = tipo === 'gasto' ? -monto : monto;
            const row = ClubAccounting.recordManual(bucket, signed, concepto, 'manual');
            if (row) {
                try {
                    await persistRecordToFirebase('clubAccountingLedger', 'ledger', row);
                } catch (e) {
                    console.warn(e);
                }
            }
            document.getElementById('contabMovMonto').value = '';
            document.getElementById('contabMovConcepto').value = '';
            loadContabilidadPanel();
        }

        async function contabilidadTraspaso() {
            if (typeof ClubAccounting === 'undefined') return;
            const from = document.getElementById('contabXferFrom').value;
            const to = document.getElementById('contabXferTo').value;
            const monto = parseFloat(document.getElementById('contabXferMonto').value);
            const nota = document.getElementById('contabXferNota').value.trim();
            if (from === to || !Number.isFinite(monto) || monto <= 0) {
                alert('❌ Origen y destino distintos e importe mayor que cero.');
                return;
            }
            const before = ClubAccounting.readLedger().length;
            ClubAccounting.recordTransfer(from, to, monto, nota);
            const list = ClubAccounting.readLedger();
            const added = list.slice(before);
            for (let i = 0; i < added.length; i++) {
                try {
                    await persistRecordToFirebase('clubAccountingLedger', 'ledger', added[i]);
                } catch (e) {
                    console.warn(e);
                }
            }
            document.getElementById('contabXferMonto').value = '';
            document.getElementById('contabXferNota').value = '';
            loadContabilidadPanel();
        }

        function loadMembersList() {
            try {
                const membersRaw = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const members = dedupeMembersList(membersRaw);
                members.forEach((m) => {
                    if (typeof window.applyClubRoleFlagsToMember === 'function') {
                        window.applyClubRoleFlagsToMember(m);
                    }
                });
                const membersList = document.getElementById('membersList');
                const statusFilter = document.getElementById('memberStatusFilter').value;

                if (!membersList) return;

                // Filtrar socios según el estado
                let filteredMembers = members;
                if (statusFilter !== 'all') {
                    filteredMembers = members.filter(member => {
                        if (statusFilter === 'pending') return member.status === 'pending_validation';
                        if (statusFilter === 'pending_renewal') return isMemberPendingRenewal(member);
                        if (statusFilter === 'pending_new') return isMemberPendingNewAlta(member);
                        if (statusFilter === 'active') return member.status === 'active';
                        if (statusFilter === 'expired') return isMemberExpired(member);
                        return true;
                    });
                }

                if (filteredMembers.length === 0) {
                    membersList.innerHTML = '<div style="text-align: center; padding: 20px; color: #666;">No hay socios que mostrar con los filtros actuales.</div>';
                    return;
                }

                let html = '';
                filteredMembers.forEach((member, visualIndex) => {
                    const isExpired = isMemberExpired(member);
                    const statusText = getMemberStatusText(member, isExpired);
                    const statusColor = getMemberStatusColor(member, isExpired);

                    html += `
                        <div style="background: white; padding: 15px; border-radius: 8px; margin-bottom: 10px; border-left: 4px solid ${statusColor};">
                            <div style="display: flex; justify-content: space-between; align-items: flex-start;">
                                <div>
                                    <h4 style="margin: 0 0 5px 0; color: #1e3a8a;">#${visualIndex + 1} · ${([member.name, member.surname].filter(function (x) { return x && String(x).trim(); }).join(' ') || '—')}</h4>
                                    <div style="font-size: 0.9em; color: #666; margin-bottom: 8px;">
                                        📞 ${member.phone || '—'} | 📧 ${member.email || 'No especificado'} | 📍 ${member.address || 'No especificada'}
                                    </div>
                                    <div style="font-size: 0.9em; color: #666;">
                                        🆔 DNI: ${member.dni || 'No especificado'} | 📅 Registro: ${member.registrationDate ? (() => { const d = new Date(member.registrationDate); return isNaN(d.getTime()) ? '—' : d.toLocaleDateString('es-ES'); })() : '—'}
                                        ${(function(){
                                            const CMN = window.ClubMemberNumbers;
                                            if (CMN && CMN.isSocioDeHonor(member)) {
                                                const h = CMN.getHonorNumber(member);
                                                return '| 🏅 SOCIO DE HONOR' + (h ? ' · N.º SOC. ' + CMN.padSocNum(h) : '');
                                            }
                                            if (!member.memberNumber || String(member.memberNumber).startsWith('SOC')) return '';
                                            const label = CMN ? CMN.padSocNum(parseInt(member.memberNumber)) : String(member.memberNumber).padStart(6,'0');
                                            return '| N.º SOC. ' + label;
                                        })()}
                                        ${member.pendingReason === 'renovacion' ? ' | <span style="color:#0284c7;font-weight:600;">Renovación cuota</span>' : ''}
                                        ${member.cuota != null ? ` | 💶 Cuota: ${member.cuota} €` : ''}
                                    </div>
                                    <div style="font-size: 0.9em; color: #059669; font-weight: bold; margin-top: 5px;">
                                        🔐 Contraseña gestionada de forma segura (no visible en panel)
                                    </div>
                                    ${typeof formatClubRoleBadgesHtml === 'function' ? formatClubRoleBadgesHtml(member) : ''}
                                </div>
                                <span style="background: ${statusColor}; color: white; padding: 4px 8px; border-radius: 12px; font-size: 0.8rem;">
                                    ${statusText}
                                </span>
                            </div>
                            <div style="display: flex; gap: 10px; margin-top: 15px;">
                                <button onclick="viewMemberDetails('${member.id}')" style="padding: 6px 12px; background: #6c757d; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">👁️ Ver Detalles</button>
                                ${member.status === 'active' ? `<button onclick="previewMemberCard('${member.id}')" title="Vista previa del carnet (solo admin)" style="padding: 6px 12px; background: #1e3a8a; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">🎫 Carnet</button>` : ''}
                                ${member.status === 'pending_validation' ? `<button onclick="validateMember('${member.id}')" title="Solo tras ver el ingreso en la cuenta bancaria" style="padding: 6px 12px; background: #059669; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">✅ Validar pago</button>` : ''}
                                ${member.status === 'active' ? `<button type="button" onclick="contabilidadRegistrarCuotaSocioActivo('${String(member.id).replace(/'/g, "\\'")}')" title="Si validaste antes de tener contabilidad o falta el asiento en el libro" style="padding: 6px 12px; background: #1d4ed8; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">💶 Cuota → contabilidad</button>` : ''}
                                <button onclick="editMember('${member.id}')" style="padding: 6px 12px; background: #f59e0b; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">✏️ Editar</button>
                                <button onclick="deleteMember('${member.id}')" style="padding: 6px 12px; background: #dc2626; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.8rem;">🗑️ Eliminar</button>
                            </div>
                        </div>
                    `;
                });

                membersList.innerHTML = html;
                console.log('👨‍👩‍👧‍👦 Lista de socios cargada:', filteredMembers.length, 'socios');

            } catch (error) {
                console.error('❌ Error cargando lista de socios:', error);
            }
        }

        function isMemberExpired(member) {
            const m = normalizeClubMember(member);
            if (m.status === 'active') return false;
            if (m.status === 'expired') return true;
            if (m.status !== 'pending_validation') return false;
            return isPastMemberPaymentDeadline(m);
        }

        function getMemberStatusText(member, isExpired) {
            const m = normalizeClubMember(member);
            if (m.status === 'active') return 'Activo';
            if (isExpired || m.status === 'expired') return 'Caducado';
            if (m.status === 'pending_validation' && m.pendingReason === 'renovacion') return 'Pendiente (renovación)';
            return 'Pendiente';
        }

        function getMemberStatusColor(member, isExpired) {
            const m = normalizeClubMember(member);
            if (m.status === 'active') return '#059669';
            if (isExpired || m.status === 'expired') return '#dc2626';
            return '#f59e0b';
        }

        function filterMembers() {
            loadMembersList();
        }

        function previewMemberCard(memberId) {
            if (!window.memberCardGenerator) {
                alert('❌ Módulo de carnet no cargado. Recarga el panel.');
                return;
            }
            const _adminSess = JSON.parse(localStorage.getItem('currentAdmin') || 'null');
            if (!_adminSess || !_adminSess.email) {
                alert('❌ Solo administradores pueden ver carnets de socios.');
                return;
            }
            const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
            const raw = members.find(m => m.id === memberId);
            if (!raw) {
                alert('❌ Socio no encontrado');
                return;
            }
            const member = normalizeClubMember(raw);
            Object.assign(member, {
                dni: raw.dni || member.dni,
                socioDeHonor: raw.socioDeHonor,
                numeroSocioHonor: raw.numeroSocioHonor,
                numeroSocioRegular: raw.numeroSocioRegular,
                numeroSocio: raw.numeroSocio != null ? raw.numeroSocio : raw.memberNumber,
                memberNumber: raw.memberNumber != null ? raw.memberNumber : raw.numeroSocio
            });
            const r = window.memberCardGenerator.openForAdminMember(member);
            if (!r.ok) alert('🎫 ' + (r.message || 'No se puede mostrar el carnet.'));
        }

        function viewMemberDetails(memberId) {
            const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
            const raw = members.find(m => m.id === memberId);
            const member = raw ? normalizeClubMember(raw) : null;
            
            if (member) {
                const isExpired = isMemberExpired(member);
                let details = `👤 DETALLES COMPLETOS DEL SOCIO\n\n`;
                details += `📋 INFORMACIÓN PERSONAL:\n`;
                details += `• Nombre: ${member.name} ${member.surname}\n`;
                details += `• DNI: ${member.dni || 'No especificado'}\n`;
                details += `• Teléfono: ${member.phone}\n`;
                details += `• Dirección: ${member.address || 'No especificada'}\n`;
                details += `• Email: ${member.email || 'No especificado'}\n`;
                details += `• Fecha de Nacimiento: ${member.birthDate ? new Date(member.birthDate).toLocaleDateString() : 'No especificada'}\n\n`;
                
                details += `📊 INFORMACIÓN DEL CLUB:\n`;
                details += `• Estado: ${getMemberStatusText(member, isExpired)}\n`;
                details += `• Fecha de Registro: ${member.registrationDate ? (() => { const d = new Date(member.registrationDate); return isNaN(d.getTime()) ? '—' : d.toLocaleDateString('es-ES'); })() : '—'}\n`;
                
                if (member.memberNumber) {
                    const _numLabel = window.ClubMemberNumbers && !String(member.memberNumber).startsWith('SOC')
                        ? (window.ClubMemberNumbers.isSocioDeHonor(member)
                            ? window.ClubMemberNumbers.formatMemberLabel(member)
                            : 'N.º SOC. ' + window.ClubMemberNumbers.padSocNum(parseInt(member.memberNumber)))
                        : member.memberNumber;
                    details += `• Número de Socio: ${_numLabel}\n`;
                }
                
                if (member.validatedBy) {
                    details += `• Validado por: ${member.validatedBy}\n`;
                    details += `• Fecha de Validación: ${new Date(member.validatedDate).toLocaleDateString()}\n`;
                }
                
                if (member.lastModified) {
                    details += `• Última modificación: ${new Date(member.lastModified).toLocaleDateString()}\n`;
                    details += `• Modificado por: ${member.modifiedBy || 'No especificado'}\n`;
                }
                
                details += `\n🔐 ACCESO:\n`;
                details += `• Contraseña: gestionada de forma segura (no visible)\n`;
                
                const dl = getMemberPaymentDeadline(member);
                if (member.pendingReason === 'renovacion') {
                    details += `• Tipo: Renovación de cuota${member.renovacionTemporada ? ' (' + member.renovacionTemporada + ')' : ''} — sin plazo automático de caducidad\n`;
                } else if (dl && !isNaN(dl.getTime())) {
                    details += `• Plazo para ingresar (alta nueva): ${dl.toLocaleString('es-ES')}\n`;
                }
                if (member.cuota != null) details += `• Cuota aplicada: ${member.cuota} €\n`;
                if (isExpired) {
                    details += `\n⚠️ ADVERTENCIA: Ha superado el plazo para validar el pago.`;
                }
                
                alert(details);
            }
        }
        
        async function assignPendingMemberNumbersFromPanel() {
            try {
                if (!window.AdminClubCloudPersist || !window.AdminClubCloudPersist.assignPendingMemberNumbers) {
                    alert('❌ Función no disponible. Despliega las funciones Netlify actualizadas.');
                    return;
                }
                const CMN = window.ClubMemberNumbers;
                const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const localPending = members.filter(function (m) {
                    if (String(m.status || '').toLowerCase() !== 'active' && m.estado !== 'activo') return false;
                    if (CMN && CMN.isSocioDeHonor(m)) return false;
                    if (CMN) return CMN.getRegularNumber(m) == null;
                    const n = String(m.memberNumber || m.numeroSocio || '');
                    return !n || n.startsWith('SOC');
                }).length;
                const msg =
                    localPending > 0
                        ? 'Hay ' +
                          localPending +
                          ' socio(s) activo(s) en este dispositivo sin número definitivo (≥ 51).\n\n¿Asignar números en Firebase y sincronizar?'
                        : '¿Buscar en Firebase socios activos sin número definitivo y asignarles el siguiente disponible (≥ 51)?';
                if (!confirm(msg)) return;
                const result = await window.AdminClubCloudPersist.assignPendingMemberNumbers();
                const rows = result.members || [];
                if (rows.length) {
                    const all = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                    rows.forEach(function (row) {
                        const ix = all.findIndex(function (m) {
                            return m.id === row.id;
                        });
                        if (ix >= 0) {
                            all[ix].memberNumber = row.memberNumber;
                            all[ix].numeroSocio = row.numeroSocio;
                            all[ix].numeroSocioRegular = row.numeroSocioRegular;
                            all[ix].membershipTier = 'regular';
                        }
                    });
                    syncMembersLocalStorage(all);
                }
                loadMembersList();
                updateMemberCounts();
                alert(
                    '✅ Números asignados: ' +
                        (result.assigned || 0) +
                        '.\n\nGuardado en Firebase (sanabria_members) y actualizado en este panel.'
                );
            } catch (e) {
                console.error(e);
                alert('❌ ' + (e.message || e));
            }
        }

        async function repairPlayerInscriptionsFromPanel() {
            try {
                if (!window.AdminClubCloudPersist || !window.AdminClubCloudPersist.repairPlayerInscriptions) {
                    alert('❌ Función no disponible. Despliega las funciones Netlify actualizadas.');
                    return;
                }
                const raw = prompt(
                    'Pedido(s) pasarela Redsys (números del correo «Pedido pasarela»), separados por coma:\n\nEjemplo: 173131153731,106631462066'
                );
                if (!raw || !String(raw).trim()) return;
                const orderIds = String(raw)
                    .split(/[,;\s]+/)
                    .map(function (s) {
                        return s.trim();
                    })
                    .filter(Boolean);
                if (!orderIds.length) {
                    alert('❌ Indica al menos un pedido.');
                    return;
                }
                if (
                    !confirm(
                        'Se recrearán/actualizarán en Firebase las fichas de jugador/a y socio para ' +
                            orderIds.length +
                            ' pedido(s) pagado(s).\n\n¿Continuar?'
                    )
                ) {
                    return;
                }
                const result = await window.AdminClubCloudPersist.repairPlayerInscriptions(orderIds);
                const lines = (result.results || []).map(function (r) {
                    return (
                        (r.nombre || '') +
                        ' ' +
                        (r.apellidos || '') +
                        ' (DNI ' +
                        (r.dni || '—') +
                        ')\n  Jugador: ' +
                        (r.playerId || '—') +
                        '\n  Socio: ' +
                        (r.memberId || '—') +
                        (r.numeroSocio ? ' · Nº ' + r.numeroSocio : '')
                    );
                });
                alert(
                    '✅ Reparación completada: ' +
                        (result.repaired || 0) +
                        ' pedido(s).\n\n' +
                        (lines.length ? lines.join('\n\n') : '') +
                        '\n\nRecarga listas (Jugadores / Socios) o sincroniza desde la nube.'
                );
            } catch (e) {
                console.error(e);
                alert('❌ ' + (e.message || e));
            }
        }

        async function validateMember(memberId) {
            try {
                const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const memberIndex = members.findIndex(m => m.id === memberId);
                
                if (memberIndex !== -1) {
                    if (!confirm('¿Has comprobado el ingreso de la cuota en la cuenta bancaria del club?\n\n(Solo pulsa Aceptar si ya has visto el abono.)')) {
                        return;
                    }
                    const currentAdmin = JSON.parse(localStorage.getItem('currentAdmin') || '{}');
                    const nm = normalizeClubMember(members[memberIndex]);
                    
                    if (isPastMemberPaymentDeadline(members[memberIndex])) {
                        alert('❌ No se puede validar: ha superado el plazo de 7 días para ingresar (alta nueva).\n\nEl registro puede eliminarse al limpiar pendientes caducados.');
                        await deleteExpiredMembers();
                        return;
                    }

                    // Número de socios activos con número real ≥ 51 (ignora provisionales "SOCxxxxx")
                    const CMN = window.ClubMemberNumbers;
                    const nextNumber = CMN ? CMN.nextRegularMemberNumber(members) : (Math.max(...members.filter(m => normalizeClubMember(m).status === 'active').map(m => parseInt(m.memberNumber) || 0), 50) + 1);
                    const hadNum = !!(members[memberIndex].memberNumber != null && members[memberIndex].memberNumber !== '' && !String(members[memberIndex].memberNumber).startsWith('SOC'))
                        || !!(members[memberIndex].numeroSocio != null && String(members[memberIndex].numeroSocio).trim() !== '' && !String(members[memberIndex].numeroSocio).startsWith('SOC'));

                    members[memberIndex].status = 'active';
                    members[memberIndex].estado = 'activo';
                    members[memberIndex].pagado = true;
                    if (!hadNum) {
                        members[memberIndex].memberNumber = nextNumber;
                        members[memberIndex].numeroSocio = nextNumber;
                        members[memberIndex].numeroSocioRegular = nextNumber;
                        members[memberIndex].membershipTier = 'regular';
                    }
                    members[memberIndex].pendingReason = null;
                    members[memberIndex].fechaLimitePago = null;
                    members[memberIndex].renovacionDesde = null;
                    members[memberIndex].renovacionTemporada = null;
                    members[memberIndex].cuotaReferenciaEdad31Agosto = null;
                    members[memberIndex].diasLimiteRenovacion = null;
                    members[memberIndex].cuotaVigenteHasta = proximoCierreTemporada().toISOString();
                    members[memberIndex].validatedBy = currentAdmin.name || currentAdmin.email || 'Administrador';
                    members[memberIndex].validatedDate = new Date().toISOString();
                    members[memberIndex].lastModified = new Date().toISOString();
                    
                    syncMembersLocalStorage(members);

                    let cuotaImporte = Number(nm.cuota);
                    if (!Number.isFinite(cuotaImporte) || cuotaImporte <= 0) {
                        const refRaw = nm.cuotaReferenciaEdadCierre || nm.cuotaReferenciaEdad31Agosto;
                        const yRef = refRaw != null ? parseInt(String(refRaw).slice(0, 4), 10) : NaN;
                        const yDefault = (typeof ClubAccounting !== 'undefined' && ClubAccounting.getCuotaEdadReferenciaAnio)
                            ? ClubAccounting.getCuotaEdadReferenciaAnio()
                            : new Date().getFullYear();
                        const y = !isNaN(yRef) ? yRef : yDefault;
                        cuotaImporte = cuotaSegunEdadAl31Agosto(members[memberIndex], y);
                    }
                    if (typeof ClubAccounting !== 'undefined' && Number.isFinite(cuotaImporte) && cuotaImporte > 0) {
                        const row = ClubAccounting.recordMemberCuotaToBankA(members[memberIndex], cuotaImporte);
                        if (row) {
                            try {
                                await persistRecordToFirebase('clubAccountingLedger', 'ledger', row);
                            } catch (accErr) {
                                console.warn('Asiento contable en local; error Firebase:', accErr);
                            }
                        }
                    }

                    let firebaseSyncOk = false;
                    try {
                        await persistMemberToFirebase(members[memberIndex]);
                        firebaseSyncOk = true;
                    } catch (syncErr) {
                        console.warn('Validación guardada en local; error al sincronizar con Firebase:', syncErr);
                        alert('⚠️ Validación guardada solo en este dispositivo.\n\nNo se pudo guardar en la nube. Comprueba conexión, sesión de administrador y vuelve a intentarlo.');
                    }
                    
                    loadMembersList();
                    updateMemberCounts();
                    updateDashboardCounts();
                    
                    const displayName = `${nm.name || ''} ${nm.surname || ''}`.trim() || 'Socio';
                    const _mValido = members[memberIndex];
                    const _rawNum = _mValido.memberNumber || _mValido.numeroSocio;
                    const _CMN = window.ClubMemberNumbers;
                    const numFinal = (_CMN && _rawNum && !String(_rawNum).startsWith('SOC'))
                        ? (_CMN.isSocioDeHonor(_mValido) ? _CMN.formatMemberLabel(_mValido) : 'N.º SOC. ' + _CMN.padSocNum(parseInt(_rawNum)))
                        : _rawNum;
                    if (firebaseSyncOk) {
                        alert(`✅ Socio "${displayName}" validado y sincronizado correctamente.\n\n🔢 ${numFinal}${hadNum ? ' (sin cambios)' : ' (asignado)'}\n\n📧 Se enviará un correo al socio con la confirmación del alta.`);
                        console.log('✅ Socio validado y sincronizado:', displayName);
                    } else {
                        console.log('⚠️ Socio validado solo en local (sin Firebase):', displayName);
                    }

                    // Correo al socio: alta activa (transferencia/efectivo validado por admin)
                    const memberValidado = members[memberIndex];
                    if (memberValidado.email) {
                        (async function () {
                            try {
                                const headers = { 'Content-Type': 'application/json' };
                                if (window.CdsanAdminApiAuth && window.CdsanAdminApiAuth.getAdminAuthHeaders) {
                                    Object.assign(headers, await window.CdsanAdminApiAuth.getAdminAuthHeaders());
                                }
                                const r = await fetch('/.netlify/functions/send-club-email', {
                                    method: 'POST',
                                    headers: headers,
                                    body: JSON.stringify({
                                        type: 'member_validated_manual',
                                        email: memberValidado.email,
                                        memberId: memberValidado.id,
                                        nombre: memberValidado.nombre || memberValidado.name,
                                        apellidos: memberValidado.apellidos || memberValidado.surname,
                                        numeroSocio: memberValidado.numeroSocio || memberValidado.memberNumber
                                    })
                                });
                                const data = await r.json().catch(function () { return {}; });
                                if (!r.ok || !data.ok) console.warn('Email validación socio:', data.error || r.status);
                            } catch (e) {
                                console.warn('Email validación socio:', e);
                            }
                        })();
                    }
                }
            } catch (error) {
                console.error('❌ Error validando socio:', error);
                alert('❌ Error al validar el socio');
            }
        }

        /**
         * Socios ya activos sin asiento en el libro (p. ej. validados antes de activar contabilidad).
         * Crea un ingreso en caja A enlazado al socio; no duplica si ya existe cuota_socio para ese id.
         */
        async function contabilidadRegistrarCuotaSocioActivo(memberId) {
            if (typeof ClubAccounting === 'undefined' || !memberId) return;
            try {
                const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const ix = members.findIndex((m) => String(m.id) === String(memberId));
                if (ix < 0) {
                    alert('❌ Socio no encontrado.');
                    return;
                }
                const m = normalizeClubMember(members[ix]);
                if (m.status !== 'active') {
                    alert('ℹ️ Solo aplica a socios en estado activo. Si está pendiente, usa «Validar pago».');
                    return;
                }
                if (!confirm('¿Registrar en contabilidad (caja A — banco) la cuota de este socio?\n\nComprueba antes en Contabilidad que no esté ya ingresada (si ya existe asiento enlazado, no se duplicará).')) {
                    return;
                }
                let cuotaImporte = Number(m.cuota);
                if (!Number.isFinite(cuotaImporte) || cuotaImporte <= 0) {
                    const refRawM = m.cuotaReferenciaEdadCierre || m.cuotaReferenciaEdad31Agosto;
                    const yRef = refRawM != null ? parseInt(String(refRawM).slice(0, 4), 10) : NaN;
                    const yDefault = ClubAccounting.getCuotaEdadReferenciaAnio ? ClubAccounting.getCuotaEdadReferenciaAnio() : new Date().getFullYear();
                    const y = !isNaN(yRef) ? yRef : yDefault;
                    cuotaImporte = cuotaSegunEdadAl31Agosto(members[ix], y);
                }
                if (!Number.isFinite(cuotaImporte) || cuotaImporte <= 0) {
                    alert('❌ No se pudo determinar la cuota. Indica importe en el socio (Editar) o revisa fecha de nacimiento.');
                    return;
                }
                const accRes = ClubAccounting.recordMemberCuotaToBankAIfMissing(members[ix], cuotaImporte);
                if (accRes.skipped) {
                    alert('ℹ️ Ya hay un asiento de cuota de socio en el libro para esta persona. Revisa Contabilidad → libro.');
                    return;
                }
                if (accRes.row) {
                    try {
                        await persistRecordToFirebase('clubAccountingLedger', 'ledger', accRes.row);
                    } catch (e) {
                        console.warn(e);
                        alert('⚠️ Asiento guardado en este dispositivo; no se pudo sincronizar con la nube. Reintenta con conexión y sesión de admin.');
                    }
                }
                try {
                    loadContabilidadPanel();
                } catch (e2) {
                    console.warn(e2);
                }
                alert(`✅ Cuota de ${cuotaImporte.toFixed(2)} € registrada en contabilidad (caja A).`);
            } catch (err) {
                console.error(err);
                alert('❌ Error al registrar la cuota en contabilidad.');
            }
        }

        /** Solo pendientes de alta con plazo de pago superado (misma regla que antes). No borra en silencio solo por estado «expired». */
        function isMemberAutoExpiredOnLoad(member) {
            const m = normalizeClubMember(member);
            return m.status === 'pending_validation' && isPastMemberPaymentDeadline(member);
        }

        // Al abrir el panel: quita del servidor las altas nuevas fuera de plazo (evita que vuelvan con onSnapshot)
        async function deleteExpiredMembers() {
            try {
                const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const toRemove = members.filter(m => isMemberAutoExpiredOnLoad(m));
                if (toRemove.length === 0) return;
                const failed = [];
                for (const r of toRemove) {
                    try {
                        await removeMemberFromCloudIfNeeded(r.id, { email: r.email, dni: r.dni });
                    } catch (e) {
                        console.warn('Auto-limpieza caducados: Firebase', r.id, e);
                        failed.push(r);
                    }
                }
                const updatedMembers = members.filter(mem => {
                    if (!isMemberAutoExpiredOnLoad(mem)) return true;
                    return failed.some(f => String(f.id) === String(mem.id));
                });
                const deletedCount = members.length - updatedMembers.length;
                if (deletedCount > 0) {
                    syncMembersLocalStorage(updatedMembers);
                    try {
                        loadMembersList();
                        updateMemberCounts();
                        updateDashboardCounts();
                    } catch (_) {}
                    console.log(`🗑️ Auto-limpieza: ${deletedCount} alta(s) fuera de plazo eliminada(s) en servidor.`);
                    if (failed.length > 0) {
                        console.warn('Auto-limpieza: no eliminados en Firebase (se mantienen en lista):', failed.length);
                    }
                }
            } catch (error) {
                console.error('❌ Error eliminando socios expirados:', error);
            }
        }

        function checkExpiredMembers() {
            deleteExpiredMembers().catch((e) => console.error(e));
        }

        function toggleHonorFields(checked) {
            const f = document.getElementById('honorFields');
            const i = document.getElementById('noHonorInfo');
            if (f) f.style.display = checked ? 'block' : 'none';
            if (i) i.style.display = checked ? 'none' : 'block';
        }

