        function closeEditMemberModal() {
            const modal = document.getElementById('editMemberModal');
            if (modal) {
                modal.remove();
            }
        }
        
        async function saveMemberEdit(event, memberId) {
            event.preventDefault();
            
            try {
                const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const memberIndex = members.findIndex(m => m.id === memberId);
                
                if (memberIndex === -1) {
                    alert('❌ Socio no encontrado');
                    return;
                }
                
                const member = members[memberIndex];
                const currentAdmin = JSON.parse(localStorage.getItem('currentAdmin') || '{}');
                
                // Obtener valores del formulario
                const name = document.getElementById('editMemberName').value.trim();
                const surname = document.getElementById('editMemberSurname').value.trim();
                const dni = document.getElementById('editMemberDNI').value.trim();
                const phone = document.getElementById('editMemberPhone').value.trim();
                const address = document.getElementById('editMemberAddress').value.trim();
                const email = document.getElementById('editMemberEmail').value.trim();
                const birthDate = document.getElementById('editMemberBirthDate').value;
                const sexo = document.getElementById('editMemberSexo').value;
                const status = document.getElementById('editMemberStatus').value;
                const newPassword = document.getElementById('editMemberPassword').value.trim();
                
                // Validaciones
                if (!name || !surname || !sexo || !dni || !phone || !address || !email) {
                    alert('❌ Por favor, completa todos los campos obligatorios');
                    return;
                }
                
                const existingMember = members.find(function (m) {
                    if (m.id === memberId) return false;
                    return membersShareIdentity(m, {
                        dni: dni,
                        email: email,
                        name: name,
                        surname: surname,
                        nombre: name,
                        apellidos: surname
                    });
                });

                if (existingMember) {
                    alert('❌ Ya existe otro socio con el mismo DNI o con ese email y los mismos nombre y apellidos.');
                    return;
                }
                
                // Actualizar datos del socio
                member.name = name;
                member.surname = surname;
                member.nombre = name;
                member.apellidos = surname;
                member.sexo = sexo;
                member.dni = dni;
                member.phone = phone;
                member.telefono = phone;
                member.address = address;
                member.direccion = address;
                member.email = email;
                member.birthDate = birthDate;
                member.fechaNacimiento = birthDate;
                member.status = status;
                member.lastModified = new Date().toISOString();
                member.modifiedBy = currentAdmin.name || currentAdmin.email || 'Administrador';
                
                if (newPassword) {
                    alert(
                        'ℹ️ La contraseña no se guarda desde el panel.\n\n' +
                        'El socio puede cambiarla en su perfil (web) o solicitar «Restablecer contraseña» desde la web.'
                    );
                    document.getElementById('editMemberPassword').value = '';
                }

                delete member.password;
                delete member.pass;
                delete member.plainPassword;

                // Socio de Honor: asignar / quitar
                const CMN_honor = window.ClubMemberNumbers;
                const quiereHonor = !!(document.getElementById('editSocioDeHonor') && document.getElementById('editSocioDeHonor').checked);
                if (CMN_honor) {
                    if (quiereHonor) {
                        const honorNumInput = document.getElementById('editNumeroHonor');
                        const honorNum = honorNumInput ? parseInt(honorNumInput.value, 10) : NaN;
                        if (!Number.isFinite(honorNum) || honorNum < 1 || honorNum > 50) {
                            alert('❌ Introduce un número de honor válido entre 1 y 50.');
                            return;
                        }
                        const res = CMN_honor.applyHonorToMember(member, honorNum, members, memberId);
                        if (!res.ok) { alert('❌ ' + res.error); return; }
                    } else if (CMN_honor.isSocioDeHonor(member)) {
                        CMN_honor.removeHonorFromMember(member, members);
                    }
                }
                
                // Si el estado cambió a activo y no tenía número de socio regular, asignar uno
                const CMN_edit = window.ClubMemberNumbers;
                const numActual = member.memberNumber != null ? String(member.memberNumber) : '';
                const numEsProvisional = !numActual || numActual.startsWith('SOC') ||
                    (CMN_edit && !CMN_edit.isSocioDeHonor(member) && (parseInt(numActual) || 0) < CMN_edit.REGULAR_MIN);
                if (status === 'active' && numEsProvisional && !( CMN_edit && CMN_edit.isSocioDeHonor(member))) {
                    const next = CMN_edit ? CMN_edit.nextRegularMemberNumber(members) : (Math.max(...members.filter(m => m.status==='active').map(m=>parseInt(m.memberNumber)||0), 50) + 1);
                    member.memberNumber = next;
                    member.numeroSocio = next;
                    member.numeroSocioRegular = next;
                    member.membershipTier = 'regular';
                    member.validatedBy = currentAdmin.name || currentAdmin.email || 'Administrador';
                    member.validatedDate = new Date().toISOString();
                }
                
                // Guardar cambios
                syncMembersLocalStorage(members);
                await persistMemberToFirebase(members[memberIndex]);
                
                // Cerrar modal
                closeEditMemberModal();
                
                // Recargar lista y contadores
                loadMembersList();
                updateMemberCounts();
                updateDashboardCounts();
                
                alert('✅ Socio actualizado correctamente');
                console.log('✏️ Socio editado:', member.name + ' ' + member.surname);
                
            } catch (error) {
                console.error('❌ Error editando socio:', error);
                alert('❌ Error al editar el socio');
            }
        }

        async function deleteMember(memberId) {
            if (!confirm('¿Estás seguro de que quieres eliminar este socio?\n\n⚠️ Esta acción no se puede deshacer.')) return;
            try {
                const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const memberToDelete = members.find(m => String(m.id) === String(memberId));
                if (!memberToDelete) return;
                try {
                    await removeMemberFromCloudIfNeeded(memberToDelete.id, {
                        email: memberToDelete.email,
                        dni: memberToDelete.dni
                    });
                } catch (syncErr) {
                    console.error('❌ Error eliminando socio en Firebase:', syncErr);
                    alert('❌ No se pudo eliminar en el servidor (nube).\n\nLa lista se sincroniza en tiempo real: si no se borra en la nube, el socio volverá a aparecer.\n\nComprueba conexión, permisos de administrador y acceso a la nube.\n\n' + (syncErr.message || String(syncErr)));
                    return;
                }
                const updatedMembers = members.filter(m => String(m.id) !== String(memberId));
                syncMembersLocalStorage(updatedMembers);
                loadMembersList();
                updateMemberCounts();
                updateDashboardCounts();
                if (typeof updateDatabaseStats === 'function') updateDatabaseStats();
                const label = ([memberToDelete.name, memberToDelete.surname].filter(Boolean).join(' ') || 'Socio').trim();
                alert('✅ Socio "' + label + '" eliminado correctamente (también en el servidor).');
                console.log('🗑️ Socio eliminado:', label);
            } catch (error) {
                console.error('❌ Error eliminando socio:', error);
                alert('❌ Error al eliminar el socio');
            }
        }

        /** Política del club: nunca validación masiva; solo al ver el pago en cuenta. */
        function validateAllPendingMembers() {
            alert('No está disponible la validación masiva.\n\nValida cada socio con «Validar pago» cuando hayas comprobado el ingreso en la cuenta bancaria.\n\nContacto: cdsanabriafc@gmail.com');
        }

        /**
         * Renovación manual (respaldo): marca activos como pendientes.
         * Lo habitual es la renovación automática tras el 31/05 (Firebase + función programada).
         */
        async function iniciarNuevaTemporadaCuotas() {
            const anioDef = (typeof ClubAccounting !== 'undefined' && ClubAccounting.getCuotaEdadReferenciaAnio)
                ? ClubAccounting.getCuotaEdadReferenciaAnio()
                : new Date().getFullYear();
            const cierreLabel = (typeof ClubMembershipSeason !== 'undefined' && ClubMembershipSeason.formatCierreFechaCorta)
                ? ClubMembershipSeason.formatCierreFechaCorta(anioDef)
                : '31/05/' + anioDef;
            const anioStr = prompt(
                'Año de REFERENCIA (edad al ' + cierreLabel + ') para calcular cuota menor/mayor:',
                String(anioDef)
            );
            if (anioStr == null) return;
            const anio = parseInt(anioStr, 10);
            if (isNaN(anio) || anio < 2000 || anio > 2100) {
                alert('Año no válido.');
                return;
            }
            const _cp = typeof ClubAccounting !== 'undefined' ? ClubAccounting.getMembershipPricing() : { cuotaMenor: 10, cuotaMayor: 25 };
            const refLabel = anio + '-' + String(getMembershipSeasonCfg().closeMonth).padStart(2, '0') + '-' + String(getMembershipSeasonCfg().closeDay).padStart(2, '0');
            if (!confirm(
                `Se marcarán como PENDIENTES DE PAGO todos los socios ACTIVOS (renovación de temporada).\n` +
                `Tú validarás UNO A UNO cuando veas cada ingreso en la cuenta — no hay validación masiva.\n\n` +
                `• Cuota según edad al ${cierreLabel}: ${_cp.cuotaMenor} € (menor) / ${_cp.cuotaMayor} € (mayor)\n` +
                `• Altas nuevas offline: ${getMembershipSeasonCfg().paymentDeadlineDays} días. Renovaciones: sin caducidad automática.\n\n¿Continuar?`
            )) return;

            try {
                const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const temporada = `${anio - 1}-${anio}`;
                let n = 0;
                let syncFailed = false;

                for (let i = 0; i < members.length; i++) {
                    if (normalizeClubMember(members[i]).status !== 'active') continue;
                    const cuota = cuotaSegunEdadAlCierre(members[i], anio);
                    members[i].status = 'pending_validation';
                    members[i].estado = 'pendiente';
                    members[i].pagado = false;
                    members[i].pendingReason = 'renovacion';
                    members[i].cuota = cuota;
                    members[i].renovacionDesde = new Date().toISOString();
                    members[i].fechaLimitePago = null;
                    members[i].diasLimiteRenovacion = null;
                    members[i].renovacionTemporada = temporada;
                    members[i].cuotaReferenciaEdadCierre = refLabel;
                    members[i].cuotaReferenciaEdad31Agosto = refLabel;
                    members[i].lastModified = new Date().toISOString();
                    n++;
                    try {
                        await persistMemberToFirebase(members[i]);
                    } catch (e) {
                        syncFailed = true;
                        console.warn('Renovación masiva — error Firebase:', e);
                    }
                }

                syncMembersLocalStorage(members);
                loadMembersList();
                updateMemberCounts();
                updateDashboardCounts();

                let msg = n === 0
                    ? 'ℹ️ No había socios activos para renovar.'
                    : `✅ ${n} socio(s) pasado(s) a pendiente de renovación (temporada ${temporada}).`;
                if (syncFailed) msg += '\n\n⚠️ Algunos no se sincronizaron con la nube.';
                alert(msg);
                markCuotaRenovacionMasivaHecha();
            } catch (e) {
                console.error(e);
                alert('❌ Error al aplicar la nueva temporada de cuotas.');
            }
        }

        const LS_CUOTA_CIERRE_OK = 'cuotaRenovacionMasivaUltimoCierre';
        const LS_CUOTA_RECORD_DESCARTE = 'cuotaRenovacionRecordatorioDescartado';

        function getUltimoCierreCerradoAnio() {
            if (typeof ClubMembershipSeason !== 'undefined' && ClubMembershipSeason.getSeasonCloseYearToProcess) {
                const y = ClubMembershipSeason.getSeasonCloseYearToProcess();
                return y != null ? y : new Date().getFullYear() - 1;
            }
            const now = new Date();
            const y = now.getFullYear();
            const c = getMembershipSeasonCfg();
            const close = new Date(y, c.closeMonth - 1, c.closeDay, 23, 59, 59, 999);
            if (now > close) return y;
            return y - 1;
        }

        function getUltimo31AgostoCerradoAnio() {
            return getUltimoCierreCerradoAnio();
        }

        function getCierreCuotaKey() {
            if (typeof ClubMembershipSeason !== 'undefined' && ClubMembershipSeason.getCurrentAutoRenewalKey) {
                const k = ClubMembershipSeason.getCurrentAutoRenewalKey();
                if (k) return k;
            }
            const y = (typeof ClubAccounting !== 'undefined' && ClubAccounting.getCuotaEdadReferenciaAnio)
                ? ClubAccounting.getCuotaEdadReferenciaAnio()
                : getUltimoCierreCerradoAnio();
            const c = getMembershipSeasonCfg();
            const m = String(c.closeMonth).padStart(2, '0');
            const d = String(c.closeDay).padStart(2, '0');
            return 'cierre-' + y + '-' + m + '-' + d;
        }

        function shouldShowCuotaRenewalBanner() {
            const key = getCierreCuotaKey();
            if (localStorage.getItem(LS_CUOTA_CIERRE_OK) === key) return false;
            if (localStorage.getItem(LS_CUOTA_RECORD_DESCARTE) === key) return false;
            return true;
        }

        /** Llama el propio flujo de renovación masiva al terminar bien. El admin puede usar también «Ya está hecho». */
        function markCuotaRenovacionMasivaHecha() {
            try {
                localStorage.setItem(LS_CUOTA_CIERRE_OK, getCierreCuotaKey());
                refreshCuotaRenewalBanner();
            } catch (e) { console.warn(e); }
        }

        function markCuotaRenovacionMasivaHechaManual() {
            if (!confirm('¿Confirmas que la renovación de cuotas para este cierre de temporada ya está gestionada (o no aplica)? Se ocultará el recordatorio hasta el próximo 31 de mayo.')) return;
            markCuotaRenovacionMasivaHecha();
        }

        function dismissCuotaRenewalBanner() {
            try {
                localStorage.setItem(LS_CUOTA_RECORD_DESCARTE, getCierreCuotaKey());
                refreshCuotaRenewalBanner();
            } catch (e) { console.warn(e); }
        }

        function refreshCuotaRenewalBanner() {
            const el = document.getElementById('cuotaRenewalReminderBanner');
            if (!el) return;
            const show = shouldShowCuotaRenewalBanner();
            el.style.display = show ? 'block' : 'none';
            const lbl = document.getElementById('cuotaRenewalCierreLabel');
            if (lbl) {
                const yLbl = (typeof ClubAccounting !== 'undefined' && ClubAccounting.getCuotaEdadReferenciaAnio)
                    ? ClubAccounting.getCuotaEdadReferenciaAnio()
                    : getUltimoCierreCerradoAnio();
                lbl.textContent = (typeof ClubMembershipSeason !== 'undefined' && ClubMembershipSeason.formatCierreLabel)
                    ? ClubMembershipSeason.formatCierreLabel(yLbl)
                    : ('31 de mayo de ' + yLbl);
            }
        }

        window.refreshCuotaRenewalBanner = refreshCuotaRenewalBanner;

        /** Llama a la función Netlify que aplica renovación automática tras el 31/05 (idempotente). */
        async function triggerAutomaticSeasonRenewal(options) {
            const silent = options && options.silent;
            try {
                const headers = { 'Content-Type': 'application/json' };
                if (window.CdsanAdminApiAuth && window.CdsanAdminApiAuth.getAdminAuthHeaders) {
                    Object.assign(headers, await window.CdsanAdminApiAuth.getAdminAuthHeaders());
                }
                const res = await fetch('/.netlify/functions/member-season-renewal', {
                    method: 'POST',
                    headers: headers,
                    body: '{}'
                });
                const data = await res.json().catch(() => ({}));
                if (!res.ok || !data.ok) {
                    if (!silent) console.warn('Renovación automática:', data.error || res.status);
                    return data;
                }
                if (data.updated > 0) {
                    console.log('📆 Renovación automática:', data.updated, 'socio(s) → pendiente renovación');
                    try {
                        loadMembersList();
                        updateMemberCounts();
                        updateDashboardCounts();
                    } catch (_) {}
                }
                return data;
            } catch (e) {
                if (!silent) console.warn('triggerAutomaticSeasonRenewal:', e);
                return { ok: false, error: e.message };
            }
        }

        function checkAutomaticSeasonRenewal() {
            triggerAutomaticSeasonRenewal({ silent: true }).catch((e) => console.warn(e));
        }

        async function cleanExpiredMembers() {
            if (!confirm('¿Estás seguro de que quieres eliminar TODOS los socios caducados?\n\n⚠️ Incluye: pendientes de alta que superaron el plazo de ingreso, y registros con estado «caducado». No afecta a renovaciones dentro de plazo.')) return;
            try {
                const members = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const expiredMembers = members.filter(m => isMemberExpired(m));
                if (expiredMembers.length === 0) {
                    alert('ℹ️ No hay socios caducados para eliminar.');
                    return;
                }
                const failed = [];
                for (const m of expiredMembers) {
                    try {
                        await removeMemberFromCloudIfNeeded(m.id, { email: m.email, dni: m.dni });
                    } catch (e) {
                        console.warn('No se pudo eliminar en Firebase:', m.id, e);
                        failed.push(m);
                    }
                }
                const updatedMembers = members.filter(mem => {
                    if (!isMemberExpired(mem)) return true;
                    return failed.some(f => String(f.id) === String(mem.id));
                });
                syncMembersLocalStorage(updatedMembers);
                loadMembersList();
                updateMemberCounts();
                updateDashboardCounts();
                const ok = expiredMembers.length - failed.length;
                if (failed.length > 0) {
                    alert(`⚠️ Eliminados en el servidor: ${ok}.\nNo se pudieron borrar en la nube: ${failed.length} (siguen en la lista hasta que funcione la conexión o permisos).`);
                } else {
                    alert(`🗑️ ${expiredMembers.length} socios caducados eliminados correctamente (también en el servidor).`);
                }
                console.log('🗑️ Limpieza caducados:', { total: expiredMembers.length, ok, failed: failed.length });
            } catch (error) {
                console.error('❌ Error eliminando socios caducados:', error);
                alert('❌ Error al eliminar los socios caducados');
            }
        }

        function updateMemberCounts() {
            try {
                const membersRaw = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const members = dedupeMembersList(membersRaw);
                
                const activeCount = members.filter(m => m.status === 'active').length;
                const pendingCount = members.filter(m => m.status === 'pending_validation').length;
                const expiredCount = members.filter(m => isMemberExpired(m)).length;
                
                // Actualizar contadores en la interfaz
                const activeElement = document.getElementById('activeMembersCount');
                const pendingElement = document.getElementById('pendingMembersCount');
                const expiredElement = document.getElementById('expiredMembersCount');
                
                if (activeElement) activeElement.textContent = activeCount;
                if (pendingElement) pendingElement.textContent = pendingCount;
                if (expiredElement) expiredElement.textContent = expiredCount;
                
                // Calcular próximo número de socio
                const nextNumber = activeCount + 1;
                const nextElement = document.getElementById('nextMemberNumber');
                if (nextElement) nextElement.textContent = nextNumber;
                
                console.log('📊 Contadores de socios actualizados:', { activeCount, pendingCount, expiredCount, nextNumber });
                if (typeof actualizarContadorNotificacionesAdmin === 'function') actualizarContadorNotificacionesAdmin();
                
            } catch (error) {
                console.error('❌ Error actualizando contadores de socios:', error);
            }
        }

        // ===== ACTUALIZACIÓN DE CONTADORES DE CATEGORÍAS =====
        function updateCategoryCounts() {
            try {
                // PONER TODOS LOS CONTADORES DE CATEGORÍAS A CERO
                const categories = ['prebenajmin', 'benjamin', 'alevin', 'infantil', 'cadete', 'juvenil', 'aficionado'];
                categories.forEach(category => {
                    const element = document.getElementById(category + 'Count');
                    if (element) {
                        element.textContent = '0';
                    }
                });
                
                console.log('📊 Contadores de categorías reseteados a cero');
                
            } catch (error) {
                console.error('❌ Error actualizando contadores de categorías:', error);
            }
        }

        // ===== ACTUALIZACIÓN DE FUNCIÓN updateDashboardCounts =====
        function updateDashboardCounts() {
            try {
                const players = JSON.parse(localStorage.getItem('clubPlayers') || '[]');
                const membersRaw = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const members = dedupeMembersList(membersRaw);
                const friends = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                const events = JSON.parse(localStorage.getItem('clubEvents') || localStorage.getItem('events') || '[]');
                const competitions = JSON.parse(localStorage.getItem('clubCompetitions') || '[]');

                const activePlayers = players.filter(p => p && p.status === 'active').length;
                const activeMembers = members.filter(m => normalizeClubMember(m).status === 'active').length;
                const activeFriends = friends.filter(f => (f.estado || f.status) === 'activo' || (f.estado || f.status) === 'active').length;
                const eventsCount = events.length;
                const competitionsCount = competitions.length;
                const teamsList = JSON.parse(localStorage.getItem('clubTeams') || '[]');
                const teamsRegistered = Array.isArray(teamsList) ? teamsList.length : 0;

                // Actualizar elementos del dashboard
                const playersElement = document.getElementById('playersCount');
                const membersElement = document.getElementById('membersCount');
                const eventsElement = document.getElementById('eventsCount');
                const competitionsElement = document.getElementById('competitionsCount');
                const friendsElement = document.getElementById('friendsCount');
                const teamsElement = document.getElementById('teamsCount');
                const teamsCaption = document.getElementById('teamsCountCaption');

                if (playersElement) playersElement.textContent = activePlayers;
                if (membersElement) membersElement.textContent = activeMembers;
                if (eventsElement) eventsElement.textContent = eventsCount;
                if (competitionsElement) competitionsElement.textContent = competitionsCount;
                if (friendsElement) friendsElement.textContent = activeFriends;
                if (teamsElement) teamsElement.textContent = String(teamsRegistered);
                if (teamsCaption) {
                    teamsCaption.textContent = teamsRegistered > 0
                        ? 'Equipos registrados'
                        : 'Plantilla: categorías en pestaña Equipos';
                }

                console.log('📊 Dashboard actualizado:', { teamsRegistered, activePlayers, activeMembers, activeFriends, eventsCount, competitionsCount });
                if (typeof actualizarContadorNotificacionesAdmin === 'function') actualizarContadorNotificacionesAdmin();
                
            } catch (error) {
                console.error('❌ Error actualizando dashboard:', error);
            }
        }

        // ===== MÓDULO DE AMIGOS DEL CLUB =====
        
        function showAddFriendForm() {
            const form = document.getElementById('addFriendForm');
            if (form) {
                form.style.display = 'block';
                clearFriendForm();
            }
        }

        function cancelAddFriend() {
            const form = document.getElementById('addFriendForm');
            if (form) {
                form.style.display = 'none';
                clearFriendForm();
            }
        }

        function clearFriendForm() {
            document.getElementById('friendName').value = '';
            document.getElementById('friendSurname').value = '';
            document.getElementById('friendDNI').value = '';
            document.getElementById('friendPhone').value = '';
            document.getElementById('friendEmail').value = '';
            const fp = document.getElementById('friendPassword');
            const fc = document.getElementById('friendPasswordConfirm');
            if (fp) fp.value = '';
            if (fc) fc.value = '';
        }

        async function saveFriend() {
            try {
                const name = document.getElementById('friendName').value.trim();
                const surname = document.getElementById('friendSurname').value.trim();
                const dni = document.getElementById('friendDNI').value.trim();
                const phone = document.getElementById('friendPhone').value.trim();
                const email = document.getElementById('friendEmail').value.trim();
                const password = document.getElementById('friendPassword') ? document.getElementById('friendPassword').value.trim() : '';
                const passwordConfirm = document.getElementById('friendPasswordConfirm') ? document.getElementById('friendPasswordConfirm').value.trim() : '';

                // Validar campos obligatorios
                if (!name || !surname || !dni || !phone || !email || !password) {
                    alert('❌ Error: Todos los campos son obligatorios (incluida la contraseña de acceso).');
                    return;
                }
                if (password !== passwordConfirm) {
                    alert('❌ Las contraseñas no coinciden.');
                    return;
                }

                // Validar formato de email
                const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                if (!emailRegex.test(email)) {
                    alert('❌ Error: El formato del correo electrónico no es válido.');
                    return;
                }

                // Obtener amigos existentes
                const friends = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                
                // Verificar DNI único
                const existingFriendByDNI = friends.find(f => f.dni && f.dni.toLowerCase() === dni.toLowerCase());
                if (existingFriendByDNI) {
                    alert('❌ Error: Ya existe un amigo del club con ese DNI.');
                    return;
                }

                // Verificar email único
                const existingFriendByEmail = friends.find(f => f.email && f.email.toLowerCase() === email.toLowerCase());
                if (existingFriendByEmail) {
                    alert('❌ Error: Ya existe un amigo del club con ese correo electrónico.');
                    return;
                }

                // Verificar teléfono único
                const existingFriendByPhone = friends.find(f => f.phone && f.phone === phone);
                if (existingFriendByPhone) {
                    alert('❌ Error: Ya existe un amigo del club con ese número de teléfono.');
                    return;
                }

                const newFriend = {
                    id: 'FRIEND_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
                    name: name,
                    surname: surname,
                    nombre: name,
                    apellidos: surname,
                    dni: dni,
                    phone: phone,
                    telefono: phone,
                    email: email,
                    status: 'active',
                    registrationDate: new Date().toISOString(),
                    appScope: 'cdsanabriacf',
                    registrationSource: 'admin_panel',
                    lastAccess: null,
                    accessCount: 0
                };

                if (password && window.cdsanClubAuth && window.firebaseAuth && !window.firebaseAuth.isSimulation) {
                    try {
                        const reg = await window.cdsanClubAuth.registerEmail(String(email).trim().toLowerCase(), password);
                        if (!reg.simulation && reg.uid) {
                            newFriend.authUid = reg.uid;
                            newFriend.uid = reg.uid;
                        }
                    } catch (e) {
                        console.error('saveFriend Firebase Auth:', e);
                        if (e && e.code === 'auth/email-already-in-use') {
                            alert('❌ Ese correo ya tiene cuenta. El amigo puede usar «Olvidé mi contraseña» o registrarse en la web.');
                        } else {
                            alert('❌ No se pudo crear la cuenta de acceso del amigo en Firebase.');
                        }
                        return;
                    }
                } else if (password && typeof window.hashClubAccessKey === 'function') {
                    newFriend.passwordHash = await window.hashClubAccessKey(password);
                }

                friends.push(newFriend);
                syncFriendsLocalStorage(friends);
                await persistFriendToFirebase(newFriend);

                cancelAddFriend();
                loadFriendsList();
                updateFriendCounts();
                updateDashboardCounts();
                if (typeof updateDatabaseStats === 'function') updateDatabaseStats();

                let avisoPwd = '';
                if (password && window.firebaseAuth && !window.firebaseAuth.isSimulation) {
                    avisoPwd =
                        '\n\n🔐 Acceso web: el amigo debe registrarse en la página pública con su correo o usar «Olvidé mi contraseña». La clave no se guarda en el panel.';
                }
                alert('✅ Amigo del club registrado correctamente.' + avisoPwd);
                console.log('🤝 Nuevo amigo del club registrado:', newFriend.name + ' ' + newFriend.surname);

            } catch (error) {
                console.error('❌ Error guardando amigo del club:', error);
                alert('❌ Error al guardar el amigo del club. Inténtalo de nuevo.');
            }
        }

        function loadFriendsList() {
            try {
                const friends = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                const friendsList = document.getElementById('friendsList');
                const statusFilter = document.getElementById('friendStatusFilter').value;

                if (!friendsList) return;

                // Filtrar amigos según el estado
                let filteredFriends = friends;
                if (statusFilter !== 'all') {
                    filteredFriends = friends.filter(friend => friend.status === statusFilter);
                }

                if (filteredFriends.length === 0) {
                    friendsList.innerHTML = '<div style="text-align: center; padding: 20px; color: #666;">No hay amigos del club que mostrar con los filtros actuales.</div>';
                    return;
                }

                let html = '';
                filteredFriends.forEach(friend => {
                    const fr = normalizeClubFriend(friend);
                    const statusColor = fr.status === 'active' ? '#059669' : '#6c757d';
                    const statusText = fr.status === 'active' ? 'Activo' : 'Inactivo';
                    const lastAccessText = fr.lastAccess ? new Date(fr.lastAccess).toLocaleDateString('es-ES') : 'Nunca';
                    const pwdLabel = 'Gestionada de forma segura (no visible)';

                    html += `
                        <div style="background: white; padding: 15px; border-radius: 8px; margin-bottom: 10px; border-left: 4px solid ${statusColor};">
                            <div style="display: flex; justify-content: space-between; align-items: flex-start;">
                                <div>
                                    <h4 style="margin: 0 0 5px 0; color: #1e3a8a;">${fr.name} ${fr.surname}</h4>
                                    <p style="margin: 2px 0; color: #666;"><strong>DNI:</strong> ${fr.dni}</p>
                                    <p style="margin: 2px 0; color: #666;"><strong>Teléfono:</strong> ${fr.phone}</p>
                                    <p style="margin: 2px 0; color: #666;"><strong>Email:</strong> ${fr.email}</p>
                                    <p style="margin: 2px 0; color: #059669; font-weight: 600;"><strong>Contraseña:</strong> ${pwdLabel} <span style="font-weight:400; color:#6b7280; font-size:0.85em;">(solo puntos)</span></p>
                                    <p style="margin: 2px 0; color: #666;"><strong>Registro:</strong> ${new Date(fr.registrationDate).toLocaleDateString('es-ES')}</p>
                                    <p style="margin: 2px 0; color: #666;"><strong>Último acceso:</strong> ${lastAccessText}</p>
                                    <p style="margin: 2px 0; color: #666;"><strong>Accesos:</strong> ${friend.accessCount != null ? friend.accessCount : 0}</p>
                                    ${friend.torneoResponsableEnabled || friend.canTorneoResponsable ? '<p style="margin: 2px 0; color: #7c3aed; font-weight:600;">⚽ Responsable de equipo habilitado</p>' : ''}
                                </div>
                                <div style="display: flex; flex-direction: column; gap: 5px;">
                                    <span style="background: ${statusColor}; color: white; padding: 2px 8px; border-radius: 12px; font-size: 0.8rem;">${statusText}</span>
                                    <button class="btn btn-sm" onclick="viewFriendDetails('${friend.id}')" style="font-size: 0.8rem;">👁️ Ver</button>
                                    <button class="btn btn-sm" onclick="editFriend('${friend.id}')" style="font-size: 0.8rem; background:#f59e0b; color:white; border:none; border-radius:4px; cursor:pointer;">✏️ Editar</button>
                                    <button class="btn btn-sm" onclick="toggleFriendStatus('${friend.id}')" style="font-size: 0.8rem;">${fr.status === 'active' ? '⏸️ Desactivar' : '▶️ Activar'}</button>
                                    <button class="btn btn-sm btn-danger" onclick="deleteFriend('${friend.id}')" style="font-size: 0.8rem;">🗑️ Eliminar</button>
                                </div>
                            </div>
                        </div>
                    `;
                });

                friendsList.innerHTML = html;
                console.log('🤝 Lista de amigos del club cargada:', filteredFriends.length);

            } catch (error) {
                console.error('❌ Error cargando lista de amigos del club:', error);
                const friendsList = document.getElementById('friendsList');
                if (friendsList) {
                    friendsList.innerHTML = '<div style="text-align: center; padding: 20px; color: #dc2626;">Error al cargar la lista de amigos del club.</div>';
                }
            }
        }

        function filterFriends() {
            loadFriendsList();
        }

        function viewFriendDetails(friendId) {
            try {
                const friends = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                const friend = friends.find(f => f.id === friendId);
                
                if (!friend) {
                    alert('❌ Amigo del club no encontrado.');
                    return;
                }

                const lastAccessText = friend.lastAccess ? new Date(friend.lastAccess).toLocaleString('es-ES') : 'Nunca ha accedido';
                const statusText = friend.status === 'active' ? 'Activo' : 'Inactivo';

                const details = `
🤝 DETALLES DEL AMIGO DEL CLUB

👤 DATOS PERSONALES:
• Nombre: ${friend.name} ${friend.surname}
• DNI: ${friend.dni}
• Teléfono: ${friend.phone}
• Correo Electrónico: ${friend.email}

📊 INFORMACIÓN DE ACCESO:
• Estado: ${statusText}
• Fecha de Registro: ${new Date(friend.registrationDate).toLocaleDateString('es-ES')}
• Último Acceso: ${lastAccessText}
• Número de Accesos: ${friend.accessCount}

🔐 PERMISOS:
• Solo puede ver calendario y competiciones
• Acceso web: correo + contraseña (la clave no se muestra, solo en Editar se puede asignar otra)
• No puede modificar datos del club desde el panel
                `;

                alert(details);

            } catch (error) {
                console.error('❌ Error mostrando detalles del amigo del club:', error);
                alert('❌ Error al mostrar los detalles del amigo del club.');
            }
        }

        async function toggleFriendStatus(friendId) {
            try {
                const friends = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                const friendIndex = friends.findIndex(f => f.id === friendId);
                
                if (friendIndex === -1) {
                    alert('❌ Amigo del club no encontrado.');
                    return;
                }

                const friend = friends[friendIndex];
                const newStatus = friend.status === 'active' ? 'inactive' : 'active';
                const statusText = newStatus === 'active' ? 'activar' : 'desactivar';

                if (!confirm(`¿Estás seguro de que quieres ${statusText} a ${friend.name} ${friend.surname}?`)) return;

                friends[friendIndex].status = newStatus;
                friends[friendIndex].updatedAt = new Date().toISOString();
                syncFriendsLocalStorage(friends);
                await persistFriendToFirebase(friends[friendIndex]);

                loadFriendsList();
                updateFriendCounts();
                updateDashboardCounts();

                alert(`✅ Amigo del club ${statusText === 'activar' ? 'activado' : 'desactivado'} correctamente (sincronizado con la nube).`);
                console.log(`🤝 Amigo del club actualizado:`, friend.name + ' ' + friend.surname, newStatus);

            } catch (error) {
                console.error('❌ Error cambiando estado del amigo del club:', error);
                alert('❌ No se pudo actualizar en la nube.\n\n' + (error.message || String(error)));
            }
        }

        async function deleteFriend(friendId) {
            if (!confirm('¿Estás seguro de que quieres eliminar este amigo del club?\n\n⚠️ Esta acción no se puede deshacer.')) return;
            try {
                const friends = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                const friend = friends.find(f => String(f.id) === String(friendId));
                if (!friend) {
                    alert('❌ Amigo del club no encontrado.');
                    return;
                }
                try {
                    await removeFriendFromCloudIfNeeded(friend.id);
                } catch (syncErr) {
                    console.error('❌ Error eliminando amigo en Firebase:', syncErr);
                    alert('❌ No se pudo eliminar en el servidor (nube).\n\nSi no se borra en la nube, el amigo volverá a aparecer al sincronizar.\n\n' + (syncErr.message || String(syncErr)));
                    return;
                }
                const updatedFriends = friends.filter(f => String(f.id) !== String(friendId));
                syncFriendsLocalStorage(updatedFriends);
                loadFriendsList();
                updateFriendCounts();
                updateDashboardCounts();
                if (typeof updateDatabaseStats === 'function') updateDatabaseStats();
                alert('✅ Amigo del club eliminado correctamente (también en el servidor).');
                console.log('🗑️ Amigo del club eliminado:', friend.name + ' ' + friend.surname);
            } catch (error) {
                console.error('❌ Error eliminando amigo del club:', error);
                alert('❌ Error al eliminar el amigo del club.');
            }
        }

        function _aq(v) {
            return String(v ?? '').replace(/"/g, '&quot;');
        }

