        // Cambiar estado del entrenador
        async function toggleCoachStatus(coachId) {
            try {
                const coaches = JSON.parse(localStorage.getItem('clubCoaches') || '[]');
                const coachIndex = coaches.findIndex(c => c.id === coachId);
                
                if (coachIndex === -1) {
                    alert('❌ Entrenador no encontrado');
                    return;
                }

                const coach = coaches[coachIndex];
                const newStatus = coach.status === 'active' ? 'inactive' : 'active';
                
                coaches[coachIndex].status = newStatus;
                coaches[coachIndex].statusChangeDate = new Date().toISOString();
                
                localStorage.setItem('clubCoaches', JSON.stringify(coaches));
                await persistRecordToFirebase('clubCoaches', 'coaches', coaches[coachIndex]);
                
                alert(`✅ Estado del entrenador ${coach.name} ${coach.surname} cambiado a ${newStatus === 'active' ? 'Activo' : 'Inactivo'}`);
                
                loadCoachesList();
                updateCoachCounts();

            } catch (error) {
                console.error('❌ Error cambiando estado del entrenador:', error);
                alert('❌ Error al cambiar el estado del entrenador');
            }
        }

        // Eliminar entrenador
        async function deleteCoach(coachId) {
            try {
                const coaches = JSON.parse(localStorage.getItem('clubCoaches') || '[]');
                const coach = coaches.find(c => c.id === coachId);
                
                if (!coach) {
                    alert('❌ Entrenador no encontrado');
                    return;
                }

                const confirmDelete = confirm(`⚠️ ¿Estás seguro de que quieres eliminar al entrenador ${coach.name} ${coach.surname}?\n\nEsta acción no se puede deshacer.`);
                
                if (!confirmDelete) return;

                const updatedCoaches = coaches.filter(c => c.id !== coachId);
                localStorage.setItem('clubCoaches', JSON.stringify(updatedCoaches));
                if (window.AdminClubCloudPersist && typeof window.AdminClubCloudPersist.deleteCoach === 'function' && !String(coachId).startsWith('COACH_') && !/^\d{12,}$/.test(String(coachId))) {
                    try {
                        await window.AdminClubCloudPersist.deleteCoach(coachId);
                    } catch (e) {
                        console.warn('Netlify delete coach:', e);
                    }
                }
                await deleteRecordFromFirebase('coaches', coachId);
                await refreshLinkedMemberRoles(coach.dni, coach.name, coach.surname);
                
                alert(`✅ Entrenador ${coach.name} ${coach.surname} eliminado correctamente`);
                
                loadCoachesList();
                loadMembersList();
                updateCoachCounts();

            } catch (error) {
                console.error('❌ Error eliminando entrenador:', error);
                alert('❌ Error al eliminar el entrenador');
            }
        }

        async function resetCoachAccessKey(coachId) {
            try {
                const coaches = JSON.parse(localStorage.getItem('clubCoaches') || '[]');
                const coachIndex = coaches.findIndex(c => c.id === coachId);
                if (coachIndex === -1) {
                    alert('❌ Entrenador no encontrado');
                    return;
                }
                const coach = coaches[coachIndex];
                const suggestedKey = Array.from({ length: 10 }).map(() => 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#'.charAt(Math.floor(Math.random() * 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#'.length))).join('');
                const newKey = prompt(`Nueva clave de acceso para ${coach.name} ${coach.surname}:`, suggestedKey);
                if (newKey == null) return;
                const trimmed = newKey.trim();
                if (!trimmed) {
                    alert('❌ La clave no puede estar vacía');
                    return;
                }
                coach.passwordHash = await hashCoachAccessKey(trimmed);
                coach.adminAccessKey = trimmed;
                if (coach.password) delete coach.password;
                coach.keyUpdatedAt = new Date().toISOString();
                coach.failedLoginAttempts = 0;
                coach.lockUntil = null;
                coaches[coachIndex] = coach;
                localStorage.setItem('clubCoaches', JSON.stringify(coaches));
                await persistRecordToFirebase('clubCoaches', 'coaches', coach);
                appendCoachActivityLog({
                    action: 'key_reset_by_admin',
                    coachId: coach.id,
                    team: coach.team
                });
                alert('✅ Clave de acceso actualizada');
                loadCoachesList();
            } catch (error) {
                console.error('❌ Error actualizando clave de entrenador:', error);
                alert('❌ No se pudo actualizar la clave');
            }
        }

        async function removeCoachAccessKey(coachId) {
            try {
                const coaches = JSON.parse(localStorage.getItem('clubCoaches') || '[]');
                const coachIndex = coaches.findIndex(c => c.id === coachId);
                if (coachIndex === -1) {
                    alert('❌ Entrenador no encontrado');
                    return;
                }
                const coach = coaches[coachIndex];
                if (!confirm(`¿Eliminar la clave de acceso de ${coach.name} ${coach.surname}?`)) return;
                coach.passwordHash = null;
                delete coach.adminAccessKey;
                if (coach.password) delete coach.password;
                coach.keyUpdatedAt = new Date().toISOString();
                coach.failedLoginAttempts = 0;
                coach.lockUntil = null;
                coaches[coachIndex] = coach;
                localStorage.setItem('clubCoaches', JSON.stringify(coaches));
                await persistRecordToFirebase('clubCoaches', 'coaches', coach);
                appendCoachActivityLog({
                    action: 'key_removed_by_admin',
                    coachId: coach.id,
                    team: coach.team
                });
                alert('✅ Clave eliminada. Ahora debes generar una nueva.');
                loadCoachesList();
            } catch (error) {
                console.error('❌ Error eliminando clave de entrenador:', error);
                alert('❌ No se pudo eliminar la clave');
            }
        }

        async function editCoachPermissions(coachId) {
            try {
                const coaches = JSON.parse(localStorage.getItem('clubCoaches') || '[]');
                const coachIndex = coaches.findIndex(c => c.id === coachId);
                if (coachIndex === -1) return alert('❌ Entrenador no encontrado');
                const coach = coaches[coachIndex];
                const current = { ...getDefaultCoachPermissions(), ...(coach.permissions || {}) };
                const lineups = confirm(`Permitir convocatorias/alineaciones a ${coach.name}?`);
                const training = confirm(`Permitir entrenamientos de equipo a ${coach.name}?`);
                const individual = confirm(`Permitir planes individuales a ${coach.name}?`);
                const exportPerm = confirm(`Permitir exportaciones a ${coach.name}?`);
                coach.permissions = {
                    ...current,
                    lineups,
                    training,
                    individual,
                    export: exportPerm
                };
                coaches[coachIndex] = coach;
                localStorage.setItem('clubCoaches', JSON.stringify(coaches));
                await persistRecordToFirebase('clubCoaches', 'coaches', coach);
                appendCoachActivityLog({
                    action: 'permissions_updated_by_admin',
                    coachId: coach.id,
                    team: coach.team
                });
                alert('✅ Permisos actualizados');
                loadCoachesList();
            } catch (error) {
                console.error('❌ Error actualizando permisos:', error);
                alert('❌ No se pudieron actualizar permisos');
            }
        }

        // Actualizar contadores de entrenadores
        function updateCoachCounts() {
            try {
                const coaches = JSON.parse(localStorage.getItem('clubCoaches') || '[]');
                
                const activeCount = coaches.filter(c => c.status === 'active').length;
                const inactiveCount = coaches.filter(c => c.status === 'inactive').length;
                const totalCount = coaches.length;
                
                // Actualizar contadores en la interfaz
                const activeElement = document.getElementById('activeCoachesCount');
                const inactiveElement = document.getElementById('inactiveCoachesCount');
                const totalElement = document.getElementById('totalCoachesCount');
                
                if (activeElement) activeElement.textContent = activeCount;
                if (inactiveElement) inactiveElement.textContent = inactiveCount;
                if (totalElement) totalElement.textContent = totalCount;
                
                console.log('📊 Contadores de entrenadores actualizados:', { activeCount, inactiveCount, totalCount });
                
            } catch (error) {
                console.error('❌ Error actualizando contadores de entrenadores:', error);
            }
        }

        function getBoardRoleLabel(role) {
            const map = {
                presidencia: 'Presidencia',
                vicepresidencia: 'Vicepresidencia',
                secretaria: 'Secretaría',
                tesoreria: 'Tesorería',
                vocalia: 'Vocalía'
            };
            return map[role] || role || 'Cargo';
        }

        function getBoardRoleOrder(role) {
            const map = {
                presidencia: 1,
                vicepresidencia: 2,
                secretaria: 3,
                tesoreria: 4,
                vocalia: 5
            };
            return map[role] || 99;
        }

        function showAddBoardMemberForm() {
            document.getElementById('addBoardMemberForm').style.display = 'block';
            clearBoardMemberForm();
        }

        function cancelAddBoardMember() {
            document.getElementById('addBoardMemberForm').style.display = 'none';
            clearBoardMemberForm();
        }

        function clearBoardMemberForm() {
            document.getElementById('boardMemberName').value = '';
            document.getElementById('boardMemberSurname').value = '';
            document.getElementById('boardMemberDNI').value = '';
            document.getElementById('boardMemberRole').value = '';
            document.getElementById('boardMemberArea').value = '';
            const visibleInput = document.getElementById('boardMemberVisible');
            if (visibleInput) visibleInput.checked = true;
        }

        async function saveBoardMember() {
            try {
                const name = document.getElementById('boardMemberName').value.trim();
                const surname = document.getElementById('boardMemberSurname').value.trim();
                const dni = document.getElementById('boardMemberDNI').value.trim().toUpperCase();
                const role = document.getElementById('boardMemberRole').value;
                const area = document.getElementById('boardMemberArea').value.trim();
                const visible = !!document.getElementById('boardMemberVisible')?.checked;

                if (!name || !role || !dni) {
                    alert('❌ Completa nombre, DNI y cargo.');
                    return;
                }

                const board = JSON.parse(localStorage.getItem('clubBoard') || '[]');
                if (board.some(member => String(member.dni || '').trim().toUpperCase() === dni)) {
                    alert('❌ Ya existe una persona de directiva con ese DNI.');
                    return;
                }
                const newMember = {
                    id: Date.now().toString(),
                    name,
                    surname,
                    dni,
                    role,
                    area,
                    visible,
                    status: 'active',
                    createdAt: new Date().toISOString()
                };

                board.push(newMember);
                localStorage.setItem('clubBoard', JSON.stringify(board));
                await persistRecordToFirebase('clubBoard', 'board', newMember);
                await refreshLinkedMemberRoles(dni, name, surname);

                cancelAddBoardMember();
                loadBoardMembersList();
                loadMembersList();
                alert(`✅ Cargo guardado: ${getBoardRoleLabel(role)} - ${name} ${surname}`.trim());
            } catch (error) {
                console.error('❌ Error guardando directiva:', error);
                alert('❌ No se pudo guardar el cargo de directiva.');
            }
        }

        function loadBoardMembersList() {
            try {
                const board = JSON.parse(localStorage.getItem('clubBoard') || '[]');
                const container = document.getElementById('boardMembersList');
                if (!container) return;

                if (!board.length) {
                    container.innerHTML = '<p style="text-align:center; color:#6c757d;">No hay integrantes de directiva registrados.</p>';
                    return;
                }

                const sorted = [...board].sort((a, b) => {
                    const roleDiff = getBoardRoleOrder(a.role) - getBoardRoleOrder(b.role);
                    if (roleDiff !== 0) return roleDiff;
                    return `${a.name || ''} ${a.surname || ''}`.localeCompare(`${b.name || ''} ${b.surname || ''}`, 'es');
                });

                container.innerHTML = `
                    <div style="display:grid; gap:12px;">
                        ${sorted.map(member => `
                            <div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:10px; padding:14px;">
                                <div style="display:flex; justify-content:space-between; gap:10px; flex-wrap:wrap;">
                                    <div>
                                        <h4 style="margin:0; color:#1e3a8a;">${member.name || ''} ${member.surname || ''}</h4>
                                        <p style="margin:6px 0 0 0; color:#334155;"><strong>${getBoardRoleLabel(member.role)}</strong>${member.area ? ` · ${member.area}` : ''}</p>
                                        <p style="margin:6px 0 0 0; color:#64748b; font-size:0.85rem;">DNI: ${member.dni || 'No indicado'}</p>
                                        <p style="margin:6px 0 0 0; color:#64748b; font-size:0.85rem;">Visibilidad web: ${member.visible ? 'Sí' : 'No'}</p>
                                    </div>
                                    <div>
                                        <button class="btn btn-sm btn-warning" onclick="toggleBoardMemberVisibility('${member.id}')" style="margin-right:6px;">👁️ ${member.visible ? 'Ocultar' : 'Mostrar'}</button>
                                        <button class="btn btn-sm btn-danger" onclick="deleteBoardMember('${member.id}')">🗑️ Eliminar</button>
                                    </div>
                                </div>
                            </div>
                        `).join('')}
                    </div>
                `;
            } catch (error) {
                console.error('❌ Error cargando directiva:', error);
            }
        }

        async function toggleBoardMemberVisibility(memberId) {
            try {
                const board = JSON.parse(localStorage.getItem('clubBoard') || '[]');
                const idx = board.findIndex(m => m.id === memberId);
                if (idx === -1) return alert('❌ Integrante no encontrado');
                board[idx].visible = !board[idx].visible;
                board[idx].updatedAt = new Date().toISOString();
                localStorage.setItem('clubBoard', JSON.stringify(board));
                await persistRecordToFirebase('clubBoard', 'board', board[idx]);
                loadBoardMembersList();
            } catch (error) {
                console.error('❌ Error actualizando visibilidad de directiva:', error);
                alert('❌ No se pudo actualizar la visibilidad.');
            }
        }

        async function deleteBoardMember(memberId) {
            try {
                const board = JSON.parse(localStorage.getItem('clubBoard') || '[]');
                const member = board.find(m => m.id === memberId);
                if (!member) return alert('❌ Integrante no encontrado');
                if (!confirm(`¿Eliminar ${member.name || ''} ${member.surname || ''} de la directiva?`)) return;
                const updated = board.filter(m => m.id !== memberId);
                localStorage.setItem('clubBoard', JSON.stringify(updated));
                await deleteRecordFromFirebase('board', memberId);
                await refreshLinkedMemberRoles(member.dni, member.name, member.surname);
                loadBoardMembersList();
                loadMembersList();
            } catch (error) {
                console.error('❌ Error eliminando integrante de directiva:', error);
                alert('❌ No se pudo eliminar el cargo.');
            }
        }

