        function getSelectedMessageRecipients() {
            return Array.from(document.querySelectorAll('input[name="messageRecipient"]:checked')).map((el) => el.value);
        }

        function getSelectedMessageTeams() {
            const selected = Array.from(document.querySelectorAll('input[name="messageTeam"]:checked')).map((el) => el.value);
            if (!selected.length || selected.includes('all')) return [];
            return selected.filter((v) => v && v !== 'all');
        }

        function onMessageRecipientToggle(changed) {
            const allBox = document.querySelector('input[name="messageRecipient"][value="all"]');
            const others = Array.from(document.querySelectorAll('input[name="messageRecipient"]')).filter((el) => el.value !== 'all');
            if (changed.value === 'all' && changed.checked) {
                others.forEach((el) => { el.checked = false; });
            } else if (changed.value !== 'all' && changed.checked && allBox) {
                allBox.checked = false;
            }
            if (!getSelectedMessageRecipients().length && allBox) {
                allBox.checked = true;
            }
        }

        function onMessageTeamToggle(changed) {
            const allBox = document.querySelector('input[name="messageTeam"][value="all"]');
            const others = Array.from(document.querySelectorAll('input[name="messageTeam"]')).filter((el) => el.value !== 'all');
            if (changed.value === 'all' && changed.checked) {
                others.forEach((el) => { el.checked = false; });
            } else if (changed.value !== 'all' && changed.checked && allBox) {
                allBox.checked = false;
            }
            if (!Array.from(document.querySelectorAll('input[name="messageTeam"]:checked')).length && allBox) {
                allBox.checked = true;
            }
        }

        function resetMessageRecipientChecks() {
            document.querySelectorAll('input[name="messageRecipient"]').forEach((el) => {
                el.checked = el.value === 'all';
            });
        }

        function resetMessageTeamChecks() {
            document.querySelectorAll('input[name="messageTeam"]').forEach((el) => {
                el.checked = el.value === 'all';
            });
        }

        function mapPushRecipientsToTargetRoles(recipients) {
            const map = {
                all: ['all', 'member', 'friend', 'player', 'coach', 'guest'],
                socios: ['member'],
                amigos: ['friend'],
                entrenadores: ['coach'],
                jugadores: ['player'],
                padres: ['member', 'guest']
            };
            const list = Array.isArray(recipients) ? recipients : [recipients];
            if (!list.length || list.includes('all')) return map.all;
            const roles = new Set();
            list.forEach((key) => {
                (map[key] || []).forEach((role) => roles.add(role));
            });
            return roles.size ? Array.from(roles) : map.all;
        }

        function formatRecipientsLabel(recipients) {
            const labels = {
                all: 'Todos los usuarios',
                socios: 'Socios',
                amigos: 'Amigos',
                entrenadores: 'Entrenadores',
                jugadores: 'Jugadores',
                padres: 'Padres/tutores'
            };
            return (recipients || []).map((r) => labels[r] || r).join(', ');
        }

        function formatTeamsLabel(teams) {
            if (!teams || !teams.length) return 'Todos los equipos';
            const labels = {
                prebenjamin: 'Prebenjamín',
                benjamin: 'Benjamín',
                alevin: 'Alevín',
                infantil: 'Infantil',
                cadete: 'Cadete',
                juvenil: 'Juvenil',
                aficionado: 'Aficionado'
            };
            return teams.map((t) => labels[t] || t).join(', ');
        }

        async function dispatchClubPushNotification(message) {
            const fnUrl = '/.netlify/functions/send-club-push';
            const headers = { 'Content-Type': 'application/json' };
            if (window.CdsanAdminApiAuth && window.CdsanAdminApiAuth.getAdminAuthHeaders) {
                Object.assign(headers, await window.CdsanAdminApiAuth.getAdminAuthHeaders());
            }
            const res = await fetch(fnUrl, {
                method: 'POST',
                headers,
                body: JSON.stringify({
                    title: message.title,
                    body: message.content || message.message,
                    targetRoles: message.targetRoles,
                    targetTeams: message.targetTeams || [],
                    urgent: message.priority === 'high' || message.type === 'urgent',
                    broadcastId: message.broadcastId,
                    type: message.type
                })
            });
            const data = await res.json().catch(() => ({}));
            if (!res.ok || !data.ok) {
                throw new Error(data.error || 'No se pudo enviar el push al móvil');
            }
            return data;
        }

        function clearMessageForm() {
            document.getElementById('messageTitle').value = '';
            document.getElementById('messageContent').value = '';
            document.getElementById('messageType').value = 'general';
            resetMessageRecipientChecks();
            resetMessageTeamChecks();
            resetMessageSendMode();
            clearMessageAttachmentInput();
        }

        // Enviar mensaje push desde administración
        async function sendAdminPushMessage() {
            try {
                const title = document.getElementById('messageTitle').value.trim();
                const content = document.getElementById('messageContent').value.trim();
                const type = document.getElementById('messageType').value;
                const recipients = getSelectedMessageRecipients();
                const targetTeams = getSelectedMessageTeams();
                const sendMode = getMessageSendMode();
                const scheduledLocal = document.getElementById('messageScheduledAt')?.value || '';
                
                if (!title || !content) {
                    alert('❌ Por favor, completa el título y contenido del mensaje');
                    return;
                }
                if (!recipients.length) {
                    alert('❌ Selecciona al menos un grupo de destinatarios');
                    return;
                }

                let scheduledAtIso = null;
                if (sendMode === 'scheduled') {
                    if (!scheduledLocal) {
                        alert('❌ Indica fecha y hora para el recordatorio programado');
                        return;
                    }
                    const when = new Date(scheduledLocal);
                    if (isNaN(when.getTime())) {
                        alert('❌ Fecha u hora no válida');
                        return;
                    }
                    if (when.getTime() <= Date.now() + 60000) {
                        alert('❌ El recordatorio debe ser al menos 1 minuto en el futuro');
                        return;
                    }
                    scheduledAtIso = when.toISOString();
                }
                
                const currentAdmin = JSON.parse(localStorage.getItem('currentAdmin') || '{}');
                const sentAt = new Date().toISOString();
                const broadcastId = 'MSG_ADMIN_' + Date.now();
                
                const message = {
                    id: broadcastId,
                    broadcastId: broadcastId,
                    clientMessageId: broadcastId,
                    title: title,
                    content: content,
                    message: content,
                    type: type,
                    recipients: recipients,
                    targetTeams: targetTeams,
                    team: targetTeams.length ? targetTeams.join(',') : 'all',
                    targetRoles: mapPushRecipientsToTargetRoles(recipients),
                    senderId: currentAdmin.id || 'ADMIN_CDSANABRIACF',
                    senderName: currentAdmin.name || 'Administrador CDSANABRIACF',
                    senderType: 'admin',
                    sentAt: sendMode === 'scheduled' ? null : sentAt,
                    timestamp: sendMode === 'scheduled' ? scheduledAtIso : sentAt,
                    scheduledAt: scheduledAtIso,
                    sendMode: sendMode,
                    deliveryStatus: sendMode === 'scheduled' ? 'pending' : 'sent',
                    category: 'announcement',
                    priority: type === 'urgent' ? 'high' : 'medium',
                    broadcast: true,
                    status: sendMode === 'scheduled' ? 'scheduled' : 'sent',
                    appScope: 'cdsanabriacf'
                };

                const fileInput = document.getElementById('messageAttachmentFile');
                if (fileInput && fileInput.files && fileInput.files[0]) {
                    if (!window.ClubNotificationUpload || typeof window.ClubNotificationUpload.upload !== 'function') {
                        alert('❌ Subida de archivos no disponible');
                        return;
                    }
                    const attachment = await window.ClubNotificationUpload.upload(fileInput.files[0], broadcastId);
                    message.attachmentUrl = attachment.url;
                    message.attachmentType = attachment.contentType;
                    message.attachmentName = attachment.name;
                }
                
                const messages = JSON.parse(localStorage.getItem('pushMessages') || '[]');
                messages.push(message);
                localStorage.setItem('pushMessages', JSON.stringify(messages));
                await persistRecordToFirebase('pushMessages', 'notifications', message);

                let pushResult = null;
                if (sendMode === 'manual') {
                    try {
                        pushResult = await dispatchClubPushNotification(message);
                    } catch (pushErr) {
                        console.warn('Push móvil:', pushErr);
                    }
                }
                
                clearMessageForm();
                cancelAddMessage();
                
                const pushInfo = sendMode === 'scheduled'
                    ? '\n⏰ Programado para: ' + new Date(scheduledAtIso).toLocaleString('es-ES')
                    : (pushResult
                        ? '\n📱 Push móvil: ' + (pushResult.sent || 0) + ' dispositivo(s)'
                        : '\n📱 Push móvil: no enviado (revisa sesión admin o despliegue Netlify con funciones)');
                alert(
                    (sendMode === 'scheduled' ? '✅ Recordatorio programado\n\n' : '✅ Mensaje enviado exitosamente\n\n') +
                    '📱 "' + title + '"\n👥 ' + formatRecipientsLabel(recipients) +
                    '\n⚽ ' + formatTeamsLabel(targetTeams) + pushInfo +
                    '\n⏰ ' + new Date().toLocaleString()
                );
                
                // Actualizar historial y estadísticas
                loadAdminMessagesHistory();
                updateMessageCounts();
                
            } catch (error) {
                console.error('❌ Error enviando mensaje:', error);
                alert('❌ Error al enviar el mensaje. Inténtalo de nuevo.');
            }
        }

