        function escapeHtmlExport(value) {
            return String(value == null ? '' : value)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;');
        }

        function formatExportDate(value) {
            if (!value) return '';
            try {
                const d = new Date(value);
                return isNaN(d.getTime()) ? String(value) : d.toLocaleDateString('es-ES');
            } catch (e) {
                return String(value);
            }
        }

        function memberStatusExportLabel(status) {
            const s = String(status || '').toLowerCase();
            if (s === 'active' || s === 'activo') return 'Activo';
            if (s === 'pending_validation' || s === 'pending' || s === 'pendiente') return 'Pendiente';
            if (s === 'expired' || s === 'caducado') return 'Caducado';
            if (s === 'inactive' || s === 'inactivo') return 'Inactivo';
            return status || '';
        }

        function memberMatchesExportStatusFilter(member, statusFilter) {
            if (!statusFilter || statusFilter === 'all') return true;
            const m = typeof normalizeClubMember === 'function' ? normalizeClubMember(member) : member;
            const s = String(m.status || m.estado || '').toLowerCase();
            if (statusFilter === 'active') return s === 'active' || s === 'activo' || s === 'activa';
            if (statusFilter === 'paid') return m.pagado === true || s === 'active' || s === 'activo';
            if (statusFilter === 'pending') return s === 'pending' || s === 'pending_validation' || s === 'pendiente';
            if (statusFilter === 'pending_renewal') return isMemberPendingRenewal(m);
            if (statusFilter === 'pending_new') return isMemberPendingNewAlta(m);
            if (statusFilter === 'expired') {
                return s === 'expired' || s === 'caducado' || s === 'expirado' || isMemberExpired(m);
            }
            if (statusFilter === 'inactive') return s === 'inactive' || s === 'inactivo';
            return true;
        }

        function memberPaymentMethodExportLabel(m) {
            const method = String(m.paymentMethod || m.metodoPago || m.offlinePaymentChannel || '').toLowerCase();
            if (method.indexOf('bizum') >= 0 || method.indexOf('redsys_bizum') >= 0) return 'Bizum';
            if (method.indexOf('redsys') >= 0 || method.indexOf('card') >= 0 || method.indexOf('tarjeta') >= 0) return 'Tarjeta';
            if (method === 'efectivo' || method.indexOf('cash') >= 0) return 'Efectivo';
            if (method === 'tpv') return 'TPV manual';
            if (method.indexOf('transfer') >= 0 || method === 'transferencia') return 'Transferencia';
            return method || '';
        }

