        function collectClubListExportRows(listType, options) {
            const opts = options || {};
            if (listType === 'jugadores') {
                if (typeof window.PlayerExport !== 'undefined' && window.PlayerExport.collectExportRows) {
                    return window.PlayerExport.collectExportRows(opts);
                }
                let items = JSON.parse(localStorage.getItem('clubPlayers') || '[]');
                if (opts.category && opts.category !== 'all') {
                    if (window.ClubPlayerMemberSync && window.ClubPlayerMemberSync.playerMatchesCategoryFilter) {
                        items = items.filter(function (p) {
                            return window.ClubPlayerMemberSync.playerMatchesCategoryFilter(p, opts.category);
                        });
                    } else {
                        items = items.filter((p) => String(p.category || p.categoria || '') === opts.category);
                    }
                }
                return items.map(mapPlayerExportRow);
            }
            if (listType === 'socios') {
                let items = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                if (opts.status && opts.status !== 'all') {
                    items = items.filter((m) => memberMatchesExportStatusFilter(m, opts.status));
                }
                return items.map(mapSocioExportRow);
            }
            if (listType === 'amigos') {
                let items = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                if (opts.status && opts.status !== 'all') {
                    items = items.filter(function (a) {
                        return memberMatchesExportStatusFilter(a, opts.status);
                    });
                }
                return items.map(mapAmigoExportRow);
            }
            if (listType === 'entrenadores') {
                let items = JSON.parse(localStorage.getItem('clubCoaches') || '[]');
                if (opts.status && opts.status !== 'all') {
                    items = items.filter((c) => memberMatchesExportStatusFilter(c, opts.status));
                }
                return items.map(mapCoachExportRow);
            }
            if (listType === 'directiva') {
                return JSON.parse(localStorage.getItem('clubBoard') || '[]').map(mapBoardExportRow);
            }
            return [];
        }

        function getExportRowsHeaders(rows) {
            if (!rows.length) return [];
            return Object.keys(rows[0]);
        }

        function buildExportTableHtml(title, headers, rows) {
            const head = headers.map((h) => `<th>${escapeHtmlExport(h)}</th>`).join('');
            const body = rows
                .map((row) => {
                    const cells = headers.map((h) => `<td>${escapeHtmlExport(row[h])}</td>`).join('');
                    return `<tr>${cells}</tr>`;
                })
                .join('');
            return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escapeHtmlExport(title)}</title>
<style>body{font-family:Arial,sans-serif;padding:16px;} .wrap{overflow-x:auto;} table{border-collapse:collapse;min-width:100%;font-size:11px;}
th,td{border:1px solid #ccc;padding:5px 7px;text-align:left;white-space:nowrap;} th{background:#1e3a8a;color:#fff;position:sticky;top:0;}
@media print{body{padding:8px;} th,td{font-size:9px;padding:4px;}}</style></head>
<body><h1>${escapeHtmlExport(title)}</h1><p>Generado: ${escapeHtmlExport(new Date().toLocaleString('es-ES'))} · Registros: ${rows.length}</p>
<div class="wrap"><table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div></body></html>`;
        }

        /** PDF A4 / Word: ficha vertical (campo debajo de campo). Excel sigue en tabla horizontal. */
        async function resolveClubEscudoDataUri() {
            try {
                const raw = localStorage.getItem('clubLogo');
                if (raw && raw !== 'null' && raw !== 'undefined') {
                    const parsed = JSON.parse(raw);
                    if (parsed && parsed.dataUrl && String(parsed.dataUrl).startsWith('data:')) {
                        return String(parsed.dataUrl);
                    }
                    if (parsed && parsed.url && String(parsed.url).startsWith('data:')) {
                        return String(parsed.url);
                    }
                }
            } catch (_) {}
            const candidates = [
                'assets/escudo-cdsanabriacf.png',
                'assets/escudo-192.png',
                'assets/escudo-512.png',
                'escudo-192.png'
            ];
            for (let i = 0; i < candidates.length; i++) {
                try {
                    const res = await fetch(candidates[i], { cache: 'force-cache' });
                    if (!res.ok) continue;
                    const blob = await res.blob();
                    const dataUri = await new Promise(function (resolve, reject) {
                        const fr = new FileReader();
                        fr.onload = function () {
                            resolve(fr.result);
                        };
                        fr.onerror = reject;
                        fr.readAsDataURL(blob);
                    });
                    if (dataUri) return dataUri;
                } catch (_) {}
            }
            return '';
        }

        function buildExportFichaVerticalHtml(title, headers, rows, escudoDataUri, groups) {
            function buildFichasBlock(fichaRows) {
                return (fichaRows || []).map(function (row, index) {
                    const nameParts = [row['Nombre'], row['Apellidos']].filter(function (v) {
                        return v != null && String(v).trim() !== '';
                    });
                    const subtitle = nameParts.length
                        ? nameParts.join(' ')
                        : row['Nº socio'] || row['Nº amigo/a'] || 'Registro ' + (index + 1);
                    const fieldRows = headers
                        .map(function (h) {
                            const raw = row[h];
                            const display = raw == null || String(raw).trim() === '' ? '—' : String(raw);
                            return (
                                '<tr><th scope="row">' +
                                escapeHtmlExport(h) +
                                '</th><td>' +
                                escapeHtmlExport(display) +
                                '</td></tr>'
                            );
                        })
                        .join('');
                    return (
                        '<section class="ficha">' +
                        '<h2 class="ficha-title">' +
                        escapeHtmlExport(subtitle) +
                        '</h2>' +
                        '<table class="ficha-table"><tbody>' +
                        fieldRows +
                        '</tbody></table></section>'
                    );
                }).join('');
            }

            const exportGroups =
                groups && groups.length > 1
                    ? groups
                    : [{ label: null, rows: rows || [] }];
            const totalRows = exportGroups.reduce(function (sum, g) {
                return sum + (g.rows ? g.rows.length : 0);
            }, 0);
            const escudo = escudoDataUri ? String(escudoDataUri) : '';
            const escudoTag = escudo
                ? '<img src="' + escudo + '" alt="CD Sanabria CF" class="escudo-img">'
                : '';
            const metaLine =
                'Generado: ' +
                escapeHtmlExport(new Date().toLocaleString('es-ES')) +
                ' · Registros: ' +
                totalRows;
            const fichas = exportGroups
                .map(function (group) {
                    const block = buildFichasBlock(group.rows || []);
                    if (!group.label) return block;
                    return (
                        '<section class="category-block">' +
                        '<h2 class="category-heading">' +
                        escapeHtmlExport(group.label) +
                        '</h2>' +
                        block +
                        '</section>'
                    );
                })
                .join('');
            const wmBlock = escudo
                ? '<div class="wm-escudo" aria-hidden="true">' + escudoTag + '</div>'
                : '';
            const headerBlock =
                '<header class="header-brand">' +
                (escudo ? '<div class="header-escudo">' + escudoTag + '</div>' : '') +
                '<div class="header-text"><h1>' +
                escapeHtmlExport(title) +
                '</h1><p class="meta">' +
                metaLine +
                '</p></div></header>';
            return (
                '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>' +
                escapeHtmlExport(title) +
                '</title><style>' +
                '@page{size:A4 portrait;margin:12mm 14mm;}' +
                'body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#1e293b;line-height:1.45;margin:0;padding:14mm 14mm 12mm;position:relative;}' +
                '.wm-escudo{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:0;pointer-events:none;opacity:0.1;}' +
                '.wm-escudo .escudo-img{width:240px;height:240px;object-fit:contain;}' +
                '.doc-content{position:relative;z-index:1;}' +
                '.header-brand{display:flex;align-items:center;gap:14px;margin:0 0 20px;padding-bottom:12px;border-bottom:2px solid #1e3a8a;}' +
                '.header-escudo{flex-shrink:0;width:64px;height:64px;}' +
                '.header-escudo .escudo-img{width:64px;height:64px;object-fit:contain;}' +
                'h1{font-size:16pt;color:#1e3a8a;margin:0 0 4px;}' +
                '.meta{font-size:9.5pt;color:#64748b;margin:0;}' +
                '.category-block{margin:0 0 28px;page-break-inside:avoid;}' +
                '.category-heading{font-size:14pt;color:#1e3a8a;margin:24px 0 16px;padding:8px 0;border-bottom:3px solid #1e3a8a;}' +
                '.category-block:first-of-type .category-heading{margin-top:0;}' +
                '.ficha{margin:0 0 20px;padding:0 0 16px;border-bottom:2px solid #e2e8f0;page-break-inside:avoid;}' +
                '.ficha:last-child{border-bottom:none;margin-bottom:0;}' +
                '.ficha-title{font-size:13pt;color:#1e3a8a;margin:0 0 10px;font-weight:700;}' +
                '.ficha-table{width:100%;border-collapse:collapse;table-layout:fixed;}' +
                '.ficha-table th{text-align:left;vertical-align:top;width:36%;padding:7px 12px 7px 0;font-weight:600;color:#475569;border-bottom:1px solid #f1f5f9;}' +
                '.ficha-table td{vertical-align:top;padding:7px 0;border-bottom:1px solid #f1f5f9;word-wrap:break-word;white-space:normal;overflow-wrap:anywhere;}' +
                '@media print{.category-block{page-break-before:auto;}.category-heading{page-break-after:avoid;}.ficha{page-break-after:always;}.ficha:last-child{page-break-after:auto;}.wm-escudo{opacity:0.08;}}' +
                '</style></head><body>' +
                wmBlock +
                '<div class="doc-content">' +
                headerBlock +
                fichas +
                '</div></body></html>'
            );
        }

        function excelSheetNameFromLabel(label, usedNames) {
            const base = String(label || 'Listado')
                .replace(/[\\/*?:\[\]]/g, ' ')
                .trim()
                .substring(0, 28) || 'Listado';
            let name = base;
            let n = 2;
            while (usedNames.has(name)) {
                const suffix = ' ' + n;
                name = base.substring(0, Math.max(1, 31 - suffix.length)) + suffix;
                n += 1;
            }
            usedNames.add(name);
            return name;
        }

        async function exportDatasetToExcelGrouped(headers, groups, filename) {
            const ok = await ensureScriptLoaded(
                'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js',
                'XLSX'
            );
            if (!ok || !window.XLSX) {
                alert('❌ No se pudo cargar Excel. Comprueba la conexión.');
                return false;
            }
            const wb = window.XLSX.utils.book_new();
            const usedNames = new Set();
            (groups || []).forEach(function (group) {
                if (!group.rows || !group.rows.length) return;
                const ws = window.XLSX.utils.json_to_sheet(group.rows, { header: headers });
                const sheetName = excelSheetNameFromLabel(group.label || 'Listado', usedNames);
                window.XLSX.utils.book_append_sheet(wb, ws, sheetName);
            });
            if (!wb.SheetNames.length) {
                const ws = window.XLSX.utils.json_to_sheet([], { header: headers });
                window.XLSX.utils.book_append_sheet(wb, ws, 'Listado');
            }
            const buf = window.XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
            downloadBlobFile(
                buf,
                filename.endsWith('.xlsx') ? filename : `${filename}.xlsx`,
                'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            );
            return true;
        }

        async function exportDatasetToExcel(headers, rows, filename) {
            const ok = await ensureScriptLoaded(
                'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js',
                'XLSX'
            );
            if (!ok || !window.XLSX) {
                alert('❌ No se pudo cargar Excel. Comprueba la conexión.');
                return false;
            }
            const ws = window.XLSX.utils.json_to_sheet(rows, { header: headers });
            const wb = window.XLSX.utils.book_new();
            window.XLSX.utils.book_append_sheet(wb, ws, 'Listado');
            const buf = window.XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
            downloadBlobFile(
                buf,
                filename.endsWith('.xlsx') ? filename : `${filename}.xlsx`,
                'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            );
            return true;
        }

        async function exportDatasetToWord(title, headers, rows, filename, groups) {
            const escudo = await resolveClubEscudoDataUri();
            const html = buildExportFichaVerticalHtml(title, headers, rows, escudo, groups);
            downloadBlobFile(
                '\ufeff' + html,
                filename.endsWith('.doc') ? filename : `${filename}.doc`,
                'application/msword;charset=utf-8;'
            );
            return true;
        }

        async function exportDatasetToPdf(title, headers, rows, filename, groups) {
            const escudo = await resolveClubEscudoDataUri();
            const html = buildExportFichaVerticalHtml(title, headers, rows, escudo, groups);
            const w = window.open('', '_blank');
            if (!w) {
                alert('Permite ventanas emergentes y usa Imprimir → Guardar como PDF.');
                return false;
            }
            w.document.open();
            w.document.write(html);
            w.document.close();
            w.document.title = filename.replace(/\.[^.]+$/, '');
            w.focus();
            setTimeout(() => {
                try {
                    w.print();
                } catch (e) {
                    console.warn(e);
                }
            }, 400);
            return true;
        }

        async function exportClubList(listType, format, options) {
            try {
                const meta = CLUB_LIST_EXPORT_META[listType];
                if (!meta) {
                    alert('❌ Tipo de listado no reconocido');
                    return false;
                }
                const opts = { ...(options || {}) };
                if (listType === 'jugadores') {
                    const extra = getPlayerExportFilterOptions();
                    if (!opts.category) opts.category = extra.category;
                    if (!opts.season) opts.season = extra.season;
                    if (!opts.payment) opts.payment = extra.payment;
                }
                if (listType === 'socios') {
                    const stEl =
                        document.getElementById('exportMemberStatus') ||
                        document.getElementById('memberStatusFilter');
                    if (stEl && !opts.status) opts.status = stEl.value;
                }
                if (listType === 'amigos') {
                    const stEl = document.getElementById('friendStatusFilter');
                    if (stEl && !opts.status) opts.status = stEl.value;
                }
                if (listType === 'entrenadores') {
                    const stEl =
                        document.getElementById('exportCoachStatus') ||
                        document.getElementById('coachStatusFilter');
                    if (stEl && !opts.status) opts.status = stEl.value;
                }

                let playerExportGroups = null;
                let rows = collectClubListExportRows(listType, opts);
                if (
                    listType === 'jugadores' &&
                    typeof window.PlayerExport !== 'undefined' &&
                    window.PlayerExport.collectExportGroups
                ) {
                    playerExportGroups = window.PlayerExport.collectExportGroups(opts);
                    rows = [];
                    playerExportGroups.forEach(function (g) {
                        rows.push.apply(rows, g.rows || []);
                    });
                }
                if (!rows.length) {
                    alert('❌ No hay registros para exportar con los filtros seleccionados');
                    return false;
                }

                const headers =
                    listType === 'jugadores' &&
                    typeof window.PlayerExport !== 'undefined' &&
                    window.PlayerExport.getExportHeaders
                        ? window.PlayerExport.getExportHeaders()
                        : getExportRowsHeaders(rows);
                const date = new Date().toISOString().split('T')[0];
                const base = `${meta.filePrefix}_${date}`;
                const fmt = String(format || 'xlsx').toLowerCase();
                const formats = fmt === 'all' ? ['xlsx', 'word', 'pdf'] : [fmt];
                const usePlayerCategoryGroups =
                    listType === 'jugadores' &&
                    playerExportGroups &&
                    playerExportGroups.length > 1;

                for (const f of formats) {
                    if (f === 'xlsx' || f === 'excel') {
                        if (usePlayerCategoryGroups) {
                            await exportDatasetToExcelGrouped(headers, playerExportGroups, `${base}.xlsx`);
                        } else {
                            await exportDatasetToExcel(headers, rows, `${base}.xlsx`);
                        }
                        addToExportHistory(`${base}.xlsx`);
                    } else if (f === 'word' || f === 'doc') {
                        await exportDatasetToWord(
                            meta.title,
                            headers,
                            rows,
                            `${base}.doc`,
                            usePlayerCategoryGroups ? playerExportGroups : null
                        );
                        addToExportHistory(`${base}.doc`);
                    } else if (f === 'pdf') {
                        await exportDatasetToPdf(
                            meta.title,
                            headers,
                            rows,
                            `${base}.pdf`,
                            usePlayerCategoryGroups ? playerExportGroups : null
                        );
                        addToExportHistory(`${base}.pdf`);
                    } else if (f === 'csv') {
                        downloadCSV(convertToCSV(rows, headers), `${base}.csv`);
                    }
                }

                const fmtLabel =
                    formats.length > 1
                        ? 'Excel, Word y PDF'
                        : formats[0] === 'xlsx'
                          ? 'Excel'
                          : formats[0] === 'word'
                            ? 'Word'
                            : formats[0] === 'pdf'
                              ? 'PDF'
                              : formats[0];
                alert(`✅ ${meta.title}\n\n📊 ${rows.length} registros\n📁 Formato: ${fmtLabel}`);
                return true;
            } catch (error) {
                console.error('❌ Error exportando listado:', error);
                alert('❌ Error al exportar. Inténtalo de nuevo.');
                return false;
            }
        }

        async function exportarDatosEspecificos(tipo) {
            const map = {
                socios: 'socios',
                jugadores: 'jugadores',
                amigos: 'amigos',
                entrenadores: 'entrenadores',
                directiva: 'directiva',
                eventos: null
            };
            if (tipo === 'todo') {
                const types = ['jugadores', 'socios', 'amigos', 'directiva', 'entrenadores'];
                for (let i = 0; i < types.length; i++) {
                    await exportClubList(types[i], 'xlsx');
                    await new Promise((r) => setTimeout(r, 400));
                }
                return true;
            }
            if (tipo === 'eventos') {
                return exportEvents();
            }
            const listType = map[tipo];
            if (!listType) return false;
            return exportClubList(listType, 'xlsx');
        }

        // Agregar al historial de exportaciones
        function addToExportHistory(filename) {
            try {
                const history = JSON.parse(localStorage.getItem('exportHistory') || '[]');
                const exportRecord = {
                    id: Date.now(),
                    filename: filename,
                    date: new Date().toISOString(),
                    admin: JSON.parse(localStorage.getItem('currentAdmin') || '{}').name || 'Administrador'
                };
                
                history.unshift(exportRecord);
                
                // Mantener solo los últimos 20 registros
                if (history.length > 20) {
                    history.splice(20);
                }
                
                localStorage.setItem('exportHistory', JSON.stringify(history));
                loadExportHistory();
                
            } catch (error) {
                console.error('❌ Error guardando historial:', error);
            }
        }

        // Cargar historial de exportaciones
        function loadExportHistory() {
            try {
                const history = JSON.parse(localStorage.getItem('exportHistory') || '[]');
                const historyElement = document.getElementById('exportHistory');
                
                if (history.length === 0) {
                    historyElement.innerHTML = '<p style="text-align: center; color: #6c757d;">No hay exportaciones recientes</p>';
                    return;
                }

                let html = '<div style="display: grid; gap: 10px;">';
                
                history.forEach(record => {
                    html += `
                        <div style="background: #f8f9fa; padding: 15px; border-radius: 8px; border-left: 4px solid #059669;">
                            <div style="display: flex; justify-content: space-between; align-items: center;">
                                <div>
                                    <strong style="color: #1e3a8a;">📄 ${record.filename}</strong>
                                    <div style="font-size: 0.8rem; color: #666; margin-top: 5px;">
                                        👤 ${record.admin} | ⏰ ${new Date(record.date).toLocaleString()}
                                    </div>
                                </div>
                            </div>
                        </div>
                    `;
                });

                html += '</div>';
                historyElement.innerHTML = html;

            } catch (error) {
                console.error('❌ Error cargando historial:', error);
                document.getElementById('exportHistory').innerHTML = '<p style="text-align: center; color: #dc2626;">Error al cargar el historial</p>';
            }
        }

