        // ===== NUEVAS FUNCIONES DE GESTIÓN AVANZADA =====

        function getAdminDeleteRole() {
            try {
                const currentAdmin = JSON.parse(localStorage.getItem('currentAdmin') || '{}');
                if (currentAdmin.isSuperAdmin || currentAdmin.role === 'super_admin') return 'super_admin';
            } catch (_) {}
            return 'admin';
        }

        function clearClubCollectionLocally(collectionKey) {
            const empty = [];
            if (collectionKey === 'members') {
                syncMembersLocalStorage(empty);
                return;
            }
            if (collectionKey === 'players') {
                if (typeof window.syncClubPlayersLocal === 'function') {
                    window.syncClubPlayersLocal(empty);
                } else {
                    const json = JSON.stringify(empty);
                    ['clubPlayers', 'players', 'jugadores'].forEach((k) => localStorage.setItem(k, json));
                }
                return;
            }
            if (collectionKey === 'player_applications' || collectionKey === 'clubPlayerApplications') {
                localStorage.setItem('clubPlayerApplications', JSON.stringify(empty));
            }
        }

        const PURGE_ALLOWED_COLLECTION_KEYS = new Set(['members', 'players', 'player_applications']);

        async function purgeFirestoreCollection(collectionKey) {
            if (!PURGE_ALLOWED_COLLECTION_KEYS.has(collectionKey)) {
                throw new Error('Colección no permitida para borrado masivo: ' + collectionKey);
            }
            if (typeof window.getDocuments !== 'function' || typeof window.deleteDocument !== 'function') {
                return { deleted: 0, skipped: true };
            }
            const role = getAdminDeleteRole();
            const docs = await window.getDocuments(collectionKey);
            let deleted = 0;
            for (const item of docs || []) {
                const id = item && item.id;
                if (!id) continue;
                try {
                    await window.deleteDocument(collectionKey, id, role);
                    deleted += 1;
                } catch (err) {
                    console.warn('No se pudo eliminar', collectionKey, id, err);
                }
            }
            return { deleted };
        }

        function refreshDbCountersAfterPurge() {
            if (typeof updateDatabaseStats === 'function') updateDatabaseStats();
            if (typeof updateMemberCounts === 'function') updateMemberCounts();
            if (typeof updateDashboardCounts === 'function') updateDashboardCounts();
            if (typeof loadSystemStatistics === 'function') loadSystemStatistics();
            if (typeof loadMembers === 'function') loadMembers();
            if (typeof loadPlayers === 'function') loadPlayers();
            const nextEl = document.getElementById('nextMemberNumber');
            if (nextEl && window.ClubMemberNumbers) {
                nextEl.textContent = String(window.ClubMemberNumbers.REGULAR_MIN);
            }
        }

        async function limpiarSocios() {
            const msg = '⚠️ ELIMINAR TODOS LOS SOCIOS\n\nSe borrarán todos los socios en Firebase y en este dispositivo.\nEl próximo número automático volverá a ser 000051.\n\n¿Continuar?';
            if (!confirm(msg)) return;
            const statusEl = document.getElementById('dbCleanStatus');
            if (statusEl) {
                statusEl.innerHTML = '<p style="color:#666;">Eliminando socios…</p>';
                statusEl.style.display = 'block';
            }
            try {
                const result = await purgeFirestoreCollection('members');
                clearClubCollectionLocally('members');
                refreshDbCountersAfterPurge();
                const text = '✅ Socios eliminados: ' + (result.deleted || 0) + ' en Firebase. Contadores a cero en el panel.';
                if (statusEl) statusEl.innerHTML = '<p style="color:#059669;">' + text + '</p>';
                else alert(text);
            } catch (error) {
                console.error('Error limpiando socios:', error);
                const errText = '❌ Error limpiando socios: ' + (error.message || error);
                if (statusEl) statusEl.innerHTML = '<p style="color:#dc2626;">' + errText + '</p>';
                else alert(errText);
            }
        }
        window.limpiarSocios = limpiarSocios;

        async function limpiarBaseDeDatos() {
            const msg = '⚠️ RESETEAR SOCIOS Y JUGADORES\n\nSe borrarán PERMANENTEMENTE:\n• Todos los socios\n• Todos los jugadores\n• Solicitudes de nuevo jugador/a\n\nEn Firebase y en este dispositivo.\n\n¿Continuar?';
            if (!confirm(msg)) return;
            if (!confirm('Última confirmación: ¿Seguro que quieres dejar socios y jugadores a cero?')) return;
            const statusEl = document.getElementById('dbCleanStatus');
            if (statusEl) {
                statusEl.innerHTML = '<p style="color:#666;">Eliminando socios, jugadores y solicitudes…</p>';
                statusEl.style.display = 'block';
            }
            try {
                const membersR = await purgeFirestoreCollection('members');
                const playersR = await purgeFirestoreCollection('players');
                const appsR = await purgeFirestoreCollection('player_applications');
                clearClubCollectionLocally('members');
                clearClubCollectionLocally('players');
                clearClubCollectionLocally('player_applications');
                refreshDbCountersAfterPurge();
                const text = '✅ Reset completado.\nSocios: ' + (membersR.deleted || 0) +
                    ' · Jugadores: ' + (playersR.deleted || 0) +
                    ' · Solicitudes: ' + (appsR.deleted || 0) +
                    '\n\nContadores del panel a cero.';
                if (statusEl) statusEl.innerHTML = '<p style="color:#059669;white-space:pre-line;">' + text + '</p>';
                else alert(text);
            } catch (error) {
                console.error('Error en reset de base de datos:', error);
                const errText = '❌ Error: ' + (error.message || error);
                if (statusEl) statusEl.innerHTML = '<p style="color:#dc2626;">' + errText + '</p>';
                else alert(errText);
            }
        }
        window.limpiarBaseDeDatos = limpiarBaseDeDatos;

