        // Función para cerrar sesión y cerrar el panel de administración
        async function logout() {
            try {
                const confirmed = confirm('¿Estás seguro de que quieres cerrar el panel de administración?');
                if (!confirmed) {
                    return;
                }

                if (window.AdminSession && window.AdminSession.clearStoredAdminSession) {
                    window.AdminSession.clearStoredAdminSession();
                } else {
                    localStorage.removeItem('currentAdmin');
                    localStorage.removeItem('adminUser');
                    localStorage.removeItem('isAdmin');
                    localStorage.removeItem('isSuperAdmin');
                }

                if (window.firebaseAuth && !window.firebaseAuth.isSimulation) {
                    try {
                        const { signOut } = await import('https://www.gstatic.com/firebasejs/10.12.3/firebase-auth.js');
                        await signOut(window.firebaseAuth);
                    } catch (e) {
                        console.warn('signOut admin:', e);
                    }
                }

                console.log('🚪 Sesión de administrador cerrada');
                closeAdminPanelWindow();
            } catch (error) {
                console.error('❌ Error cerrando sesión:', error);
                window.location.replace('index.html');
            }
        }

