        // Función para actualizar la vista previa del mensaje
        function updateLogoMessagePreview() {
            const message = document.getElementById('logoMessage').value;
            const color = document.getElementById('logoMessageColor').value;
            const preview = document.getElementById('logoMessagePreview');
            
            if (preview) {
                preview.textContent = message || 'Vista previa del mensaje';
                preview.style.color = color;
            }
        }
        
        // Función para guardar el mensaje del logo
        function saveLogoMessage() {
            try {
                const message = document.getElementById('logoMessage').value.trim();
                const color = document.getElementById('logoMessageColor').value;
                
                const logoMessageData = {
                    message: message,
                    color: color,
                    savedAt: new Date().toISOString(),
                    savedBy: JSON.parse(localStorage.getItem('currentAdmin') || '{}').email || 'admin'
                };
                
                // Guardar en localStorage
                localStorage.setItem('cdsanabriacfLogoMessage', JSON.stringify(logoMessageData));
                
                alert('✅ Mensaje del logo guardado exitosamente\n\n📝 Mensaje: ' + (message || 'Sin mensaje') + '\n🎨 Color: ' + color);
                
                console.log('💬 Mensaje del logo guardado:', logoMessageData);
                
            } catch (error) {
                console.error('❌ Error guardando mensaje del logo:', error);
                alert('❌ Error al guardar el mensaje del logo. Inténtalo de nuevo.');
            }
        }
        
        // Función para restablecer el mensaje del logo
        function resetLogoMessage() {
            if (confirm('¿Estás seguro de que quieres restablecer el mensaje del logo a los valores por defecto?')) {
                document.getElementById('logoMessage').value = '';
                document.getElementById('logoMessageColor').value = '#333333';
                
                // Eliminar del localStorage
                localStorage.removeItem('cdsanabriacfLogoMessage');
                
                // Actualizar vista previa
                updateLogoMessagePreview();
                
                alert('✅ Mensaje del logo restablecido a los valores por defecto');
                console.log('🔄 Mensaje del logo restablecido');
            }
        }
        
        // Función para cargar el mensaje del logo guardado
        function loadLogoMessage() {
            try {
                const savedData = localStorage.getItem('cdsanabriacfLogoMessage');
                if (savedData) {
                    const logoMessageData = JSON.parse(savedData);
                    
                    document.getElementById('logoMessage').value = logoMessageData.message || '';
                    document.getElementById('logoMessageColor').value = logoMessageData.color || '#333333';
                    
                    // Actualizar vista previa
                    updateLogoMessagePreview();
                    
                    console.log('💬 Mensaje del logo cargado:', logoMessageData);
                }
            } catch (error) {
                console.error('❌ Error cargando mensaje del logo:', error);
            }
        }
        
        // Añadir event listeners para actualizar la vista previa en tiempo real
        document.addEventListener('DOMContentLoaded', function() {
            const messageInput = document.getElementById('logoMessage');
            const colorInput = document.getElementById('logoMessageColor');
            
            if (messageInput) {
                messageInput.addEventListener('input', updateLogoMessagePreview);
            }
            
            if (colorInput) {
                colorInput.addEventListener('input', updateLogoMessagePreview);
            }
            
            // Cargar mensaje guardado al cargar la página
            loadLogoMessage();
        });

        // === FUNCIONES DE ESTADÍSTICAS Y MONITOREO ===
        
        // Función para cargar estadísticas del sistema
        function loadSystemStatistics() {
            try {
                const sociosRaw = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const socios = typeof dedupeMembersList === 'function' ? dedupeMembersList(sociosRaw) : sociosRaw;
                const amigos = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                const jugadores = JSON.parse(localStorage.getItem('clubPlayers') || '[]');
                const entrenadores = JSON.parse(localStorage.getItem('clubCoaches') || '[]');
                const eventos = JSON.parse(localStorage.getItem('clubEvents') || localStorage.getItem('events') || '[]');
                
                document.getElementById('totalSocios').textContent = socios.length;
                document.getElementById('totalAmigos').textContent = amigos.length;
                document.getElementById('totalJugadores').textContent = jugadores.length;
                document.getElementById('totalEntrenadores').textContent = entrenadores.length;
                document.getElementById('totalEventos').textContent = eventos.length;
                
                let sociosActivos = 0;
                let sociosPendientes = 0;
                socios.forEach((s) => {
                    const m = typeof normalizeClubMember === 'function' ? normalizeClubMember(s) : s;
                    if (m.status === 'active') sociosActivos++;
                    else if (m.status === 'pending_validation') sociosPendientes++;
                });
                
                const amigosActivos = amigos.filter((a) => {
                    const e = String(a.estado || a.status || '').toLowerCase();
                    return e === 'activo' || e === 'active';
                }).length;
                
                document.getElementById('sociosActivos').textContent = sociosActivos;
                document.getElementById('sociosPendientes').textContent = sociosPendientes;
                document.getElementById('amigosActivos').textContent = amigosActivos;
                
                const syncStatus = window.persistenceManager && window.persistenceManager.isInitialized ? '✅ Activa' : '⚠️ Local';
                document.getElementById('estadoSincronizacion').textContent = syncStatus;
                
                const firebaseOk = typeof window.firebaseDb !== 'undefined' && window.firebaseDb;
                const firebaseLabel = firebaseOk ? '✅ OK' : '⚠️ No cargado';
                const elSync = document.getElementById('estadoFirebaseSync');
                const elHealth = document.getElementById('estadoFirebaseHealth');
                if (elSync) elSync.textContent = firebaseLabel;
                if (elHealth) elHealth.textContent = firebaseLabel;
                
                document.getElementById('ultimaActualizacion').textContent = new Date().toLocaleString();
                
                console.log('📊 Estadísticas del sistema cargadas');
                
            } catch (error) {
                console.error('❌ Error cargando estadísticas:', error);
            }
        }
        
        // Función para realizar backup automático (copia completa en localStorage cada 5 min)
        function performAutomaticBackup() {
            try {
                const backupData = {
                    timestamp: new Date().toISOString(),
                    payload: buildClubBackupPayload()
                };
                localStorage.setItem('backup_' + Date.now(), JSON.stringify(backupData));
                const backupKeys = Object.keys(localStorage).filter((key) => /^backup_\d+$/.test(key));
                if (backupKeys.length > 10) {
                    backupKeys.sort().slice(0, backupKeys.length - 10).forEach((key) => localStorage.removeItem(key));
                }
                console.log('💾 Backup automático en localStorage (payload completo)');
            } catch (error) {
                console.error('❌ Error en backup automático:', error);
            }
        }
        
        // Función para monitorear el sistema
        function monitorSystemHealth() {
            try {
                const healthStatus = {
                    localStorage: typeof Storage !== 'undefined',
                    persistenceManager: window.persistenceManager && window.persistenceManager.isInitialized,
                    firebase: typeof firebaseConfig !== 'undefined',
                    timestamp: new Date().toISOString()
                };
                
                // Actualizar estado de salud del sistema
                document.getElementById('estadoLocalStorage').textContent = healthStatus.localStorage ? '✅ OK' : '❌ Error';
                document.getElementById('estadoPersistence').textContent = healthStatus.persistenceManager ? '✅ OK' : '⚠️ No usado (opcional)';
                const fbOk = typeof window.firebaseDb !== 'undefined' && window.firebaseDb;
                const fbTxt = fbOk ? '✅ OK' : '❌ Error';
                const elSync = document.getElementById('estadoFirebaseSync');
                const elHealth = document.getElementById('estadoFirebaseHealth');
                if (elSync) elSync.textContent = fbTxt;
                if (elHealth) elHealth.textContent = fbTxt;
                
                console.log('🔍 Monitoreo del sistema completado');
                
            } catch (error) {
                console.error('❌ Error en monitoreo del sistema:', error);
            }
        }
        
        // Función para exportar estadísticas
        function exportStatistics() {
            try {
                const statistics = {
                    timestamp: new Date().toISOString(),
                    usuarios: {
                        socios: JSON.parse(localStorage.getItem('clubMembers') || '[]').length,
                        amigos: JSON.parse(localStorage.getItem('clubFriends') || '[]').length,
                        jugadores: JSON.parse(localStorage.getItem('clubPlayers') || '[]').length,
                        entrenadores: JSON.parse(localStorage.getItem('clubCoaches') || '[]').length
                    },
                    eventos: JSON.parse(localStorage.getItem('clubEvents') || '[]').length,
                    sistema: {
                        localStorage: typeof Storage !== 'undefined',
                        persistenceManager: window.persistenceManager && window.persistenceManager.isInitialized,
                        firebase: typeof firebaseConfig !== 'undefined'
                    }
                };
                
                const dataStr = JSON.stringify(statistics, null, 2);
                const dataBlob = new Blob([dataStr], {type: 'application/json'});
                const url = URL.createObjectURL(dataBlob);
                const link = document.createElement('a');
                link.href = url;
                link.download = 'estadisticas-cdsanabriacf-' + new Date().toISOString().split('T')[0] + '.json';
                link.click();
                URL.revokeObjectURL(url);
                
                console.log('📊 Estadísticas exportadas');
                
            } catch (error) {
                console.error('❌ Error exportando estadísticas:', error);
            }
        }
        
        // Actualizar estadísticas cada 30 segundos
        setInterval(() => {
            if (document.getElementById('estadisticas').style.display !== 'none') {
                loadSystemStatistics();
                monitorSystemHealth();
            }
        }, 30000);
        
        // Backup automático cada 5 minutos
        setInterval(performAutomaticBackup, 300000);
        
        // ===== FUNCIONES DE SINCRONIZACIÓN CON FIREBASE =====
        
        async function sincronizarSociosConBackend() {
            try {
                console.log('🔄 Iniciando sincronización de socios con Firebase...');
                
                // Obtener socios del localStorage
                const socios = JSON.parse(localStorage.getItem('members') || '[]');
                
                if (socios.length === 0) {
                    alert('❌ No hay socios para sincronizar. Primero crea algunos socios.');
                    return;
                }
                
                // Sincronizar cada socio con Firebase
                let sincronizados = 0;
                let errores = 0;
                
                for (const socio of socios) {
                    try {
                        // Usar la función createDocument de firebase-config.js
                        await window.createDocument('members', {
                            ...socio,
                            lastSync: new Date().toISOString(),
                            source: 'admin-panel'
                        });
                        sincronizados++;
                    } catch (error) {
                        console.error('❌ Error sincronizando socio:', socio.name, error);
                        errores++;
                    }
                }
                
                const mensaje = `✅ Sincronización completada:\n\n📊 Socios sincronizados: ${sincronizados}\n❌ Errores: ${errores}\n\nLos datos ya están en la nube para web y móvil.`;
                alert(mensaje);
                
                console.log('🔄 Sincronización completada:', { sincronizados, errores });
                
            } catch (error) {
                console.error('❌ Error en sincronización:', error);
                alert('❌ Error durante la sincronización. Revisa la consola para más detalles.');
            }
        }
        
