        async function auditarSincronizacionModulos() {
            try {
                const requiredFns = ['getDocuments', 'createDocument', 'updateDocument', 'deleteDocument'];
                const missing = requiredFns.filter((fn) => typeof window[fn] !== 'function');
                if (missing.length) {
                    alert('❌ La nube no está disponible en este panel.\n\nFaltan funciones: ' + missing.join(', '));
                    return;
                }

                const modules = [
                    { label: 'Socios', localKey: 'clubMembers', collection: 'members' },
                    { label: 'Amigos', localKey: 'clubFriends', collection: 'friends' },
                    { label: 'Jugadores', localKey: 'clubPlayers', collection: 'players' },
                    { label: 'Entrenadores', localKey: 'clubCoaches', collection: 'coaches' },
                    { label: 'Directiva', localKey: 'clubBoard', collection: 'board' },
                    { label: 'Equipos', localKey: 'clubTeams', collection: 'teams' },
                    { label: 'Eventos', localKey: 'clubEvents', collection: 'events' },
                    { label: 'Encuentros', localKey: 'encuentros', collection: 'encuentros' },
                    { label: 'Calendario', localKey: 'clubCalendarEvents', collection: 'calendarEvents' },
                    { label: 'Competiciones', localKey: 'clubCompetitions', collection: 'competitions' },
                    { label: 'Documentos', localKey: 'clubDocuments', collection: 'documents' },
                    { label: 'Publicidad', localKey: 'clubPublicidad', collection: 'ads' },
                    { label: 'Publicidad colaboradores', localKey: 'clubAdvertisements', collection: 'ads_collaborators' },
                    { label: 'Push mensajes', localKey: 'pushMessages', collection: 'notifications' }
                ];

                const rows = [];
                for (const m of modules) {
                    const local = JSON.parse(localStorage.getItem(m.localKey) || '[]');
                    const localCount = Array.isArray(local) ? local.length : 0;
                    let remoteCount = 0;
                    let ok = true;
                    let note = '';
                    try {
                        const remote = await window.getDocuments(m.collection);
                        remoteCount = Array.isArray(remote) ? remote.length : 0;
                        if (localCount !== remoteCount) {
                            note = 'conteo distinto';
                        }
                    } catch (e) {
                        ok = false;
                        note = String(e?.message || e);
                    }
                    rows.push({
                        modulo: m.label,
                        local: localCount,
                        firebase: remoteCount,
                        estado: ok ? (note ? '⚠️' : '✅') : '❌',
                        detalle: note || 'OK'
                    });
                }

                let resumen = '🧪 Auditoría de sincronización por módulo\n\n';
                rows.forEach((r) => {
                    resumen += `${r.estado} ${r.modulo}: local ${r.local} / nube ${r.firebase}${r.detalle !== 'OK' ? ` (${r.detalle})` : ''}\n`;
                });

                const hasErrors = rows.some((r) => r.estado === '❌');
                const hasWarnings = rows.some((r) => r.estado === '⚠️');
                resumen += '\n' + (hasErrors ? '❌ Hay módulos con error de acceso a la nube.' : hasWarnings ? '⚠️ Hay diferencias de conteo (puede haber sincronización pendiente).' : '✅ Todos los módulos auditados responden y están alineados por conteo.');

                try { console.table(rows); } catch (_) {}
                alert(resumen);
            } catch (error) {
                console.error('❌ Error en auditoría de módulos:', error);
                alert('❌ Error al ejecutar la auditoría de módulos.');
            }
        }

        function mostrarResumenReconciliacion(results) {
            let resumen = '🛠️ Reconciliación completada\n\n';
            results.forEach((r) => {
                resumen += `${r.estado} ${r.modulo}: ${r.detalle}\n`;
            });
            const hasErr = results.some((r) => r.estado === '❌');
            const hasWarn = results.some((r) => r.estado === '🔄');
            resumen +=
                '\n' +
                (hasErr
                    ? '❌ Algunos módulos no pudieron reconciliarse.'
                    : hasWarn
                      ? '⚠️ Algunos módulos se han sincronizado (revisa el detalle).'
                      : '✅ Módulos reconciliados correctamente.');
            try {
                console.table(results);
            } catch (_) {}
            showAdminCopyableDialog('Reconciliación completada', resumen);
        }

        function readLocalModuleArray(localKey) {
            const fallbackKeys = {
                clubMembers: ['clubMembers', 'socios', 'members', 'allMembers'],
                clubFriends: ['clubFriends', 'amigos', 'friends', 'allFriends'],
                clubPlayers: ['clubPlayers', 'jugadores', 'players'],
                clubCoaches: ['clubCoaches', 'entrenadores', 'coaches'],
                clubBoard: ['clubBoard', 'directiva', 'board'],
                clubTeams: ['clubTeams', 'equipos', 'teams'],
                clubEvents: ['clubEvents', 'events', 'allEvents'],
                encuentros: ['encuentros'],
                clubCalendarEvents: ['clubCalendarEvents', 'calendarEvents'],
                clubCompetitions: ['clubCompetitions', 'competitions'],
                clubDocuments: ['clubDocuments', 'documents'],
                clubPublicidad: ['clubPublicidad', 'publicidad', 'ads'],
                pushMessages: ['pushMessages', 'notifications', 'clubNotifications']
            };
            const keys = fallbackKeys[localKey] || [localKey];
            for (let i = 0; i < keys.length; i++) {
                try {
                    const list = JSON.parse(localStorage.getItem(keys[i]) || '[]');
                    if (Array.isArray(list) && list.length > 0) return list;
                } catch (_) {}
            }
            try {
                const list = JSON.parse(localStorage.getItem(localKey) || '[]');
                return Array.isArray(list) ? list : [];
            } catch (_) {
                return [];
            }
        }

        function formatReconcileDetail(m, localCount, remoteCount, syncRes) {
            if (localCount === remoteCount) {
                return 'alineado (' + localCount + ' en local y nube)';
            }
            if (localCount > remoteCount) {
                const synced = syncRes && syncRes.synced != null ? syncRes.synced : 0;
                const failed = syncRes && syncRes.failed != null ? syncRes.failed : 0;
                let detail = 'subidos a nube (' + synced + ' de ' + localCount + ')';
                if (failed > 0) detail += ' · fallos: ' + failed;
                if (syncRes && syncRes.error) detail += ' · ' + syncRes.error;
                if (syncRes && syncRes.errors && syncRes.errors.length) detail += ' · ' + syncRes.errors[0];
                return detail;
            }
            return 'descargados desde nube (' + remoteCount + ' · local tenía ' + localCount + ')';
        }

        async function reconciliarModulosConFirebase(options) {
            const opts = options || {};
            try {
                if (typeof window.getDocuments !== 'function' || typeof window.syncLocalArrayKeyToFirebase !== 'function') {
                    if (!opts.fromAutoOpen) {
                        alert('❌ La nube no está disponible para reconciliación en este panel.');
                    }
                    return;
                }

                const modules = [
                    { label: 'Socios', localKey: 'clubMembers', collection: 'members' },
                    { label: 'Amigos', localKey: 'clubFriends', collection: 'friends' },
                    { label: 'Jugadores', localKey: 'clubPlayers', collection: 'players' },
                    { label: 'Entrenadores', localKey: 'clubCoaches', collection: 'coaches' },
                    { label: 'Directiva', localKey: 'clubBoard', collection: 'board' },
                    { label: 'Equipos', localKey: 'clubTeams', collection: 'teams' },
                    { label: 'Eventos', localKey: 'clubEvents', collection: 'events' },
                    { label: 'Encuentros', localKey: 'encuentros', collection: 'encuentros' },
                    { label: 'Calendario', localKey: 'clubCalendarEvents', collection: 'calendarEvents' },
                    { label: 'Competiciones', localKey: 'clubCompetitions', collection: 'competitions' },
                    { label: 'Documentos', localKey: 'clubDocuments', collection: 'documents' },
                    { label: 'Publicidad', localKey: 'clubPublicidad', collection: 'ads' },
                    { label: 'Push mensajes', localKey: 'pushMessages', collection: 'notifications' }
                ];

                const results = [];
                for (const m of modules) {
                    try {
                        const remote = await window.getDocuments(m.collection);
                        const remoteCount = Array.isArray(remote) ? remote.length : 0;
                        const local = readLocalModuleArray(m.localKey);
                        const localCount = local.length;
                        let syncRes = null;

                        if (localCount > remoteCount) {
                            syncRes = await window.syncLocalArrayKeyToFirebase(m.localKey);
                        } else if (localCount < remoteCount && typeof window.syncClubMembersLocal === 'function' && m.localKey === 'clubMembers') {
                            window.syncClubMembersLocal(remote);
                        } else if (localCount < remoteCount && typeof window.syncClubPlayersLocal === 'function' && m.localKey === 'clubPlayers') {
                            window.syncClubPlayersLocal(remote);
                        } else if (localCount < remoteCount && typeof window.syncClubFriendsLocal === 'function' && m.localKey === 'clubFriends') {
                            window.syncClubFriendsLocal(remote);
                        }

                        const failed = syncRes && syncRes.failed ? syncRes.failed : 0;
                        const hasError = !!(syncRes && (syncRes.error || failed > 0));
                        results.push({
                            modulo: m.label,
                            estado: localCount === remoteCount ? '✅' : hasError ? '❌' : '🔄',
                            detalle: formatReconcileDetail(m.label, localCount, remoteCount, syncRes)
                        });
                    } catch (e) {
                        results.push({ modulo: m.label, estado: '❌', detalle: String(e?.message || e) });
                    }
                }

                // Refresco final para traer versión remota consolidada.
                if (typeof window.syncFromFirebase === 'function') {
                    await window.syncFromFirebase();
                }

                mostrarResumenReconciliacion(results);
            } catch (error) {
                console.error('❌ Error en reconciliación de módulos:', error);
                showAdminCopyableDialog('Error en reconciliación', '❌ Error al reconciliar módulos con la nube.\n\n' + (error.message || String(error)));
            }
        }

        async function intentarReconciliacionAutomaticaAlAbrir() {
            try {
                if (sessionStorage.getItem('cdsanabria_auto_reconcile_done') === '1') return;
                sessionStorage.setItem('cdsanabria_auto_reconcile_done', '1');
                await reconciliarModulosConFirebase({ fromAutoOpen: true });
            } catch (error) {
                console.warn('Reconciliación automática al abrir falló:', error);
            }
        }

        async function intentarPasoTemporadaAutomaticoAlAbrir() {
            try {
                if (sessionStorage.getItem('cdsanabria_auto_season_prompted') === '1') return;
                sessionStorage.setItem('cdsanabria_auto_season_prompted', '1');

                const pref = localStorage.getItem('cdsanabria_auto_season_pass_on_open'); // enabled | disabled | null
                let shouldRun = pref === 'enabled';

                if (pref !== 'enabled' && pref !== 'disabled') {
                    const yJug = (typeof ClubAccounting !== 'undefined' && ClubAccounting.getCuotaEdadReferenciaAnio)
                        ? ClubAccounting.getCuotaEdadReferenciaAnio()
                        : new Date().getFullYear();
                    shouldRun = confirm(
                        '🔁 Paso de temporada al abrir\n\n' +
                        '¿Quieres revisar y actualizar automáticamente categorías de jugadores por edad al abrir el panel?\n\n' +
                        'Usa la edad al 31 de mayo de ' + yJug + ' (misma referencia que cuotas de socios).'
                    );

                    if (shouldRun) {
                        const rememberOn = confirm('¿Activar este paso de temporada automático en futuras aperturas?');
                        if (rememberOn) localStorage.setItem('cdsanabria_auto_season_pass_on_open', 'enabled');
                    } else {
                        const rememberOff = confirm('¿No volver a mostrar este aviso?');
                        if (rememberOff) localStorage.setItem('cdsanabria_auto_season_pass_on_open', 'disabled');
                    }
                }

                if (!shouldRun) return;
                const sy = (typeof ClubAccounting !== 'undefined' && ClubAccounting.getCuotaEdadReferenciaAnio)
                    ? ClubAccounting.getCuotaEdadReferenciaAnio()
                    : new Date().getFullYear();
                await aplicarPasoTemporadaJugadores({ seasonYear: sy, silent: true });
            } catch (error) {
                console.warn('Paso de temporada automático al abrir falló:', error);
            }
        }
        
        // Función para eliminar completamente todos los datos de ejemplo
        async function eliminarDatosEjemplo() {
            if (confirm('⚠️ ELIMINACIÓN COMPLETA DE DATOS DE EJEMPLO\n\nEsto eliminará PERMANENTEMENTE:\n• Todos los datos de prueba de este dispositivo\n• Todos los datos de prueba en la nube\n• Datos con emails @test.com, @example.com\n• Registros con nombres "Test", "Sincronización", "undefined"\n\n¿Continuar?')) {
                try {
                    console.log('🧹 Iniciando eliminación completa de datos de ejemplo...');
                    
                    // 1. Limpiar localStorage completamente
                    const socios = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                    const amigos = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                    
                    // Filtrar datos de ejemplo
                    const sociosLimpios = socios.filter(s => 
                        !s.email?.includes('@test.com') && 
                        !s.email?.includes('@example.com') &&
                        !s.nombre?.includes('Sincronización') &&
                        !s.nombre?.includes('Test') &&
                        !s.nombre?.includes('undefined') &&
                        s.nombre && s.nombre.trim() !== '' &&
                        s.apellidos && s.apellidos.trim() !== ''
                    );
                    
                    const amigosLimpios = amigos.filter(a => 
                        !a.email?.includes('@test.com') && 
                        !a.email?.includes('@example.com') &&
                        !a.nombre?.includes('Sincronización') &&
                        !a.nombre?.includes('Test') &&
                        !a.nombre?.includes('undefined') &&
                        a.nombre && a.nombre.trim() !== '' &&
                        a.apellidos && a.apellidos.trim() !== ''
                    );
                    
                    // Guardar datos limpios en localStorage
                    localStorage.setItem('clubMembers', JSON.stringify(sociosLimpios));
                    localStorage.setItem('clubFriends', JSON.stringify(amigosLimpios));
                    localStorage.setItem('members', JSON.stringify(sociosLimpios));
                    localStorage.setItem('friends', JSON.stringify(amigosLimpios));
                    localStorage.setItem('socios', JSON.stringify(sociosLimpios));
                    localStorage.setItem('amigos', JSON.stringify(amigosLimpios));
                    
                    // 2. Eliminar de Firebase si está disponible
                    if (window.getDocuments && window.createDocument) {
                        try {
                            // Obtener todos los documentos de Firebase
                            const sociosFirebase = await window.getDocuments('members');
                            const amigosFirebase = await window.getDocuments('friends');
                            
                            console.log('🗑️ Limpiando Firebase de datos de ejemplo...');
                            
                            // Sobrescribir con datos limpios
                            if (sociosLimpios.length > 0) {
                                for (const socio of sociosLimpios) {
                                    await window.createDocument('members', socio);
                                }
                            }
                            
                            if (amigosLimpios.length > 0) {
                                for (const amigo of amigosLimpios) {
                                    await window.createDocument('friends', amigo);
                                }
                            }
                            
                        } catch (error) {
                            console.warn('⚠️ Error limpiando Firebase:', error);
                        }
                    }
                    
                    // 3. Limpiar datos de respaldo y caché
                    localStorage.removeItem('offlineQueue');
                    localStorage.removeItem('backupData');
                    localStorage.removeItem('syncData');
                    localStorage.removeItem('testData');
                    
                    const eliminados = (socios.length - sociosLimpios.length) + (amigos.length - amigosLimpios.length);
                    
                    alert(`✅ ELIMINACIÓN COMPLETA EXITOSA\n\n📊 Eliminados: ${eliminados} registros de prueba\n📊 Mantenidos: ${sociosLimpios.length} socios, ${amigosLimpios.length} amigos\n\n🔄 Los datos se han limpiado de:\n• Este dispositivo\n• La nube\n• Caché local`);
                    
                    console.log('🧹 Eliminación completa finalizada:', { 
                        eliminados, 
                        sociosLimpios: sociosLimpios.length, 
                        amigosLimpios: amigosLimpios.length 
                    });
                    
                    // Recargar la lista de socios en el panel
                    if (typeof loadMembers === 'function') {
                        loadMembers();
                    }
                    
                    // Recargar la página después de un momento
                    setTimeout(() => {
                        window.location.reload();
                    }, 2000);
                    
                } catch (error) {
                    console.error('❌ Error en eliminación completa:', error);
                    alert('❌ Error durante la eliminación. Revisa la consola para más detalles.');
                }
            }
        }
        
        // Función para mostrar pestañas
        function showTab(tabName) {
            if (window.AdminOrganizerAccess && !window.AdminOrganizerAccess.guardTabAccess(tabName)) {
                tabName = 'competiciones';
            }
            // Ocultar todas las pestañas
            const allTabs = document.querySelectorAll('.tab-content');
            allTabs.forEach(tab => tab.style.display = 'none');
            
            // Remover clase activa de todos los botones
            const allButtons = document.querySelectorAll('.nav-tab');
            allButtons.forEach(btn => btn.classList.remove('active'));
            
            // Mostrar la pestaña seleccionada
            const selectedTab = document.getElementById(tabName);
            if (selectedTab) {
                selectedTab.style.display = 'block';
            }
            
            // Activar el botón correspondiente
            const activeButton = document.querySelector(`[onclick="showTab('${tabName}')"]`);
            if (activeButton) {
                activeButton.classList.add('active');
            }
            
            // Cargar estadísticas si es la pestaña de estadísticas
            if (tabName === 'estadisticas') {
                loadSystemStatistics();
                monitorSystemHealth();
            }

            if (tabName === 'multimedia') {
                if (typeof loadMultimediaAdminPanel === 'function') loadMultimediaAdminPanel();
            }

            if (tabName === 'jugadores') {
                if (typeof loadInscriptionAdminForm === 'function') loadInscriptionAdminForm();
                if (typeof loadPlayerExportAdminForm === 'function') loadPlayerExportAdminForm();
                if (typeof refreshPlayerExportSeasonSelects === 'function') refreshPlayerExportSeasonSelects();
            }

            try { if (typeof refreshCuotaRenewalBanner === 'function') refreshCuotaRenewalBanner(); } catch (_) {}

            if (tabName === 'contabilidad') {
                loadContabilidadPanel();
            }

            if (tabName === 'tienda') {
                if (typeof cargarConfiguracionTienda === 'function') cargarConfiguracionTienda();
                if (typeof initPaygoldPanel === 'function') initPaygoldPanel();
            }

            if (tabName === 'publicidad') {
                if (typeof loadColaboradorFormConfigAdmin === 'function') loadColaboradorFormConfigAdmin();
            }

            if (tabName === 'eventos' || tabName === 'competiciones') {
                if (typeof loadTorneoPreinscripcionesAdmin === 'function') loadTorneoPreinscripcionesAdmin();
            }

            if (tabName === 'competiciones') {
                if (typeof loadCompetitionsList === 'function') loadCompetitionsList();
            }

            if (tabName === 'dashboard' && window.SiteUpdateMode && typeof window.SiteUpdateMode.refreshUi === 'function') {
                window.SiteUpdateMode.refreshUi();
            }

            if (tabName === 'basedatos' && typeof updateDatabaseStats === 'function') {
                updateDatabaseStats();
            }
            
            console.log('📋 Pestaña cambiada a:', tabName);
        }
        
        // Función para limpiar automáticamente datos de ejemplo al cargar
        function limpiarDatosEjemploAutomatico() {
            try {
                console.log('🧹 Limpieza automática de datos de ejemplo...');
                
                // Obtener todos los datos
                const socios = JSON.parse(localStorage.getItem('clubMembers') || '[]');
                const amigos = JSON.parse(localStorage.getItem('clubFriends') || '[]');
                
                // Filtrar datos de ejemplo
                const sociosLimpios = socios.filter(s => 
                    !s.email?.includes('@test.com') && 
                    !s.email?.includes('@example.com') &&
                    !s.nombre?.includes('Sincronización') &&
                    !s.nombre?.includes('Test') &&
                    !s.nombre?.includes('undefined') &&
                    s.nombre && s.nombre.trim() !== '' &&
                    s.apellidos && s.apellidos.trim() !== ''
                );
                
                const amigosLimpios = amigos.filter(a => 
                    !a.email?.includes('@test.com') && 
                    !a.email?.includes('@example.com') &&
                    !a.nombre?.includes('Sincronización') &&
                    !a.nombre?.includes('Test') &&
                    !a.nombre?.includes('undefined') &&
                    a.nombre && a.nombre.trim() !== '' &&
                    a.apellidos && a.apellidos.trim() !== ''
                );
                
                // Si hay datos de ejemplo, limpiarlos
                if (socios.length !== sociosLimpios.length || amigos.length !== amigosLimpios.length) {
                    // Guardar datos limpios
                    localStorage.setItem('clubMembers', JSON.stringify(sociosLimpios));
                    localStorage.setItem('clubFriends', JSON.stringify(amigosLimpios));
                    localStorage.setItem('members', JSON.stringify(sociosLimpios));
                    localStorage.setItem('friends', JSON.stringify(amigosLimpios));
                    localStorage.setItem('socios', JSON.stringify(sociosLimpios));
                    localStorage.setItem('amigos', JSON.stringify(amigosLimpios));
                    
                    const eliminados = (socios.length - sociosLimpios.length) + (amigos.length - amigosLimpios.length);
                    console.log(`🧹 Limpieza automática completada: ${eliminados} datos de ejemplo eliminados`);
                    
                    // Recargar la página para actualizar la interfaz
                    setTimeout(() => {
                        window.location.reload();
                    }, 1000);
                }
                
            } catch (error) {
                console.error('❌ Error en limpieza automática:', error);
            }
        }
        
